{"path":"shared/azdo.py","perm":"0644","sha":"d13fcec28224c49c5527cc2594821705c52570f6376bbfd47b943de5f3103e5d","data":"\"\"\"Azure DevOps \u5171\u7528\u5de5\u5177\uff1aPR URL \u89e3\u6790 + \u5e36 PAT/proxy \u7684 HTTP client\u3002\n\n\u8a2d\u8a08\u539f\u5247\uff1a\u9019\u88e1\u662f\u300c\u7b28\u300d\u7684\u4e00\u5c64 \u2014\u2014 \u4e0d import langfuse\u3001\u4e0d\u542b\u4efb\u4f55 review \u908f\u8f2f\u3002\n\u8a2d\u5b9a\uff1asettings().ado\uff08ADO_PAT \u5fc5\u586b\uff1bADO_VERIFY_SSL \u53ef\u70ba true/false \u6216 CA bundle \u8def\u5f91\uff09\u3002\nHTTPS_PROXY \u7b49\u6a19\u6e96 proxy \u8b8a\u6578\u7531 httpx trust_env \u81ea\u52d5\u5403\u3002\n\"\"\"\nfrom __future__ import annotations\n\nimport re\nfrom dataclasses import dataclass\nfrom urllib.parse import quote\n\nimport httpx\n\nfrom shared.settings import settings\n\nAPI_VERSION = \"7.1\"\n\n\n@dataclass(frozen=True)\nclass PrRef:\n    \"\"\"\u4e00\u689d PR \u7684\u5ea7\u6a19\u3002base_url \u5f62\u5982 https://dev.azure.com/{org}/{project}\n    \uff08on-prem \u5247\u662f https://server/{collection}/{project}\uff09\uff0crepo \u8207 pr_id \u81ea\u660e\u3002\"\"\"\n\n    base_url: str\n    repo: str\n    pr_id: int\n\n    @property\n    def repo_api(self) -> str:\n        return f\"{self.base_url}/_apis/git/repositories/{quote(self.repo)}\"\n\n    @property\n    def pr_api(self) -> str:\n        return f\"{self.repo_api}/pullRequests/{self.pr_id}\"\n\n\n_PR_URL_RE = re.compile(\n    r\"(?P<base>https?://[^\\s]+?)/_git/(?P<repo>[^/\\s]+)/pullrequest/(?P<id>\\d+)\",\n    re.IGNORECASE,\n)\n\n\ndef parse_pr_url(pr_url: str) -> PrRef:\n    \"\"\"\u652f\u63f4 dev.azure.com \u8207 on-prem Azure DevOps Server \u5169\u7a2e URL \u5f62\u614b\u3002\"\"\"\n    m = _PR_URL_RE.search(pr_url.strip())\n    if not m:\n        raise ValueError(\n            f\"\u7121\u6cd5\u89e3\u6790 PR URL\uff1a{pr_url!r}\uff08\u9810\u671f\u542b /_git/<repo>/pullrequest/<id>\uff09\"\n        )\n    return PrRef(base_url=m.group(\"base\"), repo=m.group(\"repo\"), pr_id=int(m.group(\"id\")))\n\n\ndef find_pr_url(text: str) -> str | None:\n    \"\"\"\u5f9e\u4efb\u610f\u6587\u5b57\uff08\u4f8b\u5982\u804a\u5929\u8a0a\u606f\uff09\u6488\u51fa\u7b2c\u4e00\u500b PR URL\u3002\"\"\"\n    m = _PR_URL_RE.search(text or \"\")\n    if not m:\n        return None\n    return f\"{m.group('base')}/_git/{m.group('repo')}/pullrequest/{m.group('id')}\"\n\n\ndef _verify() -> bool | str:\n    return settings().ado.verify_ssl\n\n\ndef client() -> httpx.Client:\n    pat = settings().ado.pat.get_secret_value()\n    if not pat:\n        raise RuntimeError(\"\u74b0\u5883\u8b8a\u6578 ADO_PAT \u672a\u8a2d\u5b9a\")\n    return httpx.Client(\n        auth=(\"\", pat),          # ADO \u7684 PAT \u8d70 basic auth\uff0cusername \u7559\u7a7a\n        trust_env=True,           # \u81ea\u52d5\u5403 HTTPS_PROXY / NO_PROXY\n        verify=_verify(),\n        timeout=httpx.Timeout(30.0),\n        headers={\"Accept\": \"application/json\"},\n    )\n\n\ndef get_json(c: httpx.Client, url: str, **params) -> dict:\n    params.setdefault(\"api-version\", API_VERSION)\n    r = c.get(url, params=params)\n    r.raise_for_status()\n    return r.json()\n\n\ndef get_text(c: httpx.Client, url: str, **params) -> str | None:\n    \"\"\"\u6293\u6a94\u6848\u5167\u5bb9\uff1b404\uff08\u8a72\u7248\u672c\u4e0d\u5b58\u5728\u6b64\u6a94\uff0c\u65b0\u589e/\u522a\u9664\u60c5\u5883\uff09\u56de None\u3002\"\"\"\n    params.setdefault(\"api-version\", API_VERSION)\n    r = c.get(url, params=params, headers={\"Accept\": \"text/plain\"})\n    if r.status_code == 404:\n        return None\n    r.raise_for_status()\n    return r.text\n"}
{"path":"shared/doctor.py","perm":"0644","sha":"0e928b8c43b47eabcb6b9e65cff420291f21276bc7369cc9e9150d37e39a6744","data":"\"\"\"doctor \u2014\u2014 \u628a RUNBOOK \u88e1\u6240\u6709\u300c\u624b\u52d5 HTTP \u63a2\u91dd / cat /proc / journalctl \u5224\u8b80\u300d\u6536\u6210\u4e00\u689d\u6307\u4ee4\u3002\n\n    python -m shared.doctor                  \u5168\u5957\u6aa2\u67e5\uff0c\u5370\u4e00\u5f35\u8868\n    python -m shared.doctor --pr-url <URL>   \u591a\u505a\u4e00\u4ef6\uff1a\u62ff ADO_PAT \u771f\u6253\u4e00\u689d PR \u7684 metadata\n    python -m shared.doctor --no-network     \u53ea\u770b\u8a2d\u5b9a\u3001\u4f9d\u8cf4\u3001\u76ee\u9304\u3001systemd\uff08CI / \u96e2\u7dda\u7528\uff09\n    python -m shared.doctor --json           \u6a5f\u5668\u53ef\u8b80\uff08\u65e5\u5f8c\u72c0\u614b\u9801\u76f4\u63a5\u5403\uff09\n\n\u9000\u51fa\u78bc\uff1a0 \u5168\u7da0\u6216\u53ea\u6709 WARN\uff1b1 \u81f3\u5c11\u4e00\u500b FAIL\uff1b2 \u8a2d\u5b9a\u672c\u8eab\u89e3\u6790\u4e0d\u904e\uff08\u5176\u4ed6\u6aa2\u67e5\u6c92\u958b\u8dd1\uff09\u3002\n\n\u5206\u5de5\uff1asettings.py \u7ba1\u300c\u503c\u5c0d\u4e0d\u5c0d\u300d\uff08\u578b\u5225\u3001\u7bc4\u570d\u3001\u4e92\u76f8\u77db\u76fe\uff09\uff0c\u9019\u88e1\u7ba1\u300c\u5916\u9762\u7684\u4e16\u754c\n\u914d\u4e0d\u914d\u5408\u300d\u2014\u2014\u76ee\u9304\u5728\u4e0d\u5728\u3001port \u6709\u6c92\u6709\u4eba\u807d\u3001PAT \u6253\u5f97\u901a\u55ce\u3001Langfuse \u6d3b\u8457\u55ce\u3002\n\u6bcf\u500b\u6aa2\u67e5\u90fd\u662f\u4e00\u500b\u56de\u50b3 Check \u7684\u7d14\u51fd\u5f0f\uff1b\u7db2\u8def\u8207 PATH \u7684\u63a2\u91dd\uff08_tcp_open / _http_get /\n_which / _run\uff09\u96c6\u4e2d\u5728\u4e00\u8655\u597d stub\uff0ctests/ \u5168\u90e8\u96e2\u7dda\u8dd1\u3002\n\n\u72c0\u614b\u8a9e\u610f\uff1a\n  OK    \u9019\u4e00\u9805\u7167\u8a2d\u5b9a\u904b\u4f5c\u4e2d\n  WARN  \u80fd\u8dd1\u4f46\u6709\u96b1\u60a3\uff08\u9078\u914d\u529f\u80fd\u6c92\u88dd\u3001\u820a\u540d\u5b57\u9084\u5728\u7528\u3001\u5c0d\u7167\u4e0d\u4e0a\uff09\n  FAIL  review \u4e00\u5b9a\u6703\u58de\u6216\u5df2\u7d93\u5728\u58de\uff08\u5fc5\u8981\u670d\u52d9\u4e0d\u5728\u3001PAT \u6253\u4e0d\u901a\u3001\u4f9d\u8cf4\u7f3a\uff09\n  SKIP  \u523b\u610f\u4e0d\u6aa2\u67e5\uff08\u529f\u80fd\u672a\u555f\u7528\u3001--no-network\u3001\u6c92\u7d66 --pr-url\uff09\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport shutil\nimport socket\nimport subprocess\nimport sys\nfrom dataclasses import asdict, dataclass\nfrom importlib import metadata\nfrom pathlib import Path\nfrom urllib.parse import urlparse\n\nfrom pydantic import ValidationError\n\nfrom shared import settings as S\n\nOK, WARN, FAIL, SKIP = \"OK\", \"WARN\", \"FAIL\", \"SKIP\"\n_RANK = {OK: 0, SKIP: 0, WARN: 1, FAIL: 2}\n\nTCP_TIMEOUT = 2.0\nHTTP_TIMEOUT = 5.0\n\n\n@dataclass\nclass Check:\n    group: str\n    name: str\n    status: str\n    detail: str = \"\"\n\n\n# ---------- \u63a2\u91dd\uff08tests \u4ee5 monkeypatch \u63db\u6389\uff09 ----------\n\ndef _which(binary: str) -> str | None:\n    return shutil.which(binary)\n\n\ndef _tcp_open(host: str, port: int, timeout: float = TCP_TIMEOUT) -> bool:\n    try:\n        with socket.create_connection((host, port), timeout=timeout):\n            return True\n    except OSError:\n        return False\n\n\ndef _http_get(url: str, *, auth: tuple[str, str] | None = None,\n              headers: dict | None = None, timeout: float = HTTP_TIMEOUT,\n              trust_env: bool = False) -> tuple[int | None, object, str]:\n    \"\"\"(status_code, json \u6216\u6587\u5b57, \u932f\u8aa4\u8a0a\u606f)\u3002\u9023\u4e0d\u4e0a \u2192 (None, None, \u539f\u56e0)\u3002\"\"\"\n    import httpx\n    try:\n        r = httpx.get(url, auth=auth, headers=headers or {}, timeout=timeout,\n                      trust_env=trust_env, follow_redirects=True)\n    except Exception as e:  # noqa: BLE001\n        return None, None, f\"{type(e).__name__}: {e}\"\n    try:\n        body: object = r.json()\n    except ValueError:\n        body = r.text\n    return r.status_code, body, \"\"\n\n\ndef _run(cmd: list[str], timeout: float = 10.0) -> tuple[int, str]:\n    try:\n        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)\n        return r.returncode, (r.stdout or r.stderr).strip()\n    except Exception as e:  # noqa: BLE001\n        return 127, f\"{type(e).__name__}: {e}\"\n\n\ndef _host_port(url: str) -> tuple[str, int] | None:\n    u = urlparse(url)\n    if not u.hostname:\n        return None\n    return u.hostname, u.port or (443 if u.scheme == \"https\" else 80)\n\n\ndef _git_head(path: Path) -> str:\n    rc, out = _run([\"git\", \"-C\", str(path), \"log\", \"-1\", \"--format=%h %cs\"])\n    return out if rc == 0 and out else \"not a git repo\"\n\n\n# ---------- \u5404\u7d44\u6aa2\u67e5 ----------\n\ndef check_settings() -> tuple[S.Settings | None, list[Check]]:\n    try:\n        S.reset()\n        s = S.settings()\n    except ValidationError as e:\n        bad = \"; \".join(f\"{'.'.join(map(str, err['loc']))}={err.get('input')!r}: {err['msg']}\"\n                        for err in e.errors())\n        return None, [Check(\"settings\", \"parse\", FAIL, bad)]\n    rows = S.show_rows(s)\n    from_env = sum(1 for r in rows if r[3] != \"default\")\n    out = [Check(\"settings\", \"parse\", OK,\n                 f\"{len(rows)} variables, {from_env} set from env, rest default\")]\n    out += [Check(\"settings\", \"smell\", WARN, w) for w in S.warnings_for(s)]\n    return s, out\n\n\n_REQUIRED_DISTS = (\"fastmcp\", \"langfuse\", \"openai\", \"fastapi\", \"uvicorn\",\n                   \"httpx\", \"pydantic\", \"pydantic-settings\")\n\n\ndef check_python(s: S.Settings) -> list[Check]:\n    out = [Check(\"python\", \"interpreter\", OK,\n                 f\"{sys.version.split()[0]} at {sys.executable}\")]\n    if sys.version_info < (3, 10):\n        out[0] = Check(\"python\", \"interpreter\", FAIL,\n                       f\"{sys.version.split()[0]} < 3.10\uff08v2 \u7528\u4e86 3.10+ \u8a9e\u6cd5\uff09\")\n    missing, have = [], []\n    for dist in _REQUIRED_DISTS:\n        try:\n            have.append(f\"{dist} {metadata.version(dist)}\")\n        except metadata.PackageNotFoundError:\n            missing.append(dist)\n    detail = \", \".join(have)\n    if missing:\n        detail = \"missing: \" + \", \".join(missing) + (\"; \" + detail if detail else \"\")\n    out.append(Check(\"python\", \"dependencies\", FAIL if missing else OK, detail))\n    for name, mode in ((\"semgrep\", s.static.semgrep), (\"ruff\", s.static.ruff)):\n        path = _which(name)\n        if mode == \"off\":\n            out.append(Check(\"python\", name, SKIP, f\"STATIC_{name.upper()}=off\"))\n        elif path:\n            rc, ver = _run([path, \"--version\"])\n            out.append(Check(\"python\", name, OK, f\"{ver.splitlines()[0] if ver else path}\"))\n        else:\n            out.append(Check(\"python\", name, WARN,\n                             f\"not on PATH\uff08STATIC_{name.upper()}={mode}\uff09\u2014\u2014 static \u6bb5\u6703\u8df3\u904e\uff1b\"\n                             \"systemd \u8dd1\u7684\u8a71\u78ba\u8a8d unit \u7684 PATH \u542b venv/bin\"))\n    return out\n\n\ndef check_paths(s: S.Settings) -> list[Check]:\n    out: list[Check] = []\n\n    r = s.repos.repos_root\n    if r is None:\n        out.append(Check(\"paths\", \"REPOS_ROOT\", SKIP, \"unset \u2014\u2014 review \u7167\u8dd1\uff0c\u4f46\u6c92\u6709 base \u4e0a\u4e0b\u6587\"))\n    elif not r.is_dir():\n        out.append(Check(\"paths\", \"REPOS_ROOT\", FAIL, f\"{r} \u4e0d\u5b58\u5728\"))\n    else:\n        clones = [d for d in sorted(r.iterdir()) if (d / \".git\").exists()]\n        others = [d.name for d in sorted(r.iterdir()) if d.is_dir() and not (d / \".git\").exists()]\n        detail = f\"{len(clones)} clone(s): \" + \", \".join(\n            f\"{d.name}@{_git_head(d).split()[0]}\" for d in clones[:6])\n        if len(clones) > 6:\n            detail += f\", +{len(clones) - 6}\"\n        if others:\n            detail += f\"\uff1b\u975e git \u76ee\u9304\u6703\u88ab repo-sync \u8df3\u904e\uff1a{', '.join(others[:4])}\"\n        out.append(Check(\"paths\", \"REPOS_ROOT\", OK if clones else WARN,\n                         detail if clones else f\"{r} \u5e95\u4e0b\u6c92\u6709\u4efb\u4f55 clone\"))\n\n    r = s.rules.root\n    if r is None:\n        out.append(Check(\"paths\", \"RULES_ROOT\", SKIP, \"unset \u2014\u2014 \u898f\u5247\u529f\u80fd\u505c\u7528\"))\n    elif not r.is_dir():\n        out.append(Check(\"paths\", \"RULES_ROOT\", FAIL, f\"{r} \u4e0d\u5b58\u5728\"))\n    else:\n        sub = r / s.rules.subdir\n        common = sub / s.rules.common_dir\n        n_md = len(list(sub.rglob(\"*.md\"))) if sub.is_dir() else 0\n        n_sg = len(list(r.rglob(\"*.semgrep.yml\"))) + len(list(r.rglob(\"*.semgrep.yaml\")))\n        status = OK if common.is_dir() and n_md else WARN\n        out.append(Check(\"paths\", \"RULES_ROOT\", status,\n                         f\"{_git_head(r)}; {n_md} rule md, {n_sg} semgrep rule file(s)\"\n                         + (\"\" if common.is_dir() else f\"; \u627e\u4e0d\u5230 {sub.name}/{s.rules.common_dir}/\"\n                            \"\uff08RULES_SUBDIR / RULES_COMMON_DIR \u5c0d\u4e0d\u4e0a\u76ee\u9304\uff09\")))\n\n    d = s.orchestrator.data_dir\n    try:\n        d.mkdir(parents=True, exist_ok=True)\n        probe = d / \".doctor-probe\"\n        probe.write_text(\"x\", encoding=\"utf-8\"); probe.unlink()\n        n_db = (d / \"reviews.db\").exists()\n        out.append(Check(\"paths\", \"DATA_DIR\", OK, f\"{d} \u53ef\u5beb\" + (\"\uff1breviews.db \u5b58\u5728\" if n_db else \"\uff1b\u5c1a\u7121 reviews.db\uff08\u7b2c\u4e00\u689d review \u6703\u5efa\uff09\")))\n    except OSError as e:\n        out.append(Check(\"paths\", \"DATA_DIR\", WARN, f\"{d} \u958b\u4e0d\u51fa\u4f86\uff08{type(e).__name__}\uff09\u2014\u2014 review \u6b77\u53f2\u505c\u7528\uff0creview \u7167\u8dd1\"))\n\n    r = s.knowledge.root\n    if r is None:\n        out.append(Check(\"paths\", \"KNOWLEDGE_ROOT\", SKIP, \"unset \u2014\u2014 K \u6bb5\u505c\u7528\"))\n    elif not r.is_dir():\n        out.append(Check(\"paths\", \"KNOWLEDGE_ROOT\", FAIL, f\"{r} \u4e0d\u5b58\u5728\"))\n    else:\n        pend = r / \"_pending\"\n        n_pend = len(list(pend.rglob(\"pr-*.json\"))) if pend.is_dir() else 0\n        pages = [p for p in r.rglob(\"*.md\") if not any(part.startswith(\"_\") for part in p.relative_to(r).parts)]\n        head = _git_head(r)\n        out.append(Check(\"paths\", \"KNOWLEDGE_ROOT\", OK if head != \"not a git repo\" else FAIL,\n                         f\"{head}; {len(pages)} page(s), {n_pend} pending draft(s)\"\n                         + (\"\" if head != \"not a git repo\" else \"\uff1bharvester \u662f\u552f\u4e00 commit \u8005\uff0c\u9019\u88e1\u5fc5\u9808\u662f git repo\")))\n    return out\n\n\ndef check_services(s: S.Settings, network: bool) -> list[Check]:\n    if not network:\n        return [Check(\"services\", \"all\", SKIP, \"--no-network\")]\n    out: list[Check] = []\n\n    code, body, err = _http_get(f\"{s.orchestrator.base_url}/healthz\")\n    if code == 200 and isinstance(body, dict) and body.get(\"ok\"):\n        out.append(Check(\"services\", \"orchestrator\", OK,\n                         f\"{s.orchestrator.base_url} (pipeline {body.get('pipeline', '?')})\"))\n        out += _job_checks(body.get(\"jobs\") or {}, s)\n    else:\n        out.append(Check(\"services\", \"orchestrator\", FAIL,\n                         f\"{s.orchestrator.base_url}/healthz \u2192 {code or err}\uff1b\"\n                         \"\u2460\u2462 \u8207\u6392\u7a0b\u90fd\u4f4f\u5728\u9019\u500b\u884c\u7a0b\u88e1\uff0c\u5b83\u4e0d\u5728 = \u5168\u90e8\u4e0d\u5728\"))\n\n    if not s.graph.enabled:\n        out.append(Check(\"services\", \"code graph \u2463\", SKIP,\n                         \"\u672a\u555f\u7528\" + (\"\" if not s.graph.tools_url else \"\uff08\u6709 URL \u4f46\u7f3a GRAPH_TOOL_BLAST\uff09\")))\n    else:\n        hp = _host_port(s.graph.tools_url or \"\")\n        ok = hp is not None and _tcp_open(*hp)\n        out.append(Check(\"services\", \"code graph \u2463\", OK if ok else FAIL,\n                         f\"{s.graph.tools_url}\" + (\"\" if ok else \" \u6c92\u4eba\u807d\uff1bpipeline \u6703\u512a\u96c5\u964d\u7d1a\u4f46\u6c92\u6709\u5f71\u97ff\u534a\u5f91\")))\n    return out\n\n\ndef _job_checks(jobs: dict, s: S.Settings) -> list[Check]:\n    \"\"\"/healthz \u56de\u4f86\u7684 jobs \u72c0\u614b \u2192 \u6bcf\u500b job \u4e00\u5217\uff08\u539f\u672c\u662f\u5169\u7d44 timer \u7684 is-active + journal\uff09\u3002\"\"\"\n    import time\n    out: list[Check] = []\n    if not jobs:\n        return [Check(\"jobs\", \"all\", WARN, \"/healthz \u6c92\u5e36 jobs \u6b04\u4f4d\uff08\u820a\u7248 orchestrator\uff1f\uff09\")]\n    for name, st in jobs.items():\n        if not st.get(\"enabled\"):\n            why = {\"repo-sync\": \"REPOS_ROOT \u672a\u8a2d\u6216 REPO_SYNC_INTERVAL_MIN=0\",\n                   \"harvest\": \"KNOWLEDGE_ROOT \u672a\u8a2d\u6216 HARVEST_INTERVAL_MIN=0\"}.get(name, \"off\")\n            out.append(Check(\"jobs\", name, SKIP, why))\n            continue\n        every = f\"\u6bcf {st.get('interval_min')} \u5206\"\n        if st.get(\"running\"):\n            out.append(Check(\"jobs\", name, OK, f\"{every}\uff1b\u6b63\u5728\u8dd1\"))\n        elif st.get(\"last_ok\") is None:\n            nxt = st.get(\"next_run\")\n            wait = f\"\uff0c{int(nxt - time.time())}s \u5f8c\u9996\u8dd1\" if nxt else \"\"\n            out.append(Check(\"jobs\", name, OK, f\"{every}\uff1b\u5c1a\u672a\u8dd1\u904e{wait}\"))\n        elif st.get(\"last_ok\"):\n            ago = int(time.time() - (st.get(\"last_end\") or time.time()))\n            out.append(Check(\"jobs\", name, OK, f\"{every}\uff1b\u4e0a\u6b21 {ago}s \u524d\u6210\u529f\uff0c{len(st.get('last_detail') or [])} \u9805\"))\n        else:\n            out.append(Check(\"jobs\", name, FAIL, f\"{every}\uff1b\u4e0a\u6b21\u5931\u6557\uff1a{st.get('last_error', '')[:160]}\"))\n    return out\n\n\ndef check_langfuse(s: S.Settings, network: bool) -> list[Check]:\n    if not network:\n        return [Check(\"langfuse\", \"all\", SKIP, \"--no-network\")]\n    host = s.langfuse.host.rstrip(\"/\")\n    code, _body, err = _http_get(f\"{host}/api/public/health\")\n    if code != 200:\n        return [Check(\"langfuse\", \"health\", FAIL,\n                      f\"{host}/api/public/health \u2192 {code or err}\uff1borchestrator \u662f\u552f\u4e00\u63a5\u5b83\u7684\u670d\u52d9\uff0c\"\n                      \"trace / prompt \u7248\u63a7 / eval \u5168\u90e8\u9760\u5b83\")]\n    out = [Check(\"langfuse\", \"health\", OK, host)]\n    pk, sk = s.langfuse.public_key, s.langfuse.secret_key.get_secret_value()\n    if not pk or not sk:\n        out.append(Check(\"langfuse\", \"keys\", WARN, \"LANGFUSE_PUBLIC_KEY / SECRET_KEY \u672a\u8a2d \u2014\u2014 SDK \u6703\u5728\u555f\u52d5\u6642\u62b1\u6028\"))\n        return out\n    code, body, err = _http_get(f\"{host}/api/public/projects\", auth=(pk, sk))\n    if code == 200:\n        names = [p.get(\"name\") for p in (body.get(\"data\") if isinstance(body, dict) else []) or [] if isinstance(p, dict)]\n        out.append(Check(\"langfuse\", \"keys\", OK, \"project: \" + (\", \".join(map(str, names)) or \"(unnamed)\")))\n    elif code in (401, 403):\n        out.append(Check(\"langfuse\", \"keys\", FAIL, f\"{code}\uff1akey \u5c0d\u4e0d\u4e0a\u9019\u500b host\"))\n    else:\n        out.append(Check(\"langfuse\", \"keys\", WARN, f\"/api/public/projects \u2192 {code or err}\uff08key \u7121\u6cd5\u9a57\u8b49\uff09\"))\n    return out\n\n\ndef check_llm(s: S.Settings, network: bool) -> list[Check]:\n    if not network:\n        return [Check(\"llm\", \"all\", SKIP, \"--no-network\")]\n    base = s.llm.base_url.rstrip(\"/\")\n    headers = {\"Authorization\": f\"Bearer {s.llm.api_key.get_secret_value()}\"}\n    code, body, err = _http_get(f\"{base}/models\", headers=headers, trust_env=True)\n    if code is None:\n        return [Check(\"llm\", \"gateway\", FAIL, f\"{base} \u9023\u4e0d\u4e0a\uff1a{err}\")]\n    if code != 200:\n        return [Check(\"llm\", \"gateway\", WARN,\n                      f\"{base}/models \u2192 {code}\uff08gateway \u53ef\u80fd\u4e0d\u652f\u63f4 /models\uff1bLLM_MODEL={s.llm.model} \u672a\u9a57\u8b49\uff09\")]\n    ids = [m.get(\"id\") for m in (body.get(\"data\") if isinstance(body, dict) else []) or [] if isinstance(m, dict)]\n    out = [Check(\"llm\", \"gateway\", OK, f\"{base}, {len(ids)} model(s)\")]\n    for label, model in ((\"LLM_MODEL\", s.llm.model),\n                         (\"LLM_MODEL_ADVERSARY\", s.llm.model_adversary),\n                         (\"LLM_MODEL_DIGEST\", s.llm.model_digest)):\n        if not model:\n            continue\n        if not ids:\n            out.append(Check(\"llm\", label, WARN, f\"{model}\uff08gateway \u6c92\u56de\u6a21\u578b\u6e05\u55ae\uff0c\u7121\u6cd5\u5c0d\u5e33\uff09\"))\n        elif model in ids:\n            out.append(Check(\"llm\", label, OK, model))\n        else:\n            out.append(Check(\"llm\", label, FAIL, f\"{model} \u4e0d\u5728 gateway \u7684\u6e05\u55ae\u88e1\uff1a{', '.join(map(str, ids[:8]))}\"))\n    return out\n\n\ndef check_ado(s: S.Settings, network: bool, pr_url: str | None) -> list[Check]:\n    pat = s.ado.pat.get_secret_value()\n    if not pat:\n        return [Check(\"ado\", \"ADO_PAT\", FAIL, \"\u672a\u8a2d\u5b9a \u2014\u2014 \u8b80\u53d6 PR\u3001\u767c\u5e03 comment \u8207 harvest \u90fd\u9700\u8981\")]\n    out = [Check(\"ado\", \"ADO_PAT\", OK, f\"set\uff08{len(pat)} chars\uff09\uff1bverify_ssl={s.ado.verify_ssl}\")]\n    if not network or not pr_url:\n        out.append(Check(\"ado\", \"reach\", SKIP, \"\u7d66 --pr-url <\u4e00\u689d\u771f PR> \u624d\u6703\u771f\u6253\u4e00\u6b21 API\"))\n        return out\n    from shared.azdo import client, get_json, parse_pr_url\n    try:\n        ref = parse_pr_url(pr_url)\n    except ValueError as e:\n        out.append(Check(\"ado\", \"reach\", FAIL, str(e)))\n        return out\n    try:\n        with client() as c:\n            pr = get_json(c, ref.pr_api)\n        out.append(Check(\"ado\", \"reach\", OK,\n                         f\"PR {ref.pr_id} @ {ref.repo}: \\\"{(pr.get('title') or '')[:50]}\\\" ({pr.get('status')})\"))\n    except Exception as e:  # noqa: BLE001\n        msg = str(e)\n        hint = \"\"\n        if \"401\" in msg or \"403\" in msg:\n            hint = \"\uff1bPAT \u904e\u671f\u6216\u6b0a\u9650\u4e0d\u8db3\uff08\u81f3\u5c11 Code > Read\uff09\"\n        elif \"SSL\" in msg or \"CERTIFICATE\" in msg.upper():\n            hint = \"\uff1b\u516c\u53f8\u81ea\u7c3d CA \u2192 ADO_VERIFY_SSL \u6307\u5411\u7cfb\u7d71\u5408\u4f75\u5305\"\n        elif \"Proxy\" in msg or \"proxy\" in msg:\n            hint = \"\uff1bHTTPS_PROXY \u8a2d\u4e86\u55ce\"\n        out.append(Check(\"ado\", \"reach\", FAIL, f\"{type(e).__name__}: {msg[:160]}{hint}\"))\n    return out\n\n\n_UNITS = (\"review-orchestrator\",)\n# S1 \u4e4b\u524d\u7684\u4e03\u500b unit\uff1a\u9084\u88dd\u8457\u5c31\u63d0\u9192\u62c6\uff08\u5b83\u5011\u73fe\u5728\u8981\u561b\u6436 port\u3001\u8981\u561b\u8ddf\u884c\u7a0b\u5167\u6392\u7a0b\u91cd\u8907 commit\uff09\n_RETIRED_UNITS = (\"pr-review-ado\", \"pr-review-reader\", \"pr-review-results\",\n                  \"pr-review-repo-sync.timer\", \"pr-review-knowledge-harvest.timer\")\n\n\ndef check_systemd(s: S.Settings) -> list[Check]:\n    if not _which(\"systemctl\"):\n        return [Check(\"systemd\", \"all\", SKIP, \"\u6c92\u6709 systemctl\uff08\u975e Linux \u4e3b\u6a5f\u6216\u5bb9\u5668\uff09\")]\n    out: list[Check] = []\n\n    def _state(unit: str) -> tuple[str, str]:\n        _rc, load = _run([\"systemctl\", \"show\", unit, \"-p\", \"LoadState\", \"--value\"])\n        _rc, active = _run([\"systemctl\", \"show\", unit, \"-p\", \"ActiveState\", \"--value\"])\n        return load.strip(), active.strip()\n\n    for u in _UNITS:                      # \u5e38\u99d0\u7d44\u6015 dead\n        load, active = _state(u)\n        if load == \"not-found\":\n            out.append(Check(\"systemd\", u, SKIP, \"unit \u672a\u5b89\u88dd\"))\n        elif active == \"active\":\n            out.append(Check(\"systemd\", u, OK, \"active\"))\n        else:\n            out.append(Check(\"systemd\", u, FAIL, f\"{active or 'unknown'}\uff1bjournalctl -u {u} -n 30\"))\n    leftovers = [u for u in _RETIRED_UNITS if _state(u)[0] != \"not-found\"]\n    if leftovers:\n        out.append(Check(\"systemd\", \"retired units\", WARN,\n                         \"S1 \u4e4b\u5f8c\u9019\u4e9b unit \u5df2\u7121\u5c0d\u61c9\u7a0b\u5f0f\uff0c\u8acb disable --now \u4e26\u522a\u6a94\uff1a\"\n                         + \", \".join(leftovers)))\n    return out\n\n\n# ---------- \u7d44\u88dd ----------\n\ndef run(*, network: bool = True, pr_url: str | None = None) -> tuple[list[Check], int]:\n    s, checks = check_settings()\n    if s is None:\n        return checks, 2\n    for fn in (lambda: check_python(s), lambda: check_paths(s),\n               lambda: check_services(s, network), lambda: check_langfuse(s, network),\n               lambda: check_llm(s, network), lambda: check_ado(s, network, pr_url),\n               lambda: check_systemd(s)):\n        try:\n            checks += fn()\n        except Exception as e:  # noqa: BLE001  \u2014\u2014 \u4e00\u7d44\u70b8\u6389\u4e0d\u8a72\u8b93\u6574\u5f35\u8868\u6d88\u5931\n            checks.append(Check(\"doctor\", \"internal\", FAIL, f\"{type(e).__name__}: {e}\"))\n    worst = max((_RANK[c.status] for c in checks), default=0)\n    return checks, 1 if worst >= 2 else 0\n\n\ndef render(checks: list[Check]) -> str:\n    lines: list[str] = []\n    cur = None\n    w = max((len(c.name) for c in checks), default=10)\n    for c in checks:\n        if c.group != cur:\n            lines.append(f\"\\n[{c.group}]\")\n            cur = c.group\n        lines.append(f\"  {c.status:<4} {c.name:<{w}}  {c.detail}\")\n    counts = {k: sum(1 for c in checks if c.status == k) for k in (OK, WARN, FAIL, SKIP)}\n    lines.append(\"\")\n    lines.append(\"  \".join(f\"{k} {v}\" for k, v in counts.items()))\n    return \"\\n\".join(lines).lstrip(\"\\n\")\n\n\ndef _main(argv: list[str]) -> int:\n    import argparse\n    ap = argparse.ArgumentParser(prog=\"python -m shared.doctor\",\n                                 description=\"pr-review-suite \u5065\u5eb7\u6aa2\u67e5\uff1a\u8a2d\u5b9a\u3001\u4f9d\u8cf4\u3001\u76ee\u9304\u3001\u670d\u52d9\u3001Langfuse\u3001LLM\u3001ADO\u3001systemd\")\n    ap.add_argument(\"--pr-url\", help=\"\u4e00\u689d\u771f PR \u7684 URL\uff1b\u7d66\u4e86\u624d\u6703\u62ff ADO_PAT \u771f\u6253\u4e00\u6b21 API\")\n    ap.add_argument(\"--no-network\", action=\"store_true\", help=\"\u8df3\u904e\u6240\u6709\u7db2\u8def\u63a2\u91dd\uff08CI / \u96e2\u7dda\uff09\")\n    ap.add_argument(\"--json\", action=\"store_true\", help=\"\u6a5f\u5668\u53ef\u8b80\u8f38\u51fa\")\n    a = ap.parse_args(argv)\n    checks, code = run(network=not a.no_network, pr_url=a.pr_url)\n    if a.json:\n        print(json.dumps({\"exit\": code, \"checks\": [asdict(c) for c in checks]},\n                         ensure_ascii=False, indent=2))\n    else:\n        print(render(checks))\n        print({0: \"\u2192 \u53ef\u4ee5\u4e0a\u5de5\", 1: \"\u2192 \u6709 FAIL\uff1a\u5148\u4fee\u4e0a\u9762\u6a19 FAIL \u7684\u9805\u76ee\",\n               2: \"\u2192 \u8a2d\u5b9a\u89e3\u6790\u4e0d\u904e\uff0c\u5176\u4ed6\u6aa2\u67e5\u6c92\u958b\u8dd1\"}[code])\n    return code\n\n\nif __name__ == \"__main__\":\n    sys.exit(_main(sys.argv[1:]))\n"}
{"path":"shared/install.py","perm":"0644","sha":"dd89aa0b34124ddbea6deefba60b0105af23aa7b8328f9f143ad9771635a23e4","data":"\"\"\"install \u2014\u2014 \u4e00\u53f0\u4e7e\u6de8 Linux \u6a5f\u5f9e\u96f6\u5230\u53ef\u958b\u63a7\u5236\u53f0\uff0c\u4e00\u689d\u6307\u4ee4\u3002\n\n    venv/bin/python -m shared.install   (root shell)      # \u5efa\u76ee\u9304\u3001\u5beb\u7a7a\u8a2d\u5b9a\u3001\u5beb unit\u3001\u8dd1 doctor\n    venv/bin/python -m shared.install --dry-run            # \u53ea\u5370\u6703\u505a\u4ec0\u9ebc\n    venv/bin/python -m shared.install --no-unit            # \u4e0d\u78b0 systemd\uff08\u5bb9\u5668 / \u624b\u52d5\u8dd1\uff09\n\n\u505a\u7684\u4e8b\uff08\u5168\u90e8\u51aa\u7b49\uff0c\u5df2\u5b58\u5728\u5c31\u8df3\u904e\uff09\uff1a\n  1. CONFIG_DIR\uff08\u9810\u8a2d /etc/pr-review-suite\uff09\uff1aconfig.toml\uff08\u7531 schema \u6e32\u67d3\u3001\u5168\u662f\u8a3b\u89e3\uff09\u3001\n     secrets.env\uff08600\uff0c\u542b\u8a72\u586b\u7684\u9375\u540d\uff09\u3002\n  2. DATA_DIR\uff08\u9810\u8a2d /var/lib/pr-review-suite\uff09\uff1areview \u6b77\u53f2\u3002\n  3. /etc/systemd/system/review-orchestrator.service\uff1a\u7531 deploy/systemd \u6a23\u677f\u4ee3\u5165\n     --prefix / --user / CONFIG_DIR\u3002\n  4. chown \u7d66 --user\uff08\u9810\u8a2d svc-review\uff1b\u4e0d\u5b58\u5728\u5c31\u53ea\u63d0\u9192\uff09\u3002\n  5. \u6700\u5f8c\u8dd1\u4e00\u6b21 doctor --no-network\uff0c\u5370\u51fa\u63a5\u4e0b\u4f86\u8a72\u53bb\u63a7\u5236\u53f0\u8a2d\u5b9a\u7cbe\u9748\u586b\u4ec0\u9ebc\u3002\n\n\u4e4b\u5f8c\uff1a\u628a secrets.env \u586b\u597d \u2192 systemctl enable --now review-orchestrator \u2192\n\u958b http://<\u4e3b\u6a5f>:8080/console/setup \u4e00\u6b65\u6b65\u7da0\u71c8\u3002RUNBOOK \u5c31\u9019\u4e00\u9801\u3002\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport os\nimport shutil\nimport sys\nfrom pathlib import Path\n\nfrom shared import settings as S\n\nSECRETS_TEMPLATE = \"\"\"# pr-review-suite secrets \u2014\u2014 \u7531 systemd EnvironmentFile \u8f09\u5165\uff1bchmod 600\uff1b\u4e0d\u9032 git\u3001\u4e0d\u9032 config.toml\nADO_PAT=\nLLM_API_KEY=not-needed\nLANGFUSE_PUBLIC_KEY=\nLANGFUSE_SECRET_KEY=\nORCH_API_KEY=\n# \u6709 proxy / \u81ea\u7c3d CA \u624d\u6253\u958b\uff1a\n# HTTPS_PROXY=http://proxy.corp:3128\n# ADO_VERIFY_SSL=/etc/ssl/certs/ca-certificates.crt\n\"\"\"\n\nUNIT_TEMPLATE = Path(__file__).resolve().parents[1] / \"deploy\" / \"systemd\" / \"review-orchestrator.service.example\"\n\n\ndef _say(dry: bool, msg: str) -> None:\n    print((\"[dry-run] \" if dry else \"\") + msg)\n\n\ndef _write_if_absent(p: Path, text: str, mode: int | None, dry: bool) -> None:\n    if p.exists():\n        _say(dry, f\"\u4fdd\u7559\u65e2\u6709 {p}\")\n        return\n    _say(dry, f\"\u5beb\u5165 {p}\")\n    if dry:\n        return\n    p.parent.mkdir(parents=True, exist_ok=True)\n    p.write_text(text, encoding=\"utf-8\", newline=\"\\n\")\n    if mode is not None:\n        os.chmod(p, mode)\n\n\ndef render_unit(prefix: Path, user: str, config_dir: Path) -> str:\n    text = UNIT_TEMPLATE.read_text(encoding=\"utf-8\")\n    text = text.replace(\"/opt/pr-review-suite\", prefix.as_posix())\n    text = text.replace(\"Environment=CONFIG_DIR=/etc/pr-review-suite\", f\"Environment=CONFIG_DIR={config_dir.as_posix()}\")\n    text = text.replace(\"EnvironmentFile=-/etc/pr-review-suite/\", f\"EnvironmentFile=-{config_dir.as_posix()}/\")\n    text = text.replace(\"User=svc-review\", f\"User={user}\")\n    return \"\\n\".join(ln for ln in text.splitlines() if not ln.startswith(\"# \u8907\u88fd\u70ba\")) + \"\\n\"\n\n\ndef _chown(p: Path, user: str, dry: bool) -> None:\n    if os.name != \"posix\":\n        return\n    import pwd\n    try:\n        pw = pwd.getpwnam(user)\n    except KeyError:\n        _say(dry, f\"\u5e33\u865f {user} \u4e0d\u5b58\u5728\uff1a\u8df3\u904e chown\uff08\u4e4b\u5f8c useradd \u518d chown -R {user}: {p}\uff09\")\n        return\n    _say(dry, f\"chown -R {user}: {p}\")\n    if dry:\n        return\n    for q in [p, *p.rglob(\"*\")]:\n        try:\n            os.chown(q, pw.pw_uid, pw.pw_gid)\n        except OSError:\n            pass\n\n\ndef main(argv: list[str]) -> int:\n    ap = argparse.ArgumentParser(prog=\"python -m shared.install\")\n    ap.add_argument(\"--prefix\", default=str(Path(__file__).resolve().parents[1]),\n                    help=\"\u5b89\u88dd\u6839\uff08\u542b venv/\uff09\uff1b\u9810\u8a2d = \u9019\u4efd\u7a0b\u5f0f\u78bc\u6240\u5728\u76ee\u9304\")\n    ap.add_argument(\"--config-dir\", default=os.getenv(\"CONFIG_DIR\") or S.DEFAULT_CONFIG_DIR)\n    ap.add_argument(\"--data-dir\", default=os.getenv(\"DATA_DIR\") or \"/var/lib/pr-review-suite\")\n    ap.add_argument(\"--user\", default=\"svc-review\")\n    ap.add_argument(\"--unit-path\", default=\"/etc/systemd/system/review-orchestrator.service\")\n    ap.add_argument(\"--no-unit\", action=\"store_true\", help=\"\u4e0d\u5beb systemd unit\")\n    ap.add_argument(\"--dry-run\", action=\"store_true\")\n    a = ap.parse_args(argv)\n    dry = a.dry_run\n    cfg, data, prefix = Path(a.config_dir), Path(a.data_dir), Path(a.prefix)\n\n    print(f\"\u5b89\u88dd\u6839 {prefix}\uff1b\u8a2d\u5b9a {cfg}\uff1b\u8cc7\u6599 {data}\uff1b\u670d\u52d9\u5e33\u865f {a.user}\")\n    _write_if_absent(cfg / \"config.toml\", S.render_toml({}), 0o644, dry)\n    _write_if_absent(cfg / \"secrets.env\", SECRETS_TEMPLATE, 0o600, dry)\n    _say(dry, f\"\u5efa\u7acb {data}\")\n    if not dry:\n        data.mkdir(parents=True, exist_ok=True)\n    for p in (cfg, data):\n        _chown(p, a.user, dry)\n    if not a.no_unit:\n        unit = render_unit(prefix, a.user, cfg)\n        _write_if_absent(Path(a.unit_path), unit, 0o644, dry)\n    if shutil.which(\"semgrep\") is None:\n        print(\"\u63d0\u9192\uff1asemgrep \u4e0d\u5728 PATH \u2014\u2014 static \u5730\u677f\u6703\u8df3\u904e\uff1bvenv/bin/pip install semgrep ruff\")\n\n    print(\"\\n\u63a5\u4e0b\u4f86\uff1a\")\n    print(f\"  1. \u7de8\u8f2f {cfg / 'secrets.env'}\uff08ADO_PAT\u3001LANGFUSE_*\uff1b\u8981\u767b\u5165\u63a7\u5236\u53f0\u5c31\u8a2d ORCH_API_KEY\uff09\")\n    if not a.no_unit:\n        print(\"  2. (root) systemctl daemon-reload; systemctl enable --now review-orchestrator\")\n    print(\"  3. \u958b http://<\u4e3b\u6a5f>:8080/console/setup\uff0c\u7167\u7cbe\u9748\u4e00\u6b65\u6b65\u7da0\u71c8\")\n    print(\"  4. \u4efb\u4f55\u6642\u5019\uff1avenv/bin/python -m shared.doctor\")\n    if not dry:\n        os.environ[\"CONFIG_DIR\"] = str(cfg)\n        os.environ[\"DATA_DIR\"] = str(data)\n        from shared import doctor\n        checks, _code = doctor.run(network=False)\n        print(\"\\n\" + doctor.render(checks))\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main(sys.argv[1:]))\n"}
{"path":"shared/settings.py","perm":"0644","sha":"d581a92e9d98d266b70ffcc72ddb5cbba243373fbd0115e94fa29a251444fb2e","data":"\"\"\"\u5168\u5957\u7cfb\u7d71\u552f\u4e00\u7684\u8a2d\u5b9a\u8b80\u53d6\u9ede \u2014\u2014 64 \u500b\u74b0\u5883\u8b8a\u6578\u7684 schema\u3001\u9810\u8a2d\u503c\u8207\u8aaa\u660e\u4f4f\u9019\u88e1\u3002\n\n\u70ba\u4ec0\u9ebc\u653e shared/\uff1ashared \u662f\u300c\u7b28\u5c64\u300d\uff0corchestrator / tools / eval / harvester\n\u90fd\u53ef\u4ee5 import \u5b83\uff0c\u800c\u5b83\u4e0d import \u4efb\u4f55\u696d\u52d9\u6a21\u7d44\uff08\u4e5f\u4e0d import langfuse\uff09\u3002\n\n\u8a2d\u8a08\u6c7a\u5b9a\uff1a\n  \u8b8a\u6578\u540d\u4e0d\u52d5       \u6bcf\u500b\u6b04\u4f4d\u7684 alias \u5c31\u662f\u65e2\u6709\u7684\u74b0\u5883\u8b8a\u6578\u540d\uff1b\u90e8\u7f72\u597d\u7684 env \u6a94\n                   \u4e00\u500b\u5b57\u90fd\u4e0d\u7528\u6539\u3002\u65e5\u5f8c\u8981\u6539\u540d\uff0c\u5728\u9019\u88e1\u52a0 AliasChoices \u5373\u53ef\u3002\n  \u4e09\u5c64\u4f86\u6e90         env > config.toml > \u9810\u8a2d\u3002env \u4ecd\u662f\u6700\u9ad8\u512a\u5148\uff08\u6e2c\u8a66\u7684\n                   monkeypatch.setenv\u3001run_eval \u7684\u5c0d\u7167\u7d44\u90fd\u9760\u5b83\uff09\uff1bconfig.toml\n                   \u662f\u63a7\u5236\u53f0 Settings \u9801\u5beb\u7684\u6a94\uff08CONFIG_DIR/config.toml\uff0cS2 \u8d77\uff09\uff1b\n                   secrets \u6c38\u9060\u53ea\u8d70 env\uff08systemd EnvironmentFile=secrets.env\uff09\uff0c\n                   toml \u88e1\u51fa\u73fe SecretStr \u6b04\u4f4d\u6703\u88ab\u5ffd\u7565\u4e26\u8b66\u544a\u3002\n  \u60f0\u6027 + \u53ef\u6e05\u5feb\u53d6  settings() \u7b2c\u4e00\u6b21\u547c\u53eb\u624d\u8b80\uff1breset() \u6e05\u6389\u3002tests/conftest.py\n                   \u628a monkeypatch.setenv \u7d81\u4e0a reset()\uff0c\u65e2\u6709\u6e2c\u8a66\u96f6\u6539\u52d5\u3002\n  \u7a7a\u5b57\u4e32 = \u672a\u8a2d    KNOWLEDGE_ROOT=\"\" \u662f run_eval \u95dc\u6389\u77e5\u8b58\u8ff4\u5708\u7684\u6b63\u5f0f\u624b\u6cd5\uff1b\n                   \u6240\u6709\u6b04\u4f4d\u5c0d\u7a7a\u5b57\u4e32\u4e00\u5f8b\u7576\u300c\u672a\u8a2d\u3001\u7528\u9810\u8a2d\u503c\u300d\u3002\n  \u58de\u503c\u5c31\u70b8         \u578b\u5225\u4e0d\u5c0d\uff08REVIEW_MAX_FINDINGS=abc\uff09\u5728\u555f\u52d5\u6642\u5831\u932f\uff0c\u4e0d\u518d\n                   \u975c\u9ed8\u9000\u56de\u9810\u8a2d\u503c\u3002app / tools / harvester \u555f\u52d5\u6642\u547c\u53eb fail_fast()\u3002\n  \u884d\u751f\u5224\u65b7\u6536\u9032\u4f86   knowledge.enabled / graph.enabled / static.semgrep_enabled\n                   \u9019\u985e\u300c\u672a\u8a2d = \u505c\u7528\u300d\u53ea\u5beb\u4e00\u6b21\u3002\n\n\u7528\u6cd5\uff1a\n  from shared.settings import settings\n  settings().review.max_findings\n\n  python -m shared.settings --show      \u76ee\u524d\u751f\u6548\u503c\u8207\u4f86\u6e90\uff08secrets \u906e\u7f69\uff09\n  python -m shared.settings --example   \u7531 schema \u7522\u751f suite.env.example\uff08\u5168 env \u7248\uff09\n  python -m shared.settings --example-toml  \u7531 schema \u7522\u751f config.toml \u6a23\u677f\n  python -m shared.settings --migrate   \u628a\u76ee\u524d env \u88e1\u975e\u9810\u8a2d\u3001\u975e secret \u7684\u503c\u5beb\u6210 config.toml\uff0c\n                                        \u4e26\u5370\u51fa\u8a72\u7559\u5728 secrets.env \u7684\u90a3\u5e7e\u884c\n  python -m shared.settings --check     \u53ea\u9a73\u8b49\uff1b\u58de\u503c\u56de\u50b3\u78bc 1\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport os\nimport shutil\nimport sys\nimport time\nimport tomllib\nfrom pathlib import Path\nfrom typing import Annotated, Any, Callable, Iterator, Literal\n\nfrom pydantic import (AliasChoices, BaseModel, BeforeValidator, Field,\n                      SecretStr, ValidationError, model_validator)\nfrom pydantic.fields import FieldInfo\nfrom pydantic_settings import (BaseSettings, NoDecode, PydanticBaseSettingsSource,\n                               SettingsConfigDict)\n\n# ---------- \u5171\u7528\u7684\u6b04\u4f4d\u578b\u5225 ----------\n\n_TRUE = {\"true\", \"1\", \"yes\", \"on\"}\n_FALSE = {\"false\", \"0\", \"no\", \"off\"}\n\n\ndef _strip(v: Any) -> Any:\n    return v.strip() if isinstance(v, str) else v\n\n\ndef _lower(v: Any) -> Any:\n    return v.strip().lower() if isinstance(v, str) else v\n\n\ndef _csv(v: Any) -> Any:\n    if isinstance(v, str):\n        return [p.strip() for p in v.split(\",\") if p.strip()]\n    return v\n\n\ndef _tri_ssl(v: Any) -> Any:\n    \"\"\"ADO_VERIFY_SSL\uff1atrue/false \u4e4b\u5916\u7684\u5b57\u4e32\u7576 CA bundle \u8def\u5f91\u3002\"\"\"\n    if isinstance(v, str):\n        low = v.strip().lower()\n        if low in _TRUE:\n            return True\n        if low in _FALSE:\n            return False\n        return v.strip()\n    return v\n\n\ndef _switch(v: Any) -> Any:\n    \"\"\"STATIC_SEMGREP / STATIC_RUFF\uff1aauto | on | off\uff08true/false \u540c\u7fa9\uff09\u3002\"\"\"\n    if isinstance(v, str):\n        low = v.strip().lower()\n        if low in _TRUE:\n            return \"on\"\n        if low in _FALSE:\n            return \"off\"\n        return low\n    return v\n\n\nStripped = Annotated[str, BeforeValidator(_strip)]\nLowered = Annotated[str, BeforeValidator(_lower)]\nCsvList = Annotated[list[str], NoDecode, BeforeValidator(_csv)]\nVerifySsl = Annotated[bool | str, BeforeValidator(_tri_ssl)]\nSwitch = Annotated[Literal[\"auto\", \"on\", \"off\"], BeforeValidator(_switch)]\n\n\n# ---------- config.toml\uff1a\u7b2c\u4e8c\u5c64\u4f86\u6e90 ----------\n\nDEFAULT_CONFIG_DIR = \"/etc/pr-review-suite\"\n\n\ndef config_dir() -> Path:\n    return Path(os.getenv(\"CONFIG_DIR\", \"\") or DEFAULT_CONFIG_DIR)\n\n\ndef config_path() -> Path:\n    \"\"\"CONFIG_FILE \u6307\u5b9a\u6574\u500b\u8def\u5f91\uff0c\u5426\u5247 CONFIG_DIR/config.toml\u3002\"\"\"\n    p = os.getenv(\"CONFIG_FILE\", \"\")\n    return Path(p) if p else config_dir() / \"config.toml\"\n\n\n_toml_cache: tuple[Path, float, dict] | None = None\n_toml_ignored_secrets: list[str] = []      # toml \u88e1\u51fa\u73fe\u7684 secret \u6b04\u4f4d\uff08\u88ab\u5ffd\u7565\uff0cwarnings_for \u6703\u63d0\uff09\n\n\ndef load_toml() -> dict[str, dict[str, Any]]:\n    \"\"\"\u8b80 config.toml\uff08\u4f9d mtime \u5feb\u53d6\uff09\u3002\u6a94\u4e0d\u5b58\u5728 = {}\uff1b\u58de\u6a94 = raise\uff08fail_fast \u6703\u8f49\u6210\u4eba\u8a71\uff09\u3002\"\"\"\n    global _toml_cache\n    p = config_path()\n    try:\n        mtime = p.stat().st_mtime\n    except OSError:\n        _toml_cache = None\n        return {}\n    if _toml_cache and _toml_cache[0] == p and _toml_cache[1] == mtime:\n        return _toml_cache[2]\n    with p.open(\"rb\") as f:\n        data = tomllib.load(f)\n    if not isinstance(data, dict):\n        raise ValueError(f\"{p}: \u9802\u5c64\u5fc5\u9808\u662f table\")\n    _toml_cache = (p, mtime, data)\n    return data\n\n\nclass _TomlSection(PydanticBaseSettingsSource):\n    \"\"\"\u628a config.toml \u88e1 [<group>] \u90a3\u5f35\u8868\u7576\u6210\u9019\u500b group \u7684\u4f86\u6e90\uff08\u6b04\u4f4d\u540d\u70ba\u9375\uff09\u3002\"\"\"\n\n    def __init__(self, settings_cls, section: str):\n        super().__init__(settings_cls)\n        self.section = section\n\n    def get_field_value(self, field: FieldInfo, field_name: str):\n        return load_toml().get(self.section, {}).get(field_name), field_name, False\n\n    def __call__(self) -> dict[str, Any]:\n        table = load_toml().get(self.section) or {}\n        out: dict[str, Any] = {}\n        for fname, info in self.settings_cls.model_fields.items():\n            if fname not in table:\n                continue\n            if info.annotation is SecretStr:\n                key = f\"{self.section}.{fname}\"\n                if key not in _toml_ignored_secrets:\n                    _toml_ignored_secrets.append(key)\n                continue\n            out[fname] = table[fname]\n        return out\n\n\nclass _Group(BaseSettings):\n    \"\"\"\u6bcf\u4e00\u7d44\u8a2d\u5b9a\u7684\u57fa\u5e95\uff1aenv > config.toml \u7684 [group] \u8868 > \u9810\u8a2d\uff1b\u8a8d alias\uff1b\u5ffd\u7565\u4e0d\u8a8d\u8b58\u7684\u9375\u3002\"\"\"\n\n    model_config = SettingsConfigDict(extra=\"ignore\", populate_by_name=True,\n                                      frozen=True)\n\n    @classmethod\n    def settings_customise_sources(cls, settings_cls, init_settings, env_settings,\n                                   dotenv_settings, file_secret_settings):\n        return (init_settings, env_settings,\n                _TomlSection(settings_cls, cls.__name__.lower()))\n\n    @model_validator(mode=\"before\")\n    @classmethod\n    def _blank_means_unset(cls, data: Any) -> Any:\n        \"\"\"\u74b0\u5883\u8b8a\u6578\u8a2d\u6210\u7a7a\u5b57\u4e32 = \u6c92\u8a2d\uff08\u7528\u9810\u8a2d\u503c\uff09\u3002\"\"\"\n        if isinstance(data, dict):\n            return {k: v for k, v in data.items()\n                    if not (isinstance(v, str) and v.strip() == \"\")}\n        return data\n\n\n# ---------- \u5404\u7d44 ----------\n\nclass Ado(_Group):\n    \"\"\"Azure DevOps \u9023\u7dda\u8207 diff \u6293\u53d6\uff08orchestrator/adapters/ado.py \u8207 harvester \u5171\u7528\uff09\u3002\"\"\"\n\n    pat: SecretStr = Field(\n        SecretStr(\"\"), alias=\"ADO_PAT\",\n        description=\"Azure DevOps Personal Access Token\u3002\u53ea\u8b80 PR \u81f3\u5c11 Code > Read\uff1b\"\n                    \"\u8981\u771f\u767c\u7559\u8a00\u9700 Code > Read & Write\u3002\u5168\u5957\u53ea\u586b\u9019\u4e00\u6b21\u3002\",\n        json_schema_extra={\"example\": \"changeme\", \"required\": True})\n    verify_ssl: VerifySsl = Field(\n        True, alias=\"ADO_VERIFY_SSL\",\n        description=\"true / false\uff0c\u6216 CA bundle \u8def\u5f91\uff08\u516c\u53f8\u81ea\u7c3d CA \u6307\u5411\u7cfb\u7d71\u5408\u4f75\u5305\uff0c\"\n                    \"\u4f8b\u5982 /etc/ssl/certs/ca-certificates.crt\uff09\u3002\")\n    diff_max_files: int = Field(\n        300, alias=\"ADO_DIFF_MAX_FILES\", ge=1,\n        description=\"\u4e00\u689d PR \u6700\u591a\u7d0d\u5165\u5e7e\u500b\u6a94\u6848\u3002\u8d85\u904e\u7684\u6a94\u6848\u5b8c\u5168\u4e0d\u6703\u88ab\u6293\u4e0b\u4f86\u2014\u2014\"\n                    \"LLM\u3001semgrep/ruff\u3001\u78ba\u5b9a\u6027 MISSING-TEST \u90fd\u770b\u4e0d\u5230\u3002\")\n    diff_max_file_bytes: int = Field(\n        600000, alias=\"ADO_DIFF_MAX_FILE_BYTES\", ge=1,\n        description=\"\u55ae\u6a94\u5167\u5bb9\u4e0a\u9650\uff08bytes\uff09\uff0c\u4efb\u4e00\u5074\u8d85\u904e\u5c31\u6574\u6a94\u7565\u904e\u4e26\u7559\u8a3b\u8a18\u3002\")\n    diff_fetch_concurrency: int = Field(\n        8, alias=\"ADO_DIFF_FETCH_CONCURRENCY\", ge=1,\n        description=\"\u6293\u6a94\u4f75\u767c\u5ea6\u3002\u6bcf\u6a94\u8981\u6293 base/head \u5169\u4efd\uff1b\u5148\u78ba\u8a8d proxy/ADO \u6c92\u6709\u9023\u7dda\u6578\u9650\u5236\u3002\")\n\n\nclass Posting(_Group):\n    \"\"\"\u5c0d Azure DevOps \u7684\u5beb\u5165\u958b\u95dc\uff08\u51fa\u5ee0\u5168\u5b89\u5168\u5074\uff1b\u8207 AUTO_POST \u758a\u6210\u96d9\u4fdd\u96aa\uff09\u3002\"\"\"\n\n    dry_run: bool = Field(\n        True, alias=\"DRY_RUN\",\n        description=\"review \u7a3f\u662f\u5426\u53ea\u9810\u89bd\u4e0d\u771f\u767c\u3002\u5167\u6e2c\u671f\u9593\u4fdd\u6301 true\uff08\u5b89\u5168\u6c23\u56ca\uff09\uff1b\"\n                    \"\u8981\u771f\u767c\u9700\u540c\u6642 AUTO_POST=true\u3002\")\n    knowledge_post: bool = Field(\n        False, alias=\"KNOWLEDGE_POST\",\n        description=\"\u77e5\u8b58\u84b8\u993e\u7a3f\u662f\u5426\u771f\u8cbc\u5230 PR\u3002\u8ddf DRY_RUN \u523b\u610f\u5206\u5bb6\uff0c\u53ef\u5148\u884c\u8a66\u9ede\u3002\")\n\n\nclass Jobs(_Group):\n    \"\"\"\u884c\u7a0b\u5167\u6392\u7a0b\uff08\u539f repo-sync / knowledge-harvest \u5169\u7d44 systemd timer\uff09\u30020 = \u95dc\uff1b\u5c0d\u61c9 root \u672a\u8a2d\u4e5f\u4e0d\u6392\u3002\"\"\"\n\n    repo_sync_interval_min: int = Field(\n        10, alias=\"REPO_SYNC_INTERVAL_MIN\", ge=0,\n        description=\"\u6bcf\u9694\u5e7e\u5206\u9418\u628a REPOS_ROOT \u5e95\u4e0b\u7684 clone git pull --ff-only \u4e00\u6b21\u3002\")\n    harvest_interval_min: int = Field(\n        30, alias=\"HARVEST_INTERVAL_MIN\", ge=0,\n        description=\"\u6bcf\u9694\u5e7e\u5206\u9418\u8dd1\u4e00\u6b21 knowledge harvest\uff08PR \u7d42\u614b\u88c1\u6c7a + \u843d\u5730 + commit\uff09\u3002\")\n    graph_rebuild: Switch = Field(\n        \"auto\", alias=\"REPO_SYNC_GRAPH_REBUILD\",\n        description=\"repo-sync \u5f8c\u662f\u5426\u8dd1 code-review-graph build\u3002auto = \u88dd\u4e86\u5c31\u8dd1\u3002\")\n\n\nclass Llm(_Group):\n    \"\"\"OpenAI \u76f8\u5bb9\u7684 LLM gateway\u3002\"\"\"\n\n    base_url: Stripped = Field(\n        \"http://localhost:8000\", alias=\"LLM_BASE_URL\",\n        description=\"\u586b\u5230\u300c/chat/completions \u7684\u4e0a\u4e00\u5c64\u300d\uff08\u5e36\u4e0d\u5e36 /v1 \u4ee5\u5be6\u6e2c\u70ba\u6e96\uff09\u3002\",\n        json_schema_extra={\"example\": \"http://llm-gateway.internal\", \"required\": True})\n    api_key: SecretStr = Field(\n        SecretStr(\"not-needed\"), alias=\"LLM_API_KEY\",\n        description=\"gateway \u4e0d\u9a57 key \u5c31\u7559 not-needed\u3002\")\n    model: Stripped = Field(\n        \"gpt-4o-mini\", alias=\"LLM_MODEL\",\n        description=\"planner / reviewer / distiller \u7528\u7684\u6a21\u578b\u3002\",\n        json_schema_extra={\"example\": \"changeme\", \"required\": True})\n    model_adversary: str | None = Field(\n        None, alias=\"LLM_MODEL_ADVERSARY\",\n        description=\"adversary \u5c08\u7528\u6a21\u578b\uff08\u63db\u4e00\u9846\u8166\u53bb\u81ea\u6211\u540c\u610f\u504f\u5dee\uff09\uff1b\u672a\u8a2d = LLM_MODEL\u3002\")\n    model_digest: str | None = Field(\n        None, alias=\"LLM_MODEL_DIGEST\",\n        description=\"\u6536\u53e3 digest \u9867\u554f\u5206\u6790\u5c08\u7528\u6a21\u578b\uff1b\u672a\u8a2d = LLM_MODEL\u3002\")\n    timeout_s: float = Field(\n        180.0, alias=\"LLM_TIMEOUT_S\", gt=0,\n        description=\"\u55ae\u6b21 LLM \u547c\u53eb\u903e\u6642\u79d2\u6578\uff1b\u903e\u6642\u91cd\u8a66\u4e00\u6b21\u5f8c\u628a\u4f8b\u5916\u4ea4\u9084\u547c\u53eb\u7aef\u8d70\u964d\u7d1a\u3002\")\n\n\nclass Langfuse(_Group):\n    \"\"\"Langfuse\uff08trace / prompt \u7248\u63a7 / eval\uff09\u3002SDK \u81ea\u5df1\u8b80\u9019\u4e09\u500b\u8b8a\u6578\uff1b\u9019\u88e1\u53ea\u70ba\u4e86 --show \u8207 doctor \u770b\u5f97\u898b\u3002\"\"\"\n\n    host: Stripped = Field(\"http://localhost:3000\", alias=\"LANGFUSE_HOST\",\n                           description=\"Langfuse \u4f4d\u5740\u3002\",\n                           json_schema_extra={\"required\": True})\n    public_key: Stripped = Field(\"\", alias=\"LANGFUSE_PUBLIC_KEY\",\n                                 description=\"pk-lf-\u2026\",\n                                 json_schema_extra={\"example\": \"pk-lf-changeme\", \"required\": True})\n    secret_key: SecretStr = Field(SecretStr(\"\"), alias=\"LANGFUSE_SECRET_KEY\",\n                                  description=\"sk-lf-\u2026\",\n                                  json_schema_extra={\"example\": \"sk-lf-changeme\", \"required\": True})\n\n\nclass Orchestrator(_Group):\n    \"\"\"review-orchestrator\uff088080\uff09\u7684\u670d\u52d9\u5c64\u65cb\u9215\u3002\"\"\"\n\n    pipeline: Annotated[Literal[\"v1\", \"v2\"], BeforeValidator(_lower)] = Field(\n        \"v1\", alias=\"REVIEW_PIPELINE\",\n        description=\"v1 = \u55ae\u6b21 LLM \u547c\u53eb\uff08\u56de\u6efe\u7528\uff09\uff1bv2 = anatomy\u2192static\u2192plan\u2192\u5e73\u884c reviewer\"\n                    \"\u2192adversary\u2192synthesis\u3002\u5207 v2 \u524d\u5148\u8dd1\u904e eval \u57fa\u7dda\u3002\")\n    auto_post: bool = Field(\n        False, alias=\"AUTO_POST\",\n        description=\"review \u5b8c\u662f\u5426\u547c\u53eb \u2462 \u56de\u8cbc\u3002\u9700\u540c\u6642 DRY_RUN=false \u624d\u6703\u771f\u767c\uff08\u96d9\u4fdd\u96aa\uff09\u3002\")\n    dedupe_ttl: float = Field(\n        120.0, alias=\"REVIEW_DEDUPE_TTL\", ge=0,\n        description=\"\u540c\u4e00\u689d PR \u5728\u5e7e\u79d2\u5167\u91cd\u8907\u89f8\u767c\u6642\uff0c\u91cd\u64ad\u5feb\u53d6\u800c\u4e0d\u91cd\u8dd1\u3002\")\n    api_key: SecretStr = Field(\n        SecretStr(\"\"), alias=\"ORCH_API_KEY\",\n        description=\"\u8a2d\u4e86\u5c31\u8981\u6c42 Bearer\uff1b/eval-webhook \u523b\u610f\u4e0d\u9a57\u3002\u7528\u5230 K \u6bb5\u91cd\u84b8\u5c31\u5fc5\u9808\u8a2d\"\n                    \"\uff08/knowledge/redistill \u6709 LLM \u82b1\u8cbb\u8207\u5beb\u6a94\u8a9e\u610f\uff09\u3002harvester \u8b80\u540c\u4e00\u500b\u503c\u3002\")\n    url: Stripped = Field(\n        \"http://127.0.0.1:8080\", alias=\"ORCH_URL\",\n        description=\"harvester \u6253\u91cd\u84b8\u8acb\u6c42\u7684\u4f4d\u5740\uff08\u540c\u6a5f loopback\uff1b\u4e0d\u8d70 proxy\uff09\u3002\")\n    data_dir: Path = Field(\n        Path(\"/var/lib/pr-review-suite\"), alias=\"DATA_DIR\",\n        description=\"review \u6b77\u53f2\uff08reviews.db\uff0cSQLite\uff09\u4f4f\u9019\u88e1\uff1b\u670d\u52d9\u5e33\u865f\u8981\u80fd\u5beb\u3002\u958b\u4e0d\u51fa\u4f86 = \u6b77\u53f2\u505c\u7528\u3001review \u7167\u8dd1\u3002\")\n\n    @property\n    def base_url(self) -> str:\n        return self.url.rstrip(\"/\")\n\n\nclass Review(_Group):\n    \"\"\"v2 pipeline \u65cb\u9215\u3002\u5168\u90e8\u9032 trace metadata\uff1b\u6539\u4efb\u4f55\u4e00\u9846\u5148\u904e eval\u3002\"\"\"\n\n    max_dimensions: int = Field(\n        8, alias=\"REVIEW_MAX_DIMENSIONS\", ge=2,\n        description=\"planner \u6700\u591a\u958b\u5e7e\u79d1\uff08Coverage Sweep \u53ef\u984d\u5916 +1\uff09\u3002\u958b\u591a\u79d1\u6bd4\u628a\u55ae\u79d1\u9810\u7b97\u62c9\u5927\u597d\u3002\")\n    max_parallel: int = Field(\n        6, alias=\"REVIEW_MAX_PARALLEL\", ge=1,\n        description=\"reviewer / adversary \u7684 LLM \u4f75\u767c\u4e0a\u9650\u3002\")\n    llm_base_conf: float = Field(\n        0.7, alias=\"REVIEW_LLM_BASE_CONF\", ge=0, le=1,\n        description=\"LLM finding \u7684\u57fa\u790e\u4fe1\u5fc3\uff1badversary confirmed \u00d71.25 / rejected \u00d70.35\u3002\")\n    min_confidence: float = Field(\n        0.55, alias=\"REVIEW_MIN_CONFIDENCE\", ge=0, le=1,\n        description=\"\u4f4e\u65bc\u6b64\u5206\u7684 finding \u5728 synthesis \u88ab\u904e\u6ffe\u3002\")\n    max_findings: int = Field(\n        30, alias=\"REVIEW_MAX_FINDINGS\", ge=1,\n        description=\"\u5831\u544a\u8f38\u51fa\u4e0a\u9650\uff08\u7d14\u8f38\u51fa\uff0c\u4e0d\u5f71\u97ff\u4efb\u4f55 prompt \u9577\u5ea6\uff09\u3002\")\n    adversary: bool = Field(\n        True, alias=\"REVIEW_ADVERSARY\",\n        description=\"\u95dc\u6389 = \u8df3\u904e\u5c0d\u6297\u6bb5\uff08A/B \u7528\uff09\u3002\")\n    adversary_chunk: int = Field(\n        6, alias=\"ADVERSARY_CHUNK\", ge=1,\n        description=\"adversary \u6bcf\u6b21\u547c\u53eb\u6700\u591a\u5be9\u5e7e\u689d\uff08\u5206\u584a\u9632\u6ce8\u610f\u529b\u7a00\u91cb\uff09\u3002\")\n    reviewer_rules_max_chars: int = Field(\n        20000, alias=\"REVIEWER_RULES_MAX_CHARS\", ge=0,\n        description=\"\u6bcf\u500b reviewer \u6536\u5230\u7684\u898f\u5247\u6587\u5b57\u4e0a\u9650\u3002\")\n    reviewer_slices_max_chars: int = Field(\n        30000, alias=\"REVIEWER_SLICES_MAX_CHARS\", ge=0,\n        description=\"\u6bcf\u4e00\u79d1\u7684 diff \u5207\u7247\u7e3d\u9810\u7b97\uff1b\u8d85\u9810\u7b97\u7684\u6a94\u964d\u7d1a static-only \u4e26\u9032 slices_skipped\u3002\"\n                    \"\u26a0 \u6539\u9019\u500b\u6578\u6703\u6539\u8b8a golden set \u7684\u8a9e\u610f\u3002\")\n    reviewer_file_slice_max_chars: int = Field(\n        6000, alias=\"REVIEWER_FILE_SLICE_MAX_CHARS\", ge=0,\n        description=\"\u55ae\u4e00\u6a94\u6848\u7684\u5207\u7247\u4e0a\u9650\uff08\u8d85\u904e\u5c31\u6a94\u5167\u622a\u65b7\uff09\u3002\")\n\n\nclass Static(_Group):\n    \"\"\"\u78ba\u5b9a\u6027\u975c\u614b\u6383\u63cf\uff08semgrep / ruff / MISSING-TEST\uff09\u3002\"\"\"\n\n    semgrep: Switch = Field(\n        \"auto\", alias=\"STATIC_SEMGREP\",\n        description=\"auto = \u88dd\u4e86\u5c31\u8dd1\uff1bon = \u8981\u8dd1\uff08\u6c92\u88dd\u4ecd\u53ea\u80fd\u8df3\u904e\u4e26\u8a3b\u8a18\uff09\uff1boff = \u4e0d\u8dd1\u3002\"\n                    \"\u6ce8\u610f systemd \u7684 PATH \u8981\u542b venv/bin \u624d\u627e\u5f97\u5230\u3002\")\n    ruff: Switch = Field(\"auto\", alias=\"STATIC_RUFF\", description=\"\u540c STATIC_SEMGREP\u3002\")\n    timeout: int = Field(\n        300, alias=\"STATIC_TIMEOUT\", ge=1,\n        description=\"\u6383\u63cf\u903e\u6642\u79d2\u6578\u3002journal \u51fa\u73fe timed out \u5c31\u5f80\u4e0a\u8abf\u3002\")\n    missing_test: bool = Field(\n        True, alias=\"STATIC_MISSING_TEST\",\n        description=\"\u78ba\u5b9a\u6027 MISSING-TEST\uff08diff \u6709\u65b0\u5ba3\u544a\u537b\u96f6\u6e2c\u8a66\u6a94 \u2192 conf 1.0 \u4fdd\u5e95\uff09\u3002\")\n\n    @property\n    def semgrep_enabled(self) -> bool:\n        return self.semgrep != \"off\" and shutil.which(\"semgrep\") is not None\n\n    @property\n    def ruff_enabled(self) -> bool:\n        return self.ruff != \"off\" and shutil.which(\"ruff\") is not None\n\n\nclass Repos(_Group):\n    \"\"\"\u672c\u5730\u4e7e\u6de8 clone\uff08base \u4e0a\u4e0b\u6587\uff09\u3002REPOS_ROOT/<repo\u5c0f\u5beb>/ \u4e00 repo \u4e00\u9846\uff0cjobs \u7684 repo-sync \u4fdd\u9bae\u3002\"\"\"\n\n    repos_root: Path | None = Field(\n        None, alias=\"REPOS_ROOT\",\n        description=\"REPOS_ROOT/<repo\u5c0f\u5beb>/ \u4e00 repo \u4e00\u9846 clone\uff08target branch\uff09\uff0c\"\n                    \"jobs \u7684 repo-sync \u4fdd\u9bae\u3002\u672a\u8a2d = \u6c92\u6709 base \u4e0a\u4e0b\u6587\uff0creview \u7167\u8dd1\u3002\",\n        json_schema_extra={\"example\": \"/opt/repos\"})\n    context_lines: int = Field(\n        6, alias=\"CONTEXT_LINES\", ge=0,\n        description=\"\u6bcf\u500b hunk \u5f9e base \u53d6\u820a\u884c\u865f\u9644\u8fd1 \u00b1N \u884c\u3002\")\n    context_max_chars: int = Field(\n        24000, alias=\"CONTEXT_MAX_CHARS\", ge=0,\n        description=\"base \u4e0a\u4e0b\u6587\u8207 graph \u6458\u8981\u7684\u9810\u7b97\u3002\u6703\u9032\u300c\u6bcf\u4e00\u79d1\u300d\u7684 reviewer prompt\u3002\")\n\n    def root_for(self, repo: str | None) -> Path | None:\n        \"\"\"REPOS_ROOT/<repo\u5c0f\u5beb>/\uff0c\u5b58\u5728\u624d\u56de\uff1b\u5426\u5247 None\uff08\u547c\u53eb\u7aef\u512a\u96c5\u964d\u7d1a\uff09\u3002\"\"\"\n        if not self.repos_root or not repo:\n            return None\n        p = (self.repos_root / repo.strip().lower()).resolve()\n        return p if p.is_dir() else None\n\n\nclass Graph(_Group):\n    \"\"\"\u2463 code graph\uff08\u9078\u914d\uff09\u3002GRAPH_TOOLS_URL \u8207 GRAPH_TOOL_BLAST \u90fd\u8a2d\u4e86\u624d\u555f\u7528\u3002\"\"\"\n\n    tools_url: str | None = Field(\n        None, alias=\"GRAPH_TOOLS_URL\",\n        description=\"code-review-graph serve --http \u7684 MCP \u4f4d\u5740\u3002\",\n        json_schema_extra={\"example\": \"http://127.0.0.1:8097/mcp\"})\n    tool_blast: str | None = Field(\n        None, alias=\"GRAPH_TOOL_BLAST\",\n        description=\"\u5f71\u97ff\u534a\u5f91\u5de5\u5177\u540d\uff08\u88dd\u597d\u5f8c list tools \u78ba\u8a8d\uff09\u3002\",\n        json_schema_extra={\"example\": \"get_impact_radius_tool\"})\n    tool_blast_args: str = Field(\n        '{\"files\": $files}', alias=\"GRAPH_TOOL_BLAST_ARGS\",\n        description=\"\u53c3\u6578 JSON \u6a23\u677f\uff1b$files / $repo / $repo_dir \u6703\u88ab\u4ee3\u5165\u3002\u542b $ \u8207\u7a7a\u767d\uff0c\"\n                    \"\u88ab shell source \u6642\u8981\u7528\u55ae\u5f15\u865f\u3002\u591a repo \u81ea\u52d5\u5207\u5eab\uff1a\"\n                    '{\"changed_files\": $files, \"repo_root\": \"<REPOS_ROOT>/$repo_dir\"}')\n    repo: str | None = Field(\n        None, alias=\"GRAPH_REPO\",\n        description=\"graph server \u7d81\u5b9a\u7684 repo \u540d\uff08\u5c0f\u5beb\uff09\uff1b\u8a2d\u4e86\u4e4b\u5f8c\u5176\u4ed6 repo \u81ea\u52d5\u8df3\u904e graph\u3002\"\n                    \"\u591a repo \u5207\u5eab\u6a21\u5f0f\u7559\u7a7a\u3002\")\n\n    @property\n    def enabled(self) -> bool:\n        return bool(self.tools_url and self.tool_blast)\n\n    @property\n    def bound_repo(self) -> str:\n        return (self.repo or \"\").strip().lower()\n\n\nclass Rules(_Group):\n    \"\"\"\u5718\u968a\u898f\u5247 repo\uff08\u672c\u6a5f clone\uff09\u3002RULES_ROOT \u672a\u8a2d = \u898f\u5247\u529f\u80fd\u6574\u500b\u975c\u9ed8\u505c\u7528\u3002\"\"\"\n\n    root: Path | None = Field(\n        None, alias=\"RULES_ROOT\",\n        description=\"\u898f\u5247 repo \u7684\u672c\u6a5f clone\uff1b\u6bcf\u6b21 review \u7528\u5230\u7684 commit SHA \u6703\u9032 trace\u3002\",\n        json_schema_extra={\"example\": \"/opt/pr-review-rules\"})\n    subdir: Stripped = Field(\"rules\", alias=\"RULES_SUBDIR\",\n                             description=\"\u898f\u5247\u76ee\u9304\u540d\uff08<RULES_ROOT>/rules/\uff09\u3002\")\n    common_dir: Stripped = Field(\"common\", alias=\"RULES_COMMON_DIR\",\n                                 description=\"\u6bcf\u6b21 review \u5fc5\u8f09\u7684\u5b50\u76ee\u9304\u540d\u3002\")\n    max_chars: int = Field(60000, alias=\"RULES_MAX_CHARS\", ge=0,\n                           description=\"\u7d44\u9032 prompt \u7684\u898f\u5247\u7e3d\u91cf\u4e0a\u9650\uff08\u5b57\u5143\uff09\u3002\")\n\n    @property\n    def enabled(self) -> bool:\n        return self.root is not None\n\n\nclass Knowledge(_Group):\n    \"\"\"\u77e5\u8b58\u8ff4\u5708\uff08K \u6bb5\uff0c\u9078\u914d\uff09\u3002KNOWLEDGE_ROOT \u672a\u8a2d = \u6ce8\u5165\u8207\u84b8\u993e\u7686\u975c\u9ed8\u505c\u7528\u3002\"\"\"\n\n    root: Path | None = Field(\n        None, alias=\"KNOWLEDGE_ROOT\",\n        description=\"\u672c\u5730 knowledge repo \u8def\u5f91\uff08\u884c\u7a0b\u5167\u7684 harvest job \u662f\u552f\u4e00 commit \u8005\uff09\u3002\",\n        json_schema_extra={\"example\": \"/opt/pr-review-knowledge\"})\n    branches: CsvList = Field(\n        [\"master\", \"main\"], alias=\"KNOWLEDGE_BRANCHES\",\n        description=\"\u9032\u5e33\u672c\u7684\u76ee\u6a19\u5206\u652f\uff08\u9017\u865f\u5206\u9694\u3001\u652f\u63f4\u842c\u7528\u5b57\u5143\uff0c\u4f8b\uff1amaster,release/*\uff09\u3002\")\n    max_chars: int = Field(\n        18000, alias=\"KNOWLEDGE_MAX_CHARS\", ge=0,\n        description=\"Stage 04 \u6ce8\u5165\u5340\u584a\u7e3d\u4e0a\u9650\uff1b\u540c\u6a23\u6703\u9032 reviewer prompt\u3002\")\n    distill_diff_max_chars: int = Field(\n        100000, alias=\"DISTILL_DIFF_MAX_CHARS\", ge=0,\n        description=\"\u84b8\u993e\u770b\u5f97\u5230\u7684 diff \u5207\u7247\u9810\u7b97\uff1b\u8d85\u9810\u7b97\u7684\u6a94\u6703\u7559\u8a3b\u8a18\u4e26\u9032 distill_slices_skipped\u3002\")\n    redistill: bool = Field(\n        True, alias=\"KNOWLEDGE_REDISTILL\",\n        description=\"stale \u91cd\u84b8\uff08draft \u4e4b\u5f8c\u53c8\u6709 push \u2192 \u7528\u6700\u7d42 diff \u91cd\u84b8\u4e00\u6b21\uff0c\u22642 \u6b21\uff09\u3002\"\n                    \"false = \u56de\u5230 stale \u76f4\u63a5\u4e1f\u7a3f\u3002\")\n    cycle_source: Stripped = Field(\n        \"release/*\", alias=\"KNOWLEDGE_CYCLE_SOURCE\",\n        description=\"\u9031\u671f\u9a57\u6536 PR \u7684 source \u5206\u652f\u6a23\u5f0f\uff1b\u7b26\u5408\u8005\u4e0d\u84b8\u993e\u3001\u4f5c\u70ba\u6536\u53e3\u5100\u5f0f\u3002\")\n    cycle_target: Stripped = Field(\n        \"master\", alias=\"KNOWLEDGE_CYCLE_TARGET\",\n        description=\"\u9031\u671f\u9a57\u6536 PR \u7684 target \u5206\u652f\u3002\")\n    digest: bool = Field(\n        True, alias=\"KNOWLEDGE_DIGEST\",\n        description=\"\u6536\u53e3 digest \u8981\u4e0d\u8981\u8cbc\u5230\u9a57\u6536 PR\uff08false = \u5168\u6697\u5f71\u5b50\u6a21\u5f0f\uff1a\u7167\u6a23\u843d\u5730\u3001\u4e0d\u767c\u7559\u8a00\uff09\u3002\")\n    digest_llm: bool = Field(\n        True, alias=\"KNOWLEDGE_DIGEST_LLM\",\n        description=\"digest \u7684\u300cNeeds a look\u300d\u9867\u554f\u6bb5\uff08LLM \u63d0\u6848\uff0c\u843d\u5730\u8def\u5f91\u4e0d\u8b80\uff09\u3002false = \u7d14\u6e05\u55ae\u3002\")\n    digest_max_flags: int = Field(\n        12, alias=\"KNOWLEDGE_DIGEST_MAX_FLAGS\", ge=1,\n        description=\"\u9867\u554f\u65d7\u6a19\u4e0a\u9650\uff08\u9632\u6d17\u7248\uff09\u3002\")\n    retire_on_contradiction: bool = Field(\n        True, alias=\"KNOWLEDGE_RETIRE_ON_CONTRADICTION\",\n        description=\"\u5be6\u4f5c\u63a8\u7ffb\u898f\u5247\u6642\u6536\u53e3\u662f\u5426\u62d4\u6389\u90a3\u689d\u4e0d\u8b8a\u5f0f\uff08\u6c89\u9ed8\u5373\u62d4\uff1b\u56de keep <ID> \u5426\u6c7a\uff09\u3002\"\n                    \"false = \u53ea\u63d0\u6848\u4e0d\u57f7\u884c\u3002\")\n\n    @property\n    def enabled(self) -> bool:\n        return self.root is not None and self.root.is_dir()\n\n\nclass Eval(_Group):\n    \"\"\"\u96e2\u7dda\u8003\u8a66\uff08run_eval / run_distill_eval\uff09\u3002\u9580\u6abb\u672a\u8a2d = report-only\u3002\"\"\"\n\n    knowledge_root: Path | None = Field(\n        None, alias=\"EVAL_KNOWLEDGE_ROOT\",\n        description=\"\u77e5\u8b58\u4f9d\u8cf4\u984c\u7684\u7a2e\u5b50\u5e33\u672c\uff1b\u672a\u8a2d = eval/fixtures/knowledge\u3002\")\n    knowledge_ab: bool = Field(\n        True, alias=\"EVAL_KNOWLEDGE_AB\",\n        description=\"\u5c0d\u7167\u7d44\uff08\u540c\u4e00\u6279\u77e5\u8b58\u984c\u518d\u8dd1\u4e00\u6b21 KNOWLEDGE_ROOT=\\\"\\\"\uff09\uff1b\u95dc\u6389\u5c31\u6c92\u6709 delta\u3002\")\n    min_recall: float = Field(0.0, alias=\"EVAL_MIN_RECALL\", ge=0, le=1,\n                              description=\"CI gate\uff1amust_catch_recall \u4e0b\u9650\u3002\")\n    max_noise: float | None = Field(None, alias=\"EVAL_MAX_NOISE\", ge=0,\n                                    description=\"CI gate\uff1anoise rate \u4e0a\u9650\u3002\")\n    max_forbidden: float | None = Field(None, alias=\"EVAL_MAX_FORBIDDEN\", ge=0,\n                                        description=\"CI gate\uff1aforbidden-hit rate \u4e0a\u9650\u3002\")\n    min_knowledge_delta: float | None = Field(\n        None, alias=\"EVAL_MIN_KNOWLEDGE_DELTA\",\n        description=\"knowledge_delta \u7684\u9580\u6abb\u3002\u5148 report-only\uff0c\u57fa\u7dda\u7a69\u5b9a\u5169\u8f2a\u518d\u8a2d\u3002\")\n    min_distill_score: float | None = Field(\n        None, alias=\"EVAL_MIN_DISTILL_SCORE\", ge=0, le=1,\n        description=\"\u84b8\u993e\u8003\u5377\u7684\u9580\u6abb\uff0c\u540c\u6a23\u5148 report-only\u3002\")\n\n\n# ---------- \u7e3d\u8868 ----------\n\nclass Settings(BaseModel):\n    model_config = {\"frozen\": True}\n\n    ado: Ado = Field(default_factory=Ado)\n    posting: Posting = Field(default_factory=Posting)\n    jobs: Jobs = Field(default_factory=Jobs)\n    llm: Llm = Field(default_factory=Llm)\n    langfuse: Langfuse = Field(default_factory=Langfuse)\n    orchestrator: Orchestrator = Field(default_factory=Orchestrator)\n    review: Review = Field(default_factory=Review)\n    static: Static = Field(default_factory=Static)\n    repos: Repos = Field(default_factory=Repos)\n    graph: Graph = Field(default_factory=Graph)\n    rules: Rules = Field(default_factory=Rules)\n    knowledge: Knowledge = Field(default_factory=Knowledge)\n    eval: Eval = Field(default_factory=Eval)\n\n    def knobs(self) -> dict[str, Any]:\n        \"\"\"\u9032 trace metadata \u7684\u65cb\u9215\u5feb\u7167\uff08\u5f71\u97ff review \u7d50\u679c\u7684\u90a3\u5e7e\u7d44\uff1b\u7121 secrets\uff09\u3002\"\"\"\n        out: dict[str, Any] = {}\n        for grp in (self.orchestrator, self.posting, self.review, self.static,\n                    self.repos, self.graph, self.rules, self.knowledge):\n            for name, info in type(grp).model_fields.items():\n                v = getattr(grp, name)\n                if isinstance(v, SecretStr):\n                    continue\n                out[env_names(info)[0]] = str(v) if isinstance(v, Path) else v\n        return out\n\n\nGROUP_ORDER = (\"ado\", \"posting\", \"llm\", \"langfuse\", \"orchestrator\", \"jobs\", \"review\",\n               \"static\", \"repos\", \"graph\", \"rules\", \"knowledge\", \"eval\")\n\n# S1 \u4e4b\u524d\u6709\u610f\u7fa9\u3001\u73fe\u5728\u6574\u7d44\u9000\u5834\u7684\u540d\u5b57\uff1a\u9084\u7559\u5728 env \u6a94\u88e1\u5c31\u63d0\u9192\uff0c\u5225\u8b93\u4eba\u4ee5\u70ba\u5b83\u5011\u9084\u7ba1\u4e8b\u3002\nRETIRED_ENV = (\"HOST\", \"PORT\", \"ADO_TOOLS_PORT\", \"READER_TOOLS_PORT\", \"RESULT_TOOLS_PORT\",\n               \"ADO_TOOLS_URL\", \"READER_TOOLS_URL\", \"RESULT_TOOLS_URL\", \"REPO_ROOT\")\n\n_cached: Settings | None = None\n\n\ndef settings() -> Settings:\n    \"\"\"\u60f0\u6027\u55ae\u4f8b\u3002\u74b0\u5883\u8b8a\u6578\u8b8a\u4e86\u8981\u5148 reset()\uff08tests/conftest.py \u5df2\u81ea\u52d5\u7d81\u4e0a\uff09\u3002\"\"\"\n    global _cached\n    if _cached is None:\n        _cached = Settings()\n    return _cached\n\n\n_reload_hooks: list[Callable[[], None]] = []\n\n\ndef on_reload(fn: Callable[[], None]) -> None:\n    \"\"\"\u8a2d\u5b9a\u91cd\u8f09\u6642\u8981\u8ddf\u8457\u6e05\u7684\u6771\u897f\uff08\u4f8b\u5982 llm \u7684\u9577\u99d0 client\uff09\u5728\u9019\u88e1\u767b\u8a18\u3002\"\"\"\n    if fn not in _reload_hooks:\n        _reload_hooks.append(fn)\n\n\ndef reset() -> None:\n    global _cached, _toml_cache\n    _cached = None\n    _toml_cache = None\n    _toml_ignored_secrets.clear()\n    for fn in _reload_hooks:\n        try:\n            fn()\n        except Exception:  # noqa: BLE001  \u2014\u2014 \u6e05\u5feb\u53d6\u5931\u6557\u4e0d\u8a72\u8b93\u8a2d\u5b9a\u91cd\u8f09\u5931\u6557\n            pass\n\n\ndef fail_fast() -> Settings:\n    \"\"\"\u670d\u52d9\u555f\u52d5\u6642\u547c\u53eb\uff1a\u58de\u503c\u7acb\u523b\u4ee5\u4eba\u8a71\u5831\u932f\u4e26\u9000\u51fa\uff0c\u800c\u4e0d\u662f\u5728\u7b2c\u4e00\u689d review \u4e2d\u6bb5\u624d\u70b8\u3002\"\"\"\n    try:\n        reset()\n        return settings()\n    except ValidationError as e:\n        print(\"\u8a2d\u5b9a\u503c\u6709\u8aa4\uff0c\u670d\u52d9\u4e0d\u555f\u52d5\uff1a\", file=sys.stderr)\n        for err in e.errors():\n            loc = \".\".join(str(x) for x in err[\"loc\"])\n            print(f\"  {loc}: {err['msg']}\uff08\u6536\u5230 {err.get('input')!r}\uff09\", file=sys.stderr)\n        raise SystemExit(1)\n    except (tomllib.TOMLDecodeError, ValueError) as e:\n        print(f\"config.toml \u89e3\u6790\u4e0d\u904e\uff08{config_path()}\uff09\uff1a{e}\", file=sys.stderr)\n        raise SystemExit(1)\n\n\n# ---------- schema \u53cd\u5c04\uff1a--show / --example / doctor \u5171\u7528 ----------\n\ndef env_names(info: FieldInfo) -> list[str]:\n    \"\"\"\u4e00\u500b\u6b04\u4f4d\u8a8d\u5f97\u7684\u74b0\u5883\u8b8a\u6578\u540d\uff08\u7b2c\u4e00\u500b\u662f\u6b63\u540d\uff09\u3002\"\"\"\n    va = info.validation_alias\n    if isinstance(va, AliasChoices):\n        return [c if isinstance(c, str) else \".\".join(map(str, c.path))\n                for c in va.choices]\n    if isinstance(va, str):\n        return [va]\n    return [info.alias] if info.alias else []\n\n\ndef iter_fields() -> Iterator[tuple[str, type[_Group], str, FieldInfo]]:\n    \"\"\"(group \u5c6c\u6027\u540d, group \u985e, \u6b04\u4f4d\u540d, FieldInfo)\uff0c\u4f9d GROUP_ORDER\u3002\"\"\"\n    for gname in GROUP_ORDER:\n        gcls = Settings.model_fields[gname].annotation\n        for fname, info in gcls.model_fields.items():\n            yield gname, gcls, fname, info\n\n\ndef _render_value(v: Any) -> str:\n    if isinstance(v, SecretStr):\n        return v.get_secret_value()\n    if isinstance(v, bool):\n        return \"true\" if v else \"false\"\n    if isinstance(v, list):\n        return \",\".join(v)\n    if v is None:\n        return \"\"\n    if isinstance(v, Path):\n        return v.as_posix()         # Windows dev machine renders \\, Linux is the target\n    return str(v)\n\n\ndef _mask(v: Any) -> str:\n    if isinstance(v, SecretStr):\n        raw = v.get_secret_value()\n        return \"(unset)\" if not raw else f\"***{raw[-4:]}\" if len(raw) > 8 else \"***\"\n    return _render_value(v) or \"(unset)\"\n\n\ndef example_text() -> str:\n    \"\"\"\u7531 schema \u7522\u51fa suite.env.example\uff08\u56db\u500b\u884c\u7a0b\u5171\u7528\u4e00\u4efd\uff09\u3002\"\"\"\n    lines = [\n        \"# pr-review-suite \u5168\u5957\u8a2d\u5b9a \u2014\u2014 \u7531 `python -m shared.settings --example` \u7522\u751f\uff0c\",\n        \"# \u4e0d\u8981\u624b\u6539\u9019\u500b .example\uff1b\u6539 shared/settings.py \u7684 Field \u518d\u91cd\u751f\u3002\",\n        \"# S2 \u8d77\u5efa\u8b70\uff1asecrets \u653e /etc/pr-review-suite/secrets.env\uff08systemd EnvironmentFile\uff09\uff0c\",\n        \"# \u5176\u4ed6\u65cb\u9215\u653e config.toml\uff08\u63a7\u5236\u53f0 Settings \u9801\u5beb\uff1b--migrate \u53ef\u5f9e\u65e2\u6709 env \u4e00\u6b21\u8f49\u904e\u53bb\uff09\u3002\",\n        \"# \u5168\u90e8\u653e env \u4e5f\u4ecd\u7136\u6210\u7acb\uff08env \u6c38\u9060\u512a\u5148\uff09\u2014\u2014\u9019\u4efd\u5c31\u662f\u5168 env \u7248\u3002\",\n        \"#\",\n        \"# systemd \u7684 EnvironmentFile \u4e0d\u652f\u63f4\u884c\u5167\u8a3b\u89e3\uff1a\u8a3b\u89e3\u4e00\u5f8b\u7368\u7acb\u6210\u884c\uff0c\",\n        \"# \u7b49\u865f\u53f3\u908a\u4e0d\u53ef\u6709\u7a7a\u767d\u6216 # \u5c3e\u5df4\uff08\u8840\u6dda\uff1aURL \u6703\u51fa\u73fe %20\uff09\u3002\u542b $ \u6216\u7a7a\u767d\u7684\u503c\u7528\u55ae\u5f15\u865f\u3002\",\n        \"# \u8a3b\u89e3\u6389\u7684\u884c\u4ee3\u8868\u300c\u672a\u8a2d = \u9810\u8a2d\u503c / \u505c\u7528\u300d\uff1b\u8981\u7528\u518d\u6253\u958b\u3002\",\n        \"\",\n    ]\n    for gname in GROUP_ORDER:\n        gcls = Settings.model_fields[gname].annotation\n        lines.append(f\"# {'=' * 72}\")\n        lines.append(f\"# [{gname}] {(gcls.__doc__ or '').strip()}\")\n        lines.append(f\"# {'=' * 72}\")\n        for fname, info in gcls.model_fields.items():\n            names = env_names(info)\n            extra = info.json_schema_extra or {}\n            example = extra.get(\"example\") if isinstance(extra, dict) else None\n            default = info.get_default(call_default_factory=True)\n            lines.append(\"\")\n            for d in (info.description or \"\").split(\"\u3002\"):\n                d = d.strip()\n                if d:\n                    lines.append(f\"# {d}\u3002\" if not d.endswith((\"\uff09\", \")\", \"\\\"\")) else f\"# {d}\")\n            if len(names) > 1:\n                lines.append(f\"# \uff08\u820a\u540d {', '.join(names[1:])} \u4ecd\u8a8d\uff09\")\n            val = example if example is not None else _render_value(default)\n            needs_quote = any(ch in val for ch in \" $\") if val else False\n            shown = f\"'{val}'\" if needs_quote else val\n            required = isinstance(extra, dict) and extra.get(\"required\")\n            if required:\n                # \u4e00\u5b9a\u8981\u586b\u7684\uff08PAT\u3001gateway\u3001\u6a21\u578b\uff09\uff1a\u6253\u958b\u3001\u653e\u4f54\u4f4d\u503c\n                lines.append(f\"{names[0]}={shown}\")\n            elif val == \"\" or example is not None or \"\u5df2\u6dd8\u6c70\" in (info.description or \"\"):\n                # \u672a\u8a2d=\u505c\u7528\u7684\u9078\u914d\u3001\u7bc4\u4f8b\u503c\u4e0d\u662f\u771f\u9810\u8a2d\u3001\u5df2\u6dd8\u6c70\uff1a\u7559\u6210\u8a3b\u89e3\uff0c\u4f7f\u7528\u8005\u81ea\u5df1\u6253\u958b\n                lines.append(f\"# {names[0]}={shown}\")\n            else:\n                lines.append(f\"{names[0]}={shown}\")\n        lines.append(\"\")\n    return \"\\n\".join(lines).rstrip() + \"\\n\"\n\n\ndef source_of(gname: str, fname: str, info: FieldInfo | None = None) -> str:\n    \"\"\"'env:<NAME>' | 'file' | 'default' \u2014\u2014 \u9019\u9846\u503c\u73fe\u5728\u662f\u8ab0\u7d66\u7684\u3002\"\"\"\n    info = info or Settings.model_fields[gname].annotation.model_fields[fname]\n    src = next((n for n in env_names(info) if os.getenv(n, \"\") != \"\"), None)\n    if src:\n        return f\"env:{src}\"\n    if fname in (load_toml().get(gname) or {}) and info.annotation is not SecretStr:\n        return \"file\"\n    return \"default\"\n\n\ndef show_rows(s: Settings | None = None) -> list[tuple[str, str, str, str]]:\n    \"\"\"(group, ENV, \u751f\u6548\u503c(\u906e\u7f69), \u4f86\u6e90) \u2014\u2014 \u7d66 --show \u8207 doctor\u3002\"\"\"\n    s = s or settings()\n    rows = []\n    for gname, _gcls, fname, info in iter_fields():\n        rows.append((gname, env_names(info)[0], _mask(getattr(getattr(s, gname), fname)),\n                     source_of(gname, fname, info)))\n    return rows\n\n\n# ---------- config.toml\uff1a\u5beb\u5165\uff08\u63a7\u5236\u53f0 Settings \u9801\u3001--migrate\uff09 ----------\n\ndef _toml_literal(v: Any) -> str:\n    if isinstance(v, bool):\n        return \"true\" if v else \"false\"\n    if isinstance(v, (int, float)):\n        return repr(v)\n    if isinstance(v, list):\n        return \"[\" + \", \".join(_toml_literal(x) for x in v) + \"]\"\n    if isinstance(v, Path):\n        v = v.as_posix()\n    return json.dumps(str(v), ensure_ascii=False)      # TOML \u57fa\u672c\u5b57\u4e32 = JSON \u5b57\u4e32\u8a9e\u6cd5\n\n\ndef _native(v: Any) -> Any:\n    \"\"\"\u628a settings \u7269\u4ef6\u4e0a\u7684\u503c\u8b8a\u6210\u80fd\u5beb\u9032 toml \u7684\u578b\u5225\u3002\"\"\"\n    if isinstance(v, Path):\n        return v.as_posix()\n    if isinstance(v, SecretStr):\n        return v.get_secret_value()\n    return v\n\n\ndef render_toml(values: dict[str, dict[str, Any]]) -> str:\n    \"\"\"\u7531 schema \u6e32\u67d3\u6574\u4efd config.toml\uff1a\u6bcf\u7d44\u4e00\u5f35\u8868\u3001\u6bcf\u6b04\u9644\u8aaa\u660e\uff1b\u6c92\u7d66\u503c\u7684\u6b04\u4f4d\u7559\u6210\u8a3b\u89e3\u3002\n    secrets \u6b04\u4f4d\u6c38\u9060\u53ea\u51fa\u73fe\u5728\u8a3b\u89e3\u88e1\uff08\u5b83\u5011\u4f4f secrets.env\uff09\u3002\"\"\"\n    lines = [\n        \"# pr-review-suite \u8a2d\u5b9a\uff08env \u6703\u8986\u5beb\u9019\u88e1\uff1bsecrets \u4e0d\u653e\u9019\u88e1\uff0c\u653e secrets.env\uff09\",\n        \"# \u7531\u63a7\u5236\u53f0 Settings \u9801\u6216 `python -m shared.settings --migrate` \u5beb\u5165\uff1b\",\n        \"# \u624b\u6539\u4e5f\u884c\uff0c\u670d\u52d9\u91cd\u8f09\u6642\u6703\u91cd\u8b80\u3002\u6bcf\u500b\u9375\u7684\u8aaa\u660e\u898b\u4e0b\u65b9\u8a3b\u89e3\u3002\",\n        \"\",\n    ]\n    for gname in GROUP_ORDER:\n        gcls = Settings.model_fields[gname].annotation\n        table = values.get(gname) or {}\n        lines.append(f\"[{gname}]\")\n        lines.append(f\"# {(gcls.__doc__ or '').strip()}\")\n        for fname, info in gcls.model_fields.items():\n            desc = \" \".join(d.strip() for d in (info.description or \"\").split(\"\u3002\") if d.strip())\n            env = env_names(info)[0]\n            lines.append(f\"# {fname}  (env {env})\uff1a{desc}\")\n            if info.annotation is SecretStr:\n                lines.append(f\"# {fname} = <secret\uff1a\u53ea\u80fd\u653e secrets.env \u7684 {env}>\")\n            elif fname in table and table[fname] is not None:\n                lines.append(f\"{fname} = {_toml_literal(table[fname])}\")\n            else:\n                default = info.get_default(call_default_factory=True)\n                lines.append(f\"# {fname} = {_toml_literal(_native(default)) if default is not None else '<unset>'}\")\n        lines.append(\"\")\n    return \"\\n\".join(lines)\n\n\ndef changes_log_path() -> Path:\n    return config_path().with_name(\"config-changes.jsonl\")\n\n\ndef validate_group_values(gname: str, values: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"\u7528 schema \u9a57\u4e00\u7d44\u300c\u6b04\u4f4d\u540d \u2192 \u503c\u300d\uff08\u4e0d\u5408\u4f75 env\uff1b\u63a7\u5236\u53f0\u8868\u55ae\u5c08\u7528\uff09\u3002\u56de\u6b63\u898f\u5316\u5f8c\u7684\u503c\uff1b\u58de\u503c raise ValidationError\u3002\"\"\"\n    gcls = Settings.model_fields[gname].annotation\n    obj = gcls.model_validate(values)           # model_validate \u4e0d\u8dd1 env \u4f86\u6e90\uff0c\u7d14\u9a57\u503c\n    return {k: _native(getattr(obj, k)) for k in values}\n\n\ndef save_toml(changes: dict[str, dict[str, Any]], actor: str = \"console\") -> list[dict]:\n    \"\"\"\u628a changes\uff08group \u2192 field \u2192 \u503c\uff1b\u503c\u70ba None = \u522a\u6389\u9019\u500b\u9375\u3001\u56de\u9810\u8a2d\uff09\u5beb\u9032 config.toml\u3002\n\n    \u9806\u5e8f\uff1a\u9a57\u503c \u2192 \u8b80\u73fe\u6a94 \u2192 \u5408\u4f75 \u2192 \u5099\u4efd config.toml.bak-<ts> \u2192 \u539f\u5b50\u5beb\u5165 \u2192 \u5beb change log\n    \u2192 reset()\uff08\u4e0b\u4e00\u6b21 settings() \u5c31\u662f\u65b0\u503c\uff09\u3002secrets \u6b04\u4f4d\u4e00\u5f8b\u62d2\u7d55\u3002\n    \u56de\u50b3\u6bcf\u7b46\u8b8a\u52d5 {group, field, old, new}\u3002\n    \"\"\"\n    current = {g: dict(t) for g, t in load_toml().items() if isinstance(t, dict)}\n    before = settings()\n    log: list[dict] = []\n    for gname, fields in changes.items():\n        gcls = Settings.model_fields[gname].annotation\n        clean = {k: v for k, v in fields.items() if v is not None}\n        if clean:\n            clean = validate_group_values(gname, clean)\n        for fname, v in fields.items():\n            info = gcls.model_fields[fname]\n            if info.annotation is SecretStr:\n                raise ValueError(f\"{gname}.{fname} \u662f secret\uff0c\u53ea\u80fd\u653e secrets.env\uff08{env_names(info)[0]}\uff09\")\n            old = _native(getattr(getattr(before, gname), fname))\n            table = current.setdefault(gname, {})\n            if v is None:\n                table.pop(fname, None)\n                new = _native(info.get_default(call_default_factory=True))\n            else:\n                table[fname] = clean[fname]\n                new = clean[fname]\n            if old != new:\n                log.append({\"group\": gname, \"field\": fname, \"env\": env_names(info)[0],\n                            \"old\": old, \"new\": new})\n    p = config_path()\n    p.parent.mkdir(parents=True, exist_ok=True)\n    text = render_toml(current)\n    tomllib.loads(text)                          # \u5beb\u51fa\u53bb\u4e4b\u524d\u5148\u78ba\u5b9a\u81ea\u5df1\u8b80\u5f97\u56de\u4f86\n    if p.exists():\n        shutil.copy2(p, p.with_name(f\"{p.name}.bak-{time.strftime('%Y%m%d-%H%M%S')}\"))\n    tmp = p.with_suffix(\".toml.tmp\")\n    tmp.write_text(text, encoding=\"utf-8\", newline=\"\\n\")\n    os.replace(tmp, p)\n    if log:\n        with changes_log_path().open(\"a\", encoding=\"utf-8\") as f:\n            for entry in log:\n                f.write(json.dumps({\"ts\": time.time(), \"actor\": actor, **entry},\n                                   ensure_ascii=False, default=str) + \"\\n\")\n    reset()\n    return log\n\n\ndef recent_changes(limit: int = 20) -> list[dict]:\n    p = changes_log_path()\n    if not p.exists():\n        return []\n    rows = [json.loads(ln) for ln in p.read_text(encoding=\"utf-8\").splitlines() if ln.strip()]\n    return rows[-limit:][::-1]\n\n\ndef migrate_from_env() -> tuple[dict[str, dict[str, Any]], list[str]]:\n    \"\"\"\u628a\u76ee\u524d env \u88e1\u300c\u975e\u9810\u8a2d\u3001\u975e secret\u300d\u7684\u503c\u6574\u7406\u6210 toml values\uff1bsecrets \u53e6\u5217\u6210 env \u884c\u3002\"\"\"\n    s = settings()\n    values: dict[str, dict[str, Any]] = {}\n    secret_lines: list[str] = []\n    for gname, gcls, fname, info in iter_fields():\n        names = env_names(info)\n        raw = next((os.getenv(n) for n in names if os.getenv(n, \"\") != \"\"), None)\n        if raw is None:\n            continue\n        if info.annotation is SecretStr:\n            secret_lines.append(f\"{names[0]}={raw}\")\n            continue\n        v = _native(getattr(getattr(s, gname), fname))\n        default = _native(info.get_default(call_default_factory=True))\n        if v != default:\n            values.setdefault(gname, {})[fname] = v\n    return values, secret_lines\n\n\ndef warnings_for(s: Settings | None = None) -> list[str]:\n    \"\"\"\u8a2d\u5b9a\u5c64\u5c31\u770b\u5f97\u51fa\u4f86\u7684\u554f\u984c\uff08\u4e0d\u6253\u7db2\u8def\uff1b\u90a3\u662f doctor \u7684\u4e8b\uff09\u3002\"\"\"\n    s = s or settings()\n    out: list[str] = []\n    if _toml_ignored_secrets:\n        out.append(\"config.toml \u88e1\u653e\u4e86 secret \u6b04\u4f4d\uff0c\u5df2\u5ffd\u7565\uff08secrets \u53ea\u80fd\u8d70 secrets.env\uff09\uff1a\"\n                   + \", \".join(_toml_ignored_secrets))\n    stale = [n for n in RETIRED_ENV if os.getenv(n, \"\")]\n    if stale:\n        out.append(\"\u9019\u4e9b\u8b8a\u6578\u5df2\u7121\u4f5c\u7528\uff08\u2460\u2461\u2462 \u5df2\u4f75\u5165 orchestrator \u884c\u7a0b\u3001\u2461 \u5df2\u79fb\u9664\uff09\uff0c\"\n                   f\"\u5f9e env \u6a94\u522a\u6389\uff1a{', '.join(stale)}\")\n    if s.orchestrator.auto_post and s.posting.dry_run:\n        out.append(\"AUTO_POST=true \u4f46 DRY_RUN=true\uff1areview \u6703\u300c\u5047\u767c\u300d\u2014\u2014\u53ea\u56de\u9810\u89bd\u3002\"\n                   \"\uff08\u9019\u662f\u51fa\u5ee0\u5b89\u5168\u5074\uff0c\u78ba\u8a8d\u8981\u771f\u767c\u518d\u7ffb DRY_RUN\uff09\")\n    if s.jobs.harvest_interval_min and s.knowledge.root is None:\n        pass                      # harvest \u53ea\u5728 KNOWLEDGE_ROOT \u6709\u8a2d\u6642\u6392\uff0c\u4e0d\u7b97\u554f\u984c\n    if s.knowledge.root is not None and not s.knowledge.root.is_dir():\n        out.append(f\"KNOWLEDGE_ROOT \u6307\u5411\u4e0d\u5b58\u5728\u7684\u76ee\u9304\uff1a{s.knowledge.root}\uff08K \u6bb5\u8996\u540c\u505c\u7528\uff09\")\n    if s.rules.root is not None and not s.rules.root.is_dir():\n        out.append(f\"RULES_ROOT \u6307\u5411\u4e0d\u5b58\u5728\u7684\u76ee\u9304\uff1a{s.rules.root}\uff08\u898f\u5247\u8996\u540c\u505c\u7528\uff09\")\n    if s.repos.repos_root is not None and not s.repos.repos_root.is_dir():\n        out.append(f\"REPOS_ROOT \u6307\u5411\u4e0d\u5b58\u5728\u7684\u76ee\u9304\uff1a{s.repos.repos_root}\uff08\u6c92\u6709 base \u4e0a\u4e0b\u6587\uff09\")\n    if s.graph.tools_url and not s.graph.tool_blast:\n        out.append(\"GRAPH_TOOLS_URL \u6709\u8a2d\u4f46 GRAPH_TOOL_BLAST \u6c92\u8a2d\uff1agraph \u4e0d\u6703\u555f\u7528\u3002\")\n    if s.knowledge.redistill and s.knowledge.root and not s.orchestrator.api_key.get_secret_value():\n        out.append(\"KNOWLEDGE_REDISTILL=true \u4f46 ORCH_API_KEY \u672a\u8a2d\uff1a/knowledge/redistill \u7121\u8a8d\u8b49\u3002\")\n    return out\n\n\ndef _main(argv: list[str]) -> int:\n    import argparse\n    ap = argparse.ArgumentParser(prog=\"python -m shared.settings\")\n    g = ap.add_mutually_exclusive_group(required=True)\n    g.add_argument(\"--show\", action=\"store_true\", help=\"\u76ee\u524d\u751f\u6548\u503c\u8207\u4f86\u6e90\uff08secrets \u906e\u7f69\uff09\")\n    g.add_argument(\"--example\", action=\"store_true\", help=\"\u7531 schema \u7522\u751f suite.env.example\")\n    g.add_argument(\"--example-toml\", action=\"store_true\", help=\"\u7531 schema \u7522\u751f config.toml \u6a23\u677f\")\n    g.add_argument(\"--migrate\", action=\"store_true\",\n                   help=\"\u76ee\u524d env \u7684\u975e\u9810\u8a2d\u503c\u5beb\u6210 CONFIG_DIR/config.toml\uff1bsecrets \u5370\u51fa\u4f86\u8b93\u4f60\u653e secrets.env\")\n    g.add_argument(\"--check\", action=\"store_true\", help=\"\u53ea\u9a57\u8b49\uff1b\u58de\u503c\u56de\u50b3\u78bc 1\")\n    a = ap.parse_args(argv)\n\n    if a.example:\n        sys.stdout.write(example_text())\n        return 0\n    if a.example_toml:\n        sys.stdout.write(render_toml({}))\n        return 0\n    if a.migrate:\n        values, secret_lines = migrate_from_env()\n        log = save_toml(values, actor=\"migrate\")\n        print(f\"\u5df2\u5beb\u5165 {config_path()}\uff08{sum(len(t) for t in values.values())} \u500b\u975e\u9810\u8a2d\u503c\uff0c\"\n              f\"{len(log)} \u500b\u8207\u751f\u6548\u503c\u4e0d\u540c\uff09\")\n        if secret_lines:\n            print(\"\\n\u9019\u5e7e\u884c\u662f secret\uff0c\u4e0d\u9032 toml\uff1b\u653e\u5230 secrets.env\uff08chmod 600\uff09\u4e26\u7531 systemd EnvironmentFile \u8f09\u5165\uff1a\")\n            for ln in secret_lines:\n                k, _v = ln.split(\"=\", 1)\n                print(f\"  {k}=\u2026\")\n        return 0\n    try:\n        s = Settings()\n    except ValidationError as e:\n        print(\"\u8a2d\u5b9a\u503c\u6709\u8aa4\uff1a\")\n        for err in e.errors():\n            print(f\"  {'.'.join(map(str, err['loc']))}: {err['msg']}\uff08\u6536\u5230 {err.get('input')!r}\uff09\")\n        return 1\n    if a.check:\n        print(\"\u8a2d\u5b9a OK\")\n    else:\n        w = max(len(r[1]) for r in show_rows(s))\n        cur = None\n        for grp, name, val, src in show_rows(s):\n            if grp != cur:\n                print(f\"\\n[{grp}]\")\n                cur = grp\n            print(f\"  {name:<{w}}  {val:<40}  {src}\")\n    warns = warnings_for(s)\n    if warns:\n        print(\"\\n\u6ce8\u610f\uff1a\")\n        for ln in warns:\n            print(f\"  - {ln}\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(_main(sys.argv[1:]))\n"}
{"path":"tests/conftest.py","perm":"0644","sha":"a4a3612d90ef0b803748d291ec9b996253c504c339a9f5828fa939bf0f90389c","data":"\"\"\"\u6e2c\u8a66\u5171\u7528\uff1a\u8a2d\u5b9a\u5feb\u53d6\u8207\u74b0\u5883\u8b8a\u6578\u7d81\u6b7b\u3002\n\nshared.settings.settings() \u662f\u60f0\u6027\u55ae\u4f8b\uff1b\u6e2c\u8a66\u7528 monkeypatch.setenv \u6539\u74b0\u5883\u8b8a\u6578\u5f8c\n\u5fc5\u9808\u8b93\u5b83\u91cd\u8b80\u3002\u9019\u88e1\u628a MonkeyPatch.setenv / delenv \u7d81\u4e0a reset()\uff0c\u65e2\u6709 60+ \u689d\u6e2c\u8a66\n\u4e0d\u7528\u6539\u4e00\u884c\uff1b\u6bcf\u689d\u6e2c\u8a66\u958b\u982d\u8207\u7d50\u5c3e\u4e5f\u5404\u6e05\u4e00\u6b21\uff0c\u6e2c\u8a66\u4e4b\u9593\u4e0d\u6703\u4e92\u76f8\u6c59\u67d3\u3002\n\"\"\"\nimport pytest\n\nimport shared.settings as S\n\n\n@pytest.fixture(autouse=True)\ndef _fresh_settings(monkeypatch, tmp_path):\n    S.reset()\n    # review \u6b77\u53f2\uff08SQLite\uff09\u8207 config.toml \u6c38\u9060\u5beb\u5728\u9019\u689d\u6e2c\u8a66\u81ea\u5df1\u7684 tmp \u88e1\uff0c\u4e0d\u78b0\u771f\u8def\u5f91\n    monkeypatch.setenv(\"DATA_DIR\", str(tmp_path / \"data\"))\n    monkeypatch.setenv(\"CONFIG_DIR\", str(tmp_path / \"cfg\"))\n    orig_set, orig_del = pytest.MonkeyPatch.setenv, pytest.MonkeyPatch.delenv\n\n    def setenv(self, *a, **k):\n        orig_set(self, *a, **k)\n        S.reset()\n\n    def delenv(self, *a, **k):\n        orig_del(self, *a, **k)\n        S.reset()\n\n    monkeypatch.setattr(pytest.MonkeyPatch, \"setenv\", setenv)\n    monkeypatch.setattr(pytest.MonkeyPatch, \"delenv\", delenv)\n    yield\n    S.reset()\n"}
{"path":"tests/test_config_toml.py","perm":"0644","sha":"8ee7acddb853fc93d97db6b4a9fe443c593a84cdb1981f2b7d19ec4d4abde3c2","data":"\"\"\"config.toml \u9019\u4e00\u5c64\u7684\u9396\uff1aenv > toml > \u9810\u8a2d\uff1bsecrets \u4e0d\u9032 toml\uff1bsave \u6703\u5099\u4efd\u3001\u8a18\u9304\u3001\u91cd\u8f09\u3002\u5168\u96e2\u7dda\u3002\"\"\"\nimport json\nimport tomllib\n\nimport pytest\nfrom pydantic import ValidationError\n\nimport shared.settings as S\n\n\n@pytest.fixture\ndef cfg(tmp_path, monkeypatch):\n    for _g, _c, _f, info in S.iter_fields():\n        for n in S.env_names(info):\n            monkeypatch.delenv(n, raising=False)\n    monkeypatch.setenv(\"CONFIG_DIR\", str(tmp_path))\n    return tmp_path\n\n\ndef test_toml_is_second_source_and_env_still_wins(cfg, monkeypatch):\n    (cfg / \"config.toml\").write_text(\n        '[review]\\nmax_findings = 7\\n[llm]\\nmodel = \"qwen\"\\n[knowledge]\\nbranches = [\"main\", \"release/*\"]\\n',\n        encoding=\"utf-8\")\n    S.reset()\n    s = S.settings()\n    assert s.review.max_findings == 7 and s.llm.model == \"qwen\"\n    assert s.knowledge.branches == [\"main\", \"release/*\"]\n    assert S.source_of(\"review\", \"max_findings\") == \"file\"\n    monkeypatch.setenv(\"REVIEW_MAX_FINDINGS\", \"9\")\n    assert S.settings().review.max_findings == 9\n    assert S.source_of(\"review\", \"max_findings\") == \"env:REVIEW_MAX_FINDINGS\"\n    assert S.source_of(\"review\", \"max_parallel\") == \"default\"\n\n\ndef test_secret_in_toml_is_ignored_and_warned(cfg):\n    (cfg / \"config.toml\").write_text('[ado]\\npat = \"leaked\"\\ndiff_max_files = 5\\n', encoding=\"utf-8\")\n    S.reset()\n    s = S.settings()\n    assert s.ado.pat.get_secret_value() == \"\"          # \u6c92\u5403\n    assert s.ado.diff_max_files == 5                    # \u540c\u8868\u7684\u975e secret \u7167\u5403\n    assert any(\"ado.pat\" in w for w in S.warnings_for(s))\n\n\ndef test_bad_toml_value_fails_like_bad_env(cfg):\n    (cfg / \"config.toml\").write_text(\"[review]\\nmax_findings = 0\\n\", encoding=\"utf-8\")\n    S.reset()\n    with pytest.raises(ValidationError):\n        S.settings()\n\n\ndef test_save_writes_backup_log_and_reloads(cfg):\n    S.reset()\n    assert S.settings().review.max_findings == 30\n    log = S.save_toml({\"review\": {\"max_findings\": 12}, \"llm\": {\"model\": \"big\"}}, actor=\"t\")\n    assert {(e[\"env\"], e[\"old\"], e[\"new\"]) for e in log} == {\n        (\"REVIEW_MAX_FINDINGS\", 30, 12), (\"LLM_MODEL\", \"gpt-4o-mini\", \"big\")}\n    assert S.settings().review.max_findings == 12          # save \u5167\u90e8 reset \u4e86\n    data = tomllib.loads((cfg / \"config.toml\").read_text(encoding=\"utf-8\"))\n    assert data == {\"review\": {\"max_findings\": 12}, \"llm\": {\"model\": \"big\"}} or \\\n        {k: v for k, v in data.items() if v} == {\"review\": {\"max_findings\": 12}, \"llm\": {\"model\": \"big\"}}\n    assert not list(cfg.glob(\"config.toml.bak-*\"))         # \u7b2c\u4e00\u6b21\u6c92\u6709\u820a\u6a94\u53ef\u5099\n\n    S.save_toml({\"review\": {\"max_findings\": None}}, actor=\"t\")   # None = \u56de\u9810\u8a2d\n    assert S.settings().review.max_findings == 30\n    assert len(list(cfg.glob(\"config.toml.bak-*\"))) == 1\n    rows = [json.loads(ln) for ln in (cfg / \"config-changes.jsonl\").read_text(encoding=\"utf-8\").splitlines()]\n    assert [r[\"new\"] for r in rows if r[\"env\"] == \"REVIEW_MAX_FINDINGS\"] == [12, 30]\n    assert S.recent_changes(1)[0][\"actor\"] == \"t\"\n\n\ndef test_save_refuses_secret_and_bad_value(cfg):\n    S.reset()\n    with pytest.raises(ValueError):\n        S.save_toml({\"ado\": {\"pat\": \"x\"}})\n    with pytest.raises(ValidationError):\n        S.save_toml({\"review\": {\"min_confidence\": 1.5}})\n    assert not (cfg / \"config.toml\").exists()               # \u5169\u6b21\u90fd\u6c92\u5beb\u6a94\n\n\ndef test_render_toml_is_valid_and_documents_every_field(cfg):\n    text = S.render_toml({\"review\": {\"max_findings\": 3}, \"repos\": {\"repos_root\": \"/opt/repos\"}})\n    data = tomllib.loads(text)\n    assert data[\"review\"] == {\"max_findings\": 3} and data[\"repos\"] == {\"repos_root\": \"/opt/repos\"}\n    for gname, _c, fname, _i in S.iter_fields():\n        assert f\"# {fname}  (env \" in text or f\"\\n{fname} = \" in text, (gname, fname)\n    assert \"ADO_PAT>\" in text and \"pat = \" not in text.replace(\"# pat = <secret\", \"\")\n\n\ndef test_migrate_moves_non_default_non_secret_env_into_toml(cfg, monkeypatch):\n    monkeypatch.setenv(\"REVIEW_MAX_FINDINGS\", \"5\")\n    monkeypatch.setenv(\"REVIEW_MAX_PARALLEL\", \"6\")         # \u7b49\u65bc\u9810\u8a2d \u2192 \u4e0d\u5beb\n    monkeypatch.setenv(\"ADO_PAT\", \"pat123\")\n    monkeypatch.setenv(\"KNOWLEDGE_BRANCHES\", \"master,release/*\")\n    values, secrets = S.migrate_from_env()\n    assert values == {\"review\": {\"max_findings\": 5}, \"knowledge\": {\"branches\": [\"master\", \"release/*\"]}}\n    assert secrets == [\"ADO_PAT=pat123\"]\n    S.save_toml(values, actor=\"migrate\")\n    assert tomllib.loads((cfg / \"config.toml\").read_text(encoding=\"utf-8\"))[\"review\"] == {\"max_findings\": 5}\n\n\ndef test_reload_hooks_fire_on_reset():\n    hits = []\n    S.on_reload(lambda: hits.append(1))\n    S.reset(); S.reset()\n    assert hits == [1, 1]\n    S._reload_hooks.remove(S._reload_hooks[-1])\n"}
{"path":"tests/test_console.py","perm":"0644","sha":"83cb7161a432600113cb899989658397fdd1c92005d1d616fe84e37e7a741785","data":"\"\"\"\u63a7\u5236\u53f0\uff08/console\uff09\u7684\u9396\uff1a\u8a8d\u8b49\u3001\u5169\u9801\u6e32\u67d3\u3001Apply \u7684\u9a57\u8b49\u8207\u5371\u96aa\u65cb\u9215\u3001env \u8986\u5beb\u552f\u8b80\u3002\u5168\u96e2\u7dda\u3002\"\"\"\nimport pytest\nfrom fastapi.testclient import TestClient\n\nimport shared.doctor as D\nimport shared.settings as S\n\n\n@pytest.fixture\ndef client(tmp_path, monkeypatch):\n    for _g, _c, _f, info in S.iter_fields():\n        for n in S.env_names(info):\n            monkeypatch.delenv(n, raising=False)\n    monkeypatch.setenv(\"CONFIG_DIR\", str(tmp_path))\n    monkeypatch.setenv(\"ADO_PAT\", \"pat\")\n    # overview \u6703\u8dd1 doctor\uff1a\u628a\u7db2\u8def\u63a2\u91dd\u5168\u90e8 stub \u6389\n    monkeypatch.setattr(D, \"_tcp_open\", lambda h, p, timeout=0: True)\n    monkeypatch.setattr(D, \"_http_get\", lambda url, **kw: (200, {\"ok\": True, \"jobs\": {}}, \"\"))\n    monkeypatch.setattr(D, \"_which\", lambda b: None)\n    monkeypatch.setattr(D, \"_run\", lambda cmd, timeout=0: (0, \"\"))\n    import orchestrator.app as A\n    import orchestrator.console.router as R\n    R._doctor_cache.update(ts=0.0, checks=[])\n    with TestClient(A.app) as c:\n        yield c\n\n\ndef test_open_mode_without_key_shows_banner(client):\n    r = client.get(\"/console\")\n    assert r.status_code == 200 and \"\u958b\u653e\u6a21\u5f0f\" in r.text and \"ORCH_API_KEY \u672a\u8a2d\" in r.text\n    assert client.get(\"/console/static/console.css\").status_code == 200\n\n\ndef test_key_requires_login_and_cookie_works(client, monkeypatch):\n    monkeypatch.setenv(\"ORCH_API_KEY\", \"k3y\")\n    r = client.get(\"/console/settings\", follow_redirects=False)\n    assert r.status_code == 302 and \"/console/login\" in r.headers[\"location\"]\n    r = client.post(\"/console/login\", data={\"token\": \"wrong\", \"next\": \"/console/settings\"},\n                    follow_redirects=False)\n    assert \"error=1\" in r.headers[\"location\"]\n    r = client.post(\"/console/login\", data={\"token\": \"k3y\", \"next\": \"/console/settings\"},\n                    follow_redirects=False)\n    assert r.status_code == 302 and r.headers[\"location\"] == \"/console/settings\"\n    assert client.get(\"/console/settings\").status_code == 200\n    client.post(\"/console/logout\")\n    assert client.get(\"/console/settings\", follow_redirects=False).status_code == 302\n\n\ndef test_settings_page_lists_every_group_with_sources(client, monkeypatch):\n    monkeypatch.setenv(\"REVIEW_MAX_FINDINGS\", \"4\")\n    r = client.get(\"/console/settings\")\n    assert r.status_code == 200\n    for g in S.GROUP_ORDER:\n        assert f'data-group=\"{g}\"' in r.text\n    assert \"env:REVIEW_MAX_FINDINGS\" in r.text and \"\u7531\u74b0\u5883\u8b8a\u6578\u8986\u5beb\" in r.text\n    assert \"\u50c5\u80fd\u7531 secrets.env\" in r.text\n\n\ndef test_apply_writes_toml_and_hot_reloads(client, tmp_path):\n    r = client.post(\"/console/settings/review\", data={\"max_findings\": \"12\"})\n    assert r.status_code == 200 and \"\u5df2\u5957\u7528\uff081 \u9805\uff09\" in r.text\n    assert S.settings().review.max_findings == 12\n    assert (tmp_path / \"config.toml\").exists()\n    assert \"REVIEW_MAX_FINDINGS\" in (tmp_path / \"config-changes.jsonl\").read_text(encoding=\"utf-8\")\n    r = client.post(\"/console/settings/review\", data={\"max_findings\": \"\"})\n    assert \"\u5df2\u5957\u7528\uff081 \u9805\uff09\" in r.text and S.settings().review.max_findings == 30\n\n\ndef test_apply_rejects_bad_values_inline(client):\n    r = client.post(\"/console/settings/review\", data={\"max_findings\": \"abc\"})\n    assert r.status_code == 200 and \"\u9808\u70ba\u6578\u5b57\" in r.text and S.settings().review.max_findings == 30\n    r = client.post(\"/console/settings/review\", data={\"min_confidence\": \"1.5\"})\n    assert \"has-err\" in r.text and S.settings().review.min_confidence == 0.55\n\n\ndef test_dangerous_flip_needs_confirmation(client):\n    r = client.post(\"/console/settings/posting\", data={\"_b_dry_run\": \"1\"})     # \u95dc\u6389 DRY_RUN\n    assert \"\u9700\u52fe\u9078\u78ba\u8a8d\" in r.text and S.settings().posting.dry_run is True\n    r = client.post(\"/console/settings/posting\", data={\"_b_dry_run\": \"1\", \"confirm_dry_run\": \"on\"})\n    assert \"\u5df2\u5957\u7528\" in r.text and S.settings().posting.dry_run is False\n    # \u7ffb\u56de\u5b89\u5168\u5074\u4e0d\u7528\u78ba\u8a8d\n    r = client.post(\"/console/settings/posting\", data={\"_b_dry_run\": \"1\", \"dry_run\": \"on\"})\n    assert \"\u5df2\u5957\u7528\" in r.text and S.settings().posting.dry_run is True\n\n\ndef test_env_locked_and_secret_fields_are_ignored_on_apply(client, monkeypatch):\n    monkeypatch.setenv(\"REVIEW_MAX_FINDINGS\", \"4\")\n    r = client.post(\"/console/settings/review\", data={\"max_findings\": \"99\", \"max_parallel\": \"3\"})\n    assert \"\u5df2\u5957\u7528\uff081 \u9805\uff09\" in r.text\n    assert S.settings().review.max_findings == 4 and S.settings().review.max_parallel == 3\n    r = client.post(\"/console/settings/ado\", data={\"pat\": \"newpat\", \"diff_max_files\": \"50\"})\n    assert \"\u5df2\u5957\u7528\uff081 \u9805\uff09\" in r.text and S.settings().ado.pat.get_secret_value() == \"pat\"\n\n\ndef test_absent_checkbox_does_not_flip_bool(client):\n    r = client.post(\"/console/settings/review\", data={\"max_findings\": \"11\"})   # \u6c92\u5e36 adversary\n    assert \"\u5df2\u5957\u7528\uff081 \u9805\uff09\" in r.text and S.settings().review.adversary is True\n\n\ndef test_run_job_button_redirects_and_unknown_group_404(client):\n    r = client.post(\"/console/jobs/repo-sync/run\", follow_redirects=False)\n    assert r.status_code == 303\n    assert client.post(\"/console/settings/nope\", data={}).status_code == 404\n\n\ndef test_untouched_text_field_with_non_string_default_is_not_written(client, tmp_path):\n    \"\"\"\u8868\u55ae\u628a ADO_VERIFY_SSL \u9001\u6210\u5b57\u4e32 \"true\"\uff1b\u9810\u8a2d\u662f bool True \u2014\u2014 \u4e0d\u8a72\u88ab\u7576\u6210\u6539\u52d5\u5beb\u9032 toml\u3002\"\"\"\n    r = client.post(\"/console/settings/ado\", data={\"verify_ssl\": \"true\", \"diff_max_files\": \"250\"})\n    assert \"\u5df2\u5957\u7528\uff081 \u9805\uff09\" in r.text\n    assert \"verify_ssl\" not in (tmp_path / \"config.toml\").read_text(encoding=\"utf-8\").replace(\"# verify_ssl\", \"\")\n    assert S.source_of(\"ado\", \"verify_ssl\") == \"default\" and S.source_of(\"ado\", \"diff_max_files\") == \"file\"\n"}
{"path":"tests/test_core.py","perm":"0644","sha":"4775993a39d0fa11b1b1e426c4d9f5d483823bc169f4cfa7bf3e6ee991498ae7","data":"\"\"\"\u78ba\u5b9a\u6027\u5c64\u7684 pytest \u9396 \u2014\u2014 \u627f\u91cd\u7246\u4e0d\u80fd\u53ea\u9760\u7cfb\u7d71\u7d1a eval \u4fdd\u8b77\u3002\n\u5168\u90e8\u96e2\u7dda\u3001\u96f6 LLM\u3001\u96f6\u7db2\u8def\uff1bharvest \u7684 ADO \u8584\u5c01\u88dd\u5929\u751f\u662f stub \u9ede\u3002\n\u8dd1\u6cd5\uff1avenv/bin/python -m pytest -q tests/\n\"\"\"\nimport contextlib\nimport json\nimport pathlib\nimport tempfile\n\nimport asyncio\nimport types\n\nimport pytest\n\nfrom orchestrator.anatomy import parse_diff\n\n\n# ---------- anatomy ----------\n\ndef test_anatomy_line_numbering_and_added_set():\n    diff = (\"--- a/src/A.java\\n+++ b/src/A.java\\n@@ -10,4 +10,5 @@\\n\"\n            \" ctx\\n ctx\\n+added\\n ctx\\n ctx\\n\")\n    ana = parse_diff(diff)\n    fc = ana.files[0]\n    assert fc.added_linenos == {12}\n    assert [(t, n) for h in fc.hunks for t, n, _ in h.lines][2] == (\"+\", 12)\n\n\n# ---------- diff \u5e7e\u4f55 predicates\uff08\u4f4f anatomy\uff0cpipeline / knowledge \u5171\u7528\uff09 ----------\n\ndef test_match_path_segment_boundary():\n    from orchestrator.anatomy import match_path\n    assert match_path(\"src/cache/SessionCache.java\", \"cache/SessionCache.java\")\n    assert not match_path(\"src/cache/SessionCache.java\", \"Cache.java\")\n\n\ndef test_line_near_vs_line_in_view():\n    from orchestrator.anatomy import line_in_view, line_near\n    diff = (\"--- a/src/A.java\\n+++ b/src/A.java\\n@@ -10,7 +10,8 @@\\n\"\n            \" c10\\n c11\\n+a12\\n c13\\n c14\\n c15\\n c16\\n c17\\n\")\n    ana = parse_diff(diff)\n    assert line_near(ana, \"src/A.java\", 13)           # added\u00b12\n    assert not line_near(ana, \"src/A.java\", 16)\n    assert line_in_view(ana, \"src/A.java\", 16)         # context \u884c\u5728\u8996\u91ce\n\n\ndef test_slices_budget_reports_skipped(monkeypatch):\n    from orchestrator import pipeline as pl\n    monkeypatch.setenv(\"REVIEWER_SLICES_MAX_CHARS\", \"800\")\n    diff = \"\\n\".join(\n        f\"--- /dev/null\\n+++ b/src/f{i}.java\\n@@ -0,0 +1,6 @@\\n\"\n        + \"\\n\".join(f\"+line{k} of file {i} with some padding text\" for k in range(6))\n        for i in range(6)) + \"\\n\"\n\n    class D:\n        files: list = []\n        name = \"X\"\n        focus = \"\"\n        hypotheses: list = []\n\n    text, skipped = pl._slices_for(D(), parse_diff(diff))\n    assert skipped and \"omitted\" in text\n\n\n# ---------- static\uff1aMISSING-TEST \u4fdd\u5e95\u8de8\u8a9e\u8a00 ----------\n\n@pytest.mark.parametrize(\"fname,decl\", [\n    (\"src/pkg/handler.go\", \"func HandlePing(w http.ResponseWriter) {\"),\n    (\"src/app/Service.kt\", \"fun computeTotal(x: Int): Int {\"),\n    (\"src/app/Svc.java\", \"public int run(int x) {\"),\n])\ndef test_missing_test_fires_per_language(fname, decl, monkeypatch):\n    monkeypatch.setenv(\"STATIC_MISSING_TEST\", \"true\")\n    from orchestrator.static_pass import _missing_test\n    diff = (f\"--- /dev/null\\n+++ b/{fname}\\n@@ -0,0 +1,3 @@\\n\"\n            f\"+package x\\n+{decl}\\n+}}\\n\")\n    finds = _missing_test(parse_diff(diff))\n    assert finds and finds[0].rule == \"MISSING-TEST\"\n\n\n# ---------- knowledge\uff1aK1 \u9598\u9580 ----------\n\n@pytest.fixture()\ndef kroot(monkeypatch):\n    root = pathlib.Path(tempfile.mkdtemp())\n    monkeypatch.setenv(\"KNOWLEDGE_ROOT\", str(root))\n    monkeypatch.setenv(\"KNOWLEDGE_BRANCHES\", \"release/*,master\")\n    monkeypatch.setenv(\"KNOWLEDGE_CYCLE_SOURCE\", \"release/*\")\n    monkeypatch.setenv(\"KNOWLEDGE_CYCLE_TARGET\", \"master\")\n    monkeypatch.setenv(\"KNOWLEDGE_DIGEST_LLM\", \"false\")   # \u6e2c\u8a66\u96f6 LLM\uff1a\u9867\u554f\u5206\u6790\u95dc\n    return root\n\n\ndef test_gate_matrix(kroot):\n    from orchestrator.knowledge import gate\n    ok, _ = gate({\"target_branch\": \"refs/heads/release/2026.09\",\n                  \"source_branch\": \"refs/heads/feature/x\",\n                  \"title\": \"fix NPE\"}, [\"/src/A.java\"])\n    assert ok\n    assert not gate({\"target_branch\": \"refs/heads/feature/y\",\n                     \"source_branch\": \"refs/heads/z\", \"title\": \"t\"}, [\"/a\"])[0]\n    assert not gate({\"target_branch\": \"refs/heads/master\",\n                     \"source_branch\": \"refs/heads/x\",\n                     \"title\": \"t\"}, [\"/pom.xml\"])[0]\n    assert gate({\"target_branch\": \"refs/heads/master\",\n                 \"source_branch\": \"refs/heads/x\",\n                 \"title\": 'Revert \"x\"'}, [\"/pom.xml\"])[0]\n    assert not gate({\"target_branch\": \"refs/heads/master\",\n                     \"source_branch\": \"refs/heads/release/2026.09\",\n                     \"title\": \"Release\"}, [\"/src/A.java\"])[0]   # \u9a57\u6536 PR \u8c41\u514d\n    assert not gate({\"target_branch\": \"refs/heads/master\",\n                     \"source_branch\": \"refs/heads/x\",\n                     \"title\": \"Merge master into release/1.2\"},\n                    [\"/src/A.java\"])[0]                          # ADO merge-sync\n\n\n# ---------- harvest\uff1a\u843d\u5730\u7d2f\u7a4d\u3001\u672a\u77e5\u6bb5\u524d\u6efe\u3001reject \u908a\u754c\u3001watermark ----------\n\ndef _draft(entity, **kw):\n    d = {\"summary\": \"s\", \"type\": \"bugfix\", \"intent_stated\": True,\n         \"primary_entity\": entity, \"decisions\": [], \"invariants\": [],\n         \"affected\": [], \"supersedes\": [], \"ledger_line\": \"l\"}\n    d.update(kw)\n    return d\n\n\ndef test_land_accumulates_and_keeps_unknown_sections(kroot):\n    from orchestrator import knowledge_harvest as H\n    H._land(kroot, \"repo-a\", 55,\n            _draft(\"src/a/cache/S.java\", invariants=[\"inv-A\"]),\n            \"cycle/silent\", \"\")\n    page = kroot / \"repo-a\" / \"cache\" / \"S.md\"\n    page.write_text(page.read_text() + \"\\n## Ops runbook\\n- \u624b\u5de5\u88dc\u7684\u4e00\u6bb5\\n\")\n    H._land(kroot, \"repo-a\", 56,\n            _draft(\"src/a/cache/S.java\", invariants=[\"inv-B\"]),\n            \"cycle/silent\", \"\")\n    body = page.read_text()\n    assert \"inv-A\" in body and \"inv-B\" in body\n    assert \"Ops runbook\" in body and \"\u624b\u5de5\u88dc\u7684\u4e00\u6bb5\" in body\n    assert \"| PR#55 |\" in body and \"| PR#56 |\" in body\n\n\ndef test_apply_rejects_boundary_and_ambiguity(kroot):\n    from orchestrator import knowledge_harvest as H\n    cyc = kroot / \"_cycle\" / \"repo-a\"\n    cyc.mkdir(parents=True)\n    for pid, ent in ((70, \"src/x/FeeCalc.java\"), (71, \"src/y/FeeCalc.java\")):\n        (cyc / f\"pr-{pid}.json\").write_text(\n            json.dumps({\"draft\": {\"primary_entity\": ent}}))\n    staged = sorted(cyc.glob(\"*.json\"))\n    msgs, amb = H._apply_rejects({\"eecalc.java\"}, staged, \"t\")\n    assert not msgs and not amb                       # \u6bb5\u908a\u754c\uff1a\u4e0d\u5438\u5b50\u5b57\u4e32\n    msgs, amb = H._apply_rejects({\"feecalc\"}, staged, \"t\")\n    assert amb and len(list(cyc.glob(\"*.json\"))) == 2  # \u6b67\u7fa9\uff1a\u5168\u4fdd\u7559\n    msgs, _ = H._apply_rejects({\"x/feecalc.java\"}, staged, \"t\")\n    assert any(\"\u4e1f\" in m for m in msgs)\n\n\ndef test_watermark_first_sight_no_backfill(kroot, monkeypatch):\n    from orchestrator import knowledge_harvest as H\n    (kroot / \"_state\").mkdir()\n    (kroot / \"_state\" / \"repos.json\").write_text(\n        json.dumps({\"repo-a\": \"https://x/C/P\"}))\n    monkeypatch.setattr(H, \"_list_completed\", lambda c, r: [{\n        \"pullRequestId\": 90, \"title\": \"ancient\",\n        \"sourceRefName\": \"refs/heads/f\", \"targetRefName\": \"refs/heads/master\",\n        \"closedDate\": \"2020-01-01T00:00:00Z\"}])\n    lines = H._watermark_scan(object(), kroot)\n    assert any(\"\u9996\u898b\" in x for x in lines)\n    assert not (kroot / \"repo-a\" / \"_module\" / \"unreviewed-ledger.md\").exists()\n    assert H._watermark_scan(object(), kroot) == []\n\n\ndef test_digest_state_merge_keeps_ambig(kroot, monkeypatch):\n    from orchestrator import knowledge_harvest as H\n    (kroot / \"_state\").mkdir()\n    (kroot / \"_state\" / \"repos.json\").write_text(\n        json.dumps({\"repo-a\": \"https://x/C/P\"}))\n    cyc = kroot / \"_cycle\" / \"repo-a\"\n    cyc.mkdir(parents=True)\n    (cyc / \"pr-70.json\").write_text(json.dumps({\n        \"pr_url\": \"u\", \"pr_id\": 70, \"repo\": \"repo-a\",\n        \"base_url\": \"https://x/C/P\",\n        \"draft\": _draft(\"src/x/F.java\"), \"author_note\": \"\",\n        \"provenance\": \"silent\"}))\n    posted = []\n    monkeypatch.setattr(H, \"client\",\n                        lambda: contextlib.nullcontext(object()))\n    monkeypatch.setattr(H, \"_post_thread\", lambda c, r, t: posted.append(t))\n    monkeypatch.setattr(H, \"_list_active\", lambda c, r: [{\n        \"pullRequestId\": 500, \"sourceRefName\": \"refs/heads/release/x\",\n        \"targetRefName\": \"refs/heads/master\"}])\n    monkeypatch.setattr(H, \"_list_completed\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: [])\n    state_f = kroot / \"_state\" / \"cycle.json\"\n    state_f.write_text(json.dumps({\"repo-a#500\": {\"ambig\": [\"feecalc\"]}}))\n    H._cycle_close(object(), kroot)\n    st = json.loads(state_f.read_text())[\"repo-a#500\"]\n    assert st.get(\"digest\") is True and st.get(\"ambig\") == [\"feecalc\"]\n\n\n# ---------- app\uff1a\u5feb\u53d6 commit \u8a9e\u610f\u3001meta \u76fe ----------\n\ndef test_cache_commit_invalidation():\n    from orchestrator import app as A\n    A._RECENT.clear()\n    A._cache_put(\"u1\", \"old-review\", \"sha-A\")\n    assert A._cache_get(\"u1\", \"sha-A\") == \"old-review\"\n    assert A._cache_get(\"u1\", \"sha-B\") is None         # push \u65b0 commit \u2192 \u5931\u6548\n    assert A._cache_get(\"u1\", \"\") == \"old-review\"      # \u7121 hint \u2192 TTL \u8a9e\u610f\n\n\ndef test_meta_shield_not_tripped_by_json_format():\n    from orchestrator import app as A\n    assert not A._is_meta_task({}, \"please give me the json format of X\")\n    assert A._is_meta_task({\"metadata\": {\"task\": \"title_generation\"}}, \"x\")\n\n\n# ---------- \u8003\u5377\u5e33\u76ee\uff1a\u6a94\u6578 \u2261 CASES \u2261 \u6587\u4ef6\u5ba3\u7a31\uff08\u9632\u4eba\u8166\u7b97\u8853\uff09 ----------\n\ndef test_fixture_count_matches_cases_and_readme():\n    from eval.seed_langfuse import CASES, DISTILL_CASES, KNOWLEDGE_CASES\n    fixtures = pathlib.Path(__file__).parent.parent / \"eval\" / \"fixtures\"\n    diffs = sorted(f.name for f in fixtures.glob(\"*.diff\"))\n    assert len(diffs) == len(CASES) == 30\n    case_files = {c[0] for c in CASES}\n    assert case_files == set(diffs)          # \u6bcf\u984c\u6709\u6a94\u3001\u6bcf\u6a94\u6709\u984c\n    readme = (pathlib.Path(__file__).parent.parent / \"README.md\").read_text(\n        encoding=\"utf-8\")\n    assert \"30 \u984c golden set\" in readme      # \u6587\u4ef6\u8ddf\u8003\u5377\u540c\u4e00\u500b\u6578\n\n    # \u77e5\u8b58\u4f9d\u8cf4\u984c\uff1a\u6bcf\u984c\u6709 diff\u3001\u6709\u7a2e\u5b50\u5e33\u672c\u76ee\u9304\uff08\u5c11\u4e00\u500b\u5c31\u9000\u5316\u6210\u7121\u77e5\u8b58\u5c0d\u7167\u7d44\uff09\n    kdiffs = sorted(f.name for f in (fixtures / \"knowledge_cases\").glob(\"*.diff\"))\n    assert len(kdiffs) == len(KNOWLEDGE_CASES) == 5\n    assert {c[0] for c in KNOWLEDGE_CASES} == set(kdiffs)\n    for _fname, repo, *_rest in KNOWLEDGE_CASES:\n        assert (fixtures / \"knowledge\" / repo).is_dir()\n    assert sum(1 for c in KNOWLEDGE_CASES if c[5][\"ktype\"] == \"single-page\") == 3\n    assert sum(1 for c in KNOWLEDGE_CASES if c[5][\"ktype\"] == \"distractor\") == 2\n    assert \"5 \u984c\u77e5\u8b58\u4f9d\u8cf4\u984c\" in readme\n\n    # \u84b8\u993e\u8003\u5377\uff1a10 \u984c\uff0c\u5176\u4e2d\u81f3\u5c11\u4e09\u984c\u662f\u9677\u9631\n    ddiffs = sorted(f.name for f in (fixtures / \"distill\").glob(\"*.diff\"))\n    assert len(ddiffs) == len(DISTILL_CASES) == 10\n    assert {c[0] for c in DISTILL_CASES} == set(ddiffs)\n    traps = [c for c in DISTILL_CASES if c[5][\"focus\"].startswith(\"TRAP\")]\n    assert len(traps) >= 3\n    assert \"10 \u984c\u84b8\u993e\u8003\u5377\" in readme\n\n\ndef test_cycle_isolation_between_parallel_release_branches(kroot, monkeypatch):\n    \"\"\"release/N \u6536\u53e3\u53ea\u843d\u5730\u81ea\u5df1\u90a3\u6279\uff1brelease/N+1 \u7684\u66ab\u5b58\u7a3f\u7559\u5728\u6c60\u88e1\u7b49\u81ea\u5df1\u7684\n    \u9a57\u6536 PR\uff1b\u7121 target_branch \u6a19\u8a18\u7684\u820a\u7a3f\u8996\u70ba\u842c\u7528\uff08\u5347\u7d1a\u4e0d\u64f1\u6dfa\uff09\u3002\"\"\"\n    from orchestrator import knowledge_harvest as H\n    (kroot / \"_state\").mkdir()\n    (kroot / \"_state\" / \"repos.json\").write_text(\n        json.dumps({\"repo-a\": \"https://x/C/P\"}))\n    (kroot / \"_state\" / \"cycle.json\").write_text(          # \u975e\u9996\u898b\uff08\u898b\u6c34\u4f4d\u6e2c\u8a66\uff09\n        json.dumps({\"repo-a#1\": {\"closed\": True}}))\n    cyc = kroot / \"_cycle\" / \"repo-a\"\n    cyc.mkdir(parents=True)\n    for pid, ent, tb in ((70, \"src/a/A.java\", \"release/2026.09\"),\n                         (71, \"src/b/B.java\", \"release/2026.10\"),\n                         (72, \"src/c/C.java\", \"\")):          # legacy \u7121\u6a19\u8a18\n        (cyc / f\"pr-{pid}.json\").write_text(json.dumps({\n            \"pr_url\": \"u\", \"pr_id\": pid, \"repo\": \"repo-a\",\n            \"base_url\": \"https://x/C/P\", \"target_branch\": tb,\n            \"draft\": _draft(ent), \"author_note\": \"\", \"provenance\": \"silent\"}))\n    monkeypatch.setattr(H, \"client\",\n                        lambda: contextlib.nullcontext(object()))\n    monkeypatch.setattr(H, \"_post_thread\", lambda c, r, t2: None)\n    monkeypatch.setattr(H, \"_list_active\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_list_completed\", lambda c, r: [{\n        \"pullRequestId\": 500,\n        \"sourceRefName\": \"refs/heads/release/2026.09\",\n        \"targetRefName\": \"refs/heads/master\", \"closedDate\": \"z\"}])\n    H._cycle_close(object(), kroot)\n    assert (kroot / \"repo-a\" / \"a\" / \"A.md\").exists()        # \u672c\u9031\u671f \u2192 \u843d\u5730\n    assert (kroot / \"repo-a\" / \"c\" / \"C.md\").exists()        # \u842c\u7528 \u2192 \u843d\u5730\n    assert not (kroot / \"repo-a\" / \"b\" / \"B.md\").exists()    # \u4e0b\u9031\u671f \u2192 \u7559\u6c60\n    assert [f.name for f in cyc.glob(\"*.json\")] == [\"pr-71.json\"]\n\n\n# ---------- \u4e32\u6d41\u8def\u5f91\u7aef\u5230\u7aef\uff08\u540c\u65cf NameError \u5169\u6b21\u5f97\u901e\u7684\u5171\u540c\u6839\u56e0\uff1d\u9019\u88e1\u6c92\u6e2c\uff09 ----------\n\ndef test_stream_review_delivers_markdown_and_caches_commit(monkeypatch):\n    from orchestrator import app as A\n    A._RECENT.clear()\n\n    async def f_meta(u):\n        return {\"repo\": \"r\", \"title\": \"t\", \"source_commit\": \"sha-X\",\n                \"target_branch\": \"refs/heads/feature/x\"}\n\n    async def f_diff(u):\n        return \"--- a/x.java\\n+++ b/x.java\\n@@ -1,1 +1,2 @@\\n a\\n+b\\n\"\n\n    async def f_run(diff, md):\n        return types.SimpleNamespace(markdown=\"## Pull Request Review OK\",\n                                     stats={\"file_table\": [],\n                                            \"graph_impacted\": []})\n\n    async def f_distill(*a, **k):\n        return None\n\n    monkeypatch.setattr(A.clients, \"fetch_pr_metadata\", f_meta)\n    monkeypatch.setattr(A.clients, \"fetch_pr_diff\", f_diff)\n    monkeypatch.setattr(A, \"run_review\", f_run)\n    monkeypatch.setattr(A.knowledge, \"distill_and_stage\", f_distill)\n    monkeypatch.setenv(\"AUTO_POST\", \"false\")\n\n    async def consume():\n        chunks = []\n        async for c in A._stream_review(\"rid\", \"https://x/C/P/_git/R/pullrequest/9\",\n                                        \"u\", commit_hint=\"sha-X\"):\n            chunks.append(c)\n        return \"\".join(chunks)\n\n    out = asyncio.run(consume())\n    assert \"Pull Request Review OK\" in out\n    assert \"\u274c\" not in out                    # \u5168\u7a0b\u7121\u932f\u8aa4\u6f14\u51fa\n    hit = A._RECENT[\"https://x/C/P/_git/R/pullrequest/9\"]\n    assert len(hit) == 3 and hit[2] == \"sha-X\"\n\n\n# ---------- F \u6279\uff1asynthesis / coverage gate / verdict / scorer / cache \u6e05\u7406 ----------\n\ndef _fnd(rule=\"BUG\", file=\"src/A.java\", line=12, sev=\"warning\",\n         src=\"llm\", conf=0.7, note=\"n\"):\n    from orchestrator.models import Finding\n    f = Finding(rule=rule, file=file, line=line, severity=sev, note=note)\n    f.source = src\n    f.confidence = conf\n    return f\n\n\ndef test_dedupe_corroborates_cross_source():\n    from orchestrator.pipeline import _dedupe\n    out = _dedupe([_fnd(src=\"static\", conf=1.0), _fnd(src=\"llm\", conf=0.7)])\n    assert len(out) == 1\n    assert out[0].confidence >= 1.0 - 1e-9        # \u4ea4\u53c9\u547d\u4e2d\u4e0d\u964d\u4fe1\u5fc3\n\n\ndef test_synthesize_threshold_and_cap(monkeypatch):\n    from orchestrator.pipeline import _synthesize\n    monkeypatch.setenv(\"REVIEW_MAX_FINDINGS\", \"2\")\n    stats = {}\n    out = _synthesize([_fnd(conf=0.9, file=\"a.java\", note=\"keep1\"),\n                       _fnd(conf=0.8, file=\"b.java\", note=\"keep2\"),\n                       _fnd(conf=0.7, file=\"c.java\", note=\"capped\"),\n                       _fnd(conf=0.2, file=\"d.java\", note=\"low\")], stats)\n    assert len(out) == 2 and stats[\"dropped_low_conf\"] == 1\n\n\ndef test_coverage_gate_sweeps_orphans():\n    from orchestrator.pipeline import _Dim, _coverage_gate\n    from orchestrator.rules import RulesBundle\n    diff = (\"--- a/x.java\\n+++ b/x.java\\n@@ -1,1 +1,2 @@\\n a\\n+b\\n\"\n            \"--- a/y.java\\n+++ b/y.java\\n@@ -1,1 +1,2 @@\\n a\\n+c\\n\")\n    ana = parse_diff(diff)\n    dims = [_Dim(name=\"Only-X\", focus=\"f\", hypotheses=[],\n                 files=[\"x.java\"], rules=[])]\n    out = _coverage_gate(dims, ana, RulesBundle(), {})\n    swept = [d for d in out if d is not dims[0]]\n    assert swept and any(\"y.java\" in f for d in swept for f in d.files)\n\n\ndef test_verdict_incomplete_when_all_reviewers_failed():\n    from orchestrator.render import _verdict\n    assert \"REVIEW INCOMPLETE\" in _verdict(\n        [], {\"reviewer_errors\": 4, \"static_findings\": 0})\n    assert \"APPROVED\" in _verdict([], {\"reviewer_errors\": 0,\n                                       \"static_findings\": 3})\n\n\ndef test_scorer_reports_per_source_recall():\n    from eval.run_eval import _score_v2\n    expected = [{\"rule\": \"SECURITY\"}, {\"rule\": \"MISSING-TEST\"}]\n    findings = [{\"rule\": \"SECURITY\", \"source\": \"llm\", \"file\": \"a\"},\n                {\"rule\": \"MISSING-TEST\", \"source\": \"static\", \"file\": \"\"}]\n    recall, _, _, comment, by_src = _score_v2(expected, findings, 2)\n    assert recall == 1.0 and by_src == {\"static\": 1, \"llm\": 1}\n    assert \"static 1 / llm 1\" in comment\n\n\ndef test_cache_cleanup_survives_three_tuples():\n    from orchestrator import app as A\n    A._RECENT.clear()\n    for i in range(205):                       # F2\uff1a>200 \u89f8\u767c\u6e05\u7406\u8def\u5f91\n        A._cache_put(f\"u{i}\", \"md\", f\"sha{i}\")\n    assert len(A._RECENT) >= 200               # \u672a\u904e\u671f\u4e0d\u6e05\u3001\u4f46\u7d55\u4e0d ValueError\n\n\ndef test_anatomy_ignores_git_header_lines():\n    diff = (\"diff --git a/x.java b/x.java\\n\"\n            \"index 111..222 100644\\n\"\n            \"--- a/x.java\\n+++ b/x.java\\n@@ -1,2 +1,3 @@\\n\"\n            \" a\\n+b\\n c\\n\"\n            \"diff --git a/y.java b/y.java\\n\"\n            \"new file mode 100644\\n\"\n            \"--- /dev/null\\n+++ b/y.java\\n@@ -0,0 +1,1 @@\\n+z\\n\")\n    ana = parse_diff(diff)\n    xs = [fc for fc in ana.files if fc.path.endswith(\"x.java\")][0]\n    nums = [n for h in xs.hunks for _, n, _ in h.lines if n is not None]\n    assert max(nums) == 3                      # \u4e0d\u518d\u51fa\u73fe\u5e7d\u9748\u7b2c 4/5 \u884c\n\n\ndef test_harvester_never_posts_shadow_or_legacy_drafts(kroot, monkeypatch):\n    \"\"\"\u5f71\u5b50\u6a21\u5f0f\uff08dry_run\uff09\u8207\u7121\u6a19\u8a18\u5b58\u91cf\u7a3f\uff1aactive PR + posted:false\uff0c\n    harvester \u5fc5\u9808\u966a\u7b49\u3001\u7d55\u4e0d\u4ee3\u8cbc\uff1bpost_failed \u7684\u771f\u5931\u6557\u7a3f\u624d\u88dc\u8cbc\u3001\u4e14\u53ea\u4e00\u6b21\u3002\"\"\"\n    from orchestrator import knowledge_harvest as H\n    posted = []\n    monkeypatch.setattr(H, \"_get_pr\", lambda c, r: {\"status\": \"active\"})\n    monkeypatch.setattr(H, \"_post_thread\",\n                        lambda c, r, t2: posted.append(t2) or 77)\n    pend_dir = kroot / \"_pending\" / \"repo-a\"\n    pend_dir.mkdir(parents=True)\n\n    def mk(pid, **extra):\n        f = pend_dir / f\"pr-{pid}.json\"\n        f.write_text(json.dumps({\n            \"pr_url\": \"u\", \"pr_id\": pid, \"repo\": \"repo-a\",\n            \"base_url\": \"https://x/C/P\", \"distilled_commit\": \"sha\",\n            \"author\": \"a\", \"thread_id\": None, \"posted\": False,\n            \"draft\": _draft(\"src/x/F.java\"), \"created\": \"t\", **extra}))\n        return f\n\n    shadow = mk(70, dry_run=True, post_failed=False)\n    legacy = mk(71)                                   # F7 \u4fee\u6b63\u524d\u7684\u820a\u7a3f\uff1a\u7121\u6a19\u8a18\n    failed = mk(72, dry_run=False, post_failed=True)\n    for f in (shadow, legacy):\n        out = H._process_pending(object(), kroot, f)\n        assert \"\u966a\u7b49\" in out and not posted\n        assert json.loads(f.read_text())[\"posted\"] is False\n    out = H._process_pending(object(), kroot, failed)\n    assert \"\u88dc\u6551\u6210\u529f\" in out and len(posted) == 1\n    info = json.loads(failed.read_text())\n    assert info[\"posted\"] is True and info[\"thread_id\"] == 77\n    assert \"\u966a\u7b49\" in H._process_pending(object(), kroot, failed)  # \u4e0d\u91cd\u8cbc\n\n\n# ---------- digest / \u689d\u76ee ID\uff1a\u84b8\u993e\u6642\u5b9a\u3001\u66ab\u5b58\u2192\u843d\u5730\u4e0d\u8b8a\u3001reject \u4e09\u7c92\u5ea6 ----------\n\ndef test_assign_ids_idempotent_and_legacy_shapes():\n    from orchestrator.knowledge import assign_ids, entry_ids, norm_id, split_id\n    d = {\"decisions\": [{\"text\": \"a\"}, {\"id\": \"PR9-D7\", \"text\": \"b\"}],\n         \"invariants\": [\"x\", {\"id\": \"PR9-I3\", \"text\": \"y\"}, \"\", {\"text\": \"z\"}]}\n    assign_ids(d, 12)\n    assert [q[\"id\"] for q in d[\"decisions\"]] == [\"PR12-D1\", \"PR9-D7\"]\n    assert d[\"invariants\"] == [{\"id\": \"PR12-I1\", \"text\": \"x\"},\n                               {\"id\": \"PR9-I3\", \"text\": \"y\"},\n                               {\"id\": \"PR12-I4\", \"text\": \"z\"}]\n    snap = json.dumps(d)\n    assign_ids(d, 99)                              # \u51aa\u7b49\uff1a\u5df2\u6709 id \u4e00\u5f8b\u4e0d\u52d5\n    assert json.dumps(d) == snap\n    assert entry_ids(d, 12) == {\"PR12\", \"PR12-D1\", \"PR9-D7\",\n                                \"PR12-I1\", \"PR9-I3\", \"PR12-I4\"}\n    assert norm_id(\"pr12-i1\") == \"PR12-I1\" and norm_id(\"PR12\") == \"\"\n    assert split_id(\"rule text `PR12-I1`\") == (\"rule text\", \"PR12-I1\")\n    assert split_id(\"legacy line\") == (\"legacy line\", \"\")\n\n\ndef test_land_ids_retire_by_id_and_dedupe_by_text(kroot):\n    from orchestrator import knowledge_harvest as H\n    from orchestrator.knowledge import existing_invariants\n    H._land(kroot, \"repo-a\", 55,\n            _draft(\"src/a/cache/S.java\", invariants=[\"inv-A\", \"inv-B\"],\n                   decisions=[{\"text\": \"dec\", \"evidence\": [\"PR\"]}]),\n            \"cycle/silent\", \"\")\n    page = kroot / \"repo-a\" / \"cache\" / \"S.md\"\n    body = page.read_text()\n    assert \"- inv-A `PR55-I1`\" in body and \"- dec [PR] `PR55-D1`\" in body\n    cat = existing_invariants(\"repo-a\", [\"src/a/cache/S.java\"])\n    assert cat == [(\"repo-a/cache/S.md\", [(\"PR55-I1\", \"inv-A\"),\n                                          (\"PR55-I2\", \"inv-B\")])]\n    # PR#56\uff1a\u7528 ID \u8a3b\u92b7 inv-A\u3001\u91cd\u8ff0 inv-B\uff08\u6587\u5b57\u76f8\u540c \u2192 \u4e0d\u91cd\u8907\u843d\uff09\u3001\u65b0\u589e inv-C\n    H._land(kroot, \"repo-a\", 56,\n            _draft(\"src/a/cache/S.java\", invariants=[\"inv-B\", \"inv-C\"],\n                   supersedes=[{\"entity\": \"S\", \"what\": \"A gone\",\n                                \"retires_id\": \"pr55-i1\"}]),\n            \"cycle/explicit\", \"\", rejected_ids=[\"PR56-D9\"])\n    body = page.read_text()\n    assert \"- ~~inv-A~~ \u26a0 retired by PR#56 `PR55-I1`\" in body\n    assert body.count(\"inv-B\") == 1 and \"inv-C `PR56-I2`\" in body\n    assert \"rejected: `PR56-D9`\" in body\n    # \u5df2\u8a3b\u92b7\u7684\u4e0d\u518d\u5217\u5165 catalogue\uff1bID \u8ddf\u8457\u884c\u8d70\n    cat = existing_invariants(\"repo-a\", [\"src/a/cache/S.java\"])\n    assert cat[0][1] == [(\"PR55-I2\", \"inv-B\"), (\"PR56-I2\", \"inv-C\")]\n    # \u820a\u683c\u5f0f\uff08\u7121 ID\uff09\u884c\u4ecd\u53ef\u7528\u9010\u5b57\u76f8\u7b49\u8a3b\u92b7\n    page.write_text(body.replace(\"- inv-C `PR56-I2`\", \"- legacy-rule\"))\n    H._land(kroot, \"repo-a\", 57, _draft(\n        \"src/a/cache/S.java\",\n        supersedes=[{\"entity\": \"S\", \"what\": \"x\", \"retires_verbatim\": \"legacy-rule\"}]),\n        \"cycle/silent\", \"\")\n    assert \"~~legacy-rule~~ \u26a0 retired by PR#57\" in page.read_text()\n\n\ndef test_land_stem_collision_skip_returns_pair(kroot):\n    \"\"\"\u540c parent+stem\u3001\u4e0d\u540c\u5be6\u9ad4 \u2192 \u5206\u9801\uff1b\u91cd\u8907\u843d\u5730\u8d70 skip \u8def\u5f91\u5fc5\u9808\u56de 2-tuple\n    \uff08\u539f\u672c\u56de\u4e09\u500b\u503c\uff0c\u547c\u53eb\u7aef unpack \u6703\u70b8\u3001\u6574\u500b\u9031\u671f\u5361\u6b7b\uff09\u3002\"\"\"\n    from orchestrator import knowledge_harvest as H\n    H._land(kroot, \"repo-a\", 60, _draft(\"src/a/cache/S.java\"), \"cycle/silent\", \"\")\n    msg, page = H._land(kroot, \"repo-a\", 61, _draft(\"src/b/cache/S.java\"),\n                        \"cycle/silent\", \"\")\n    assert page.name.startswith(\"S-\") and page.exists()\n    msg2, page2 = H._land(kroot, \"repo-a\", 61, _draft(\"src/b/cache/S.java\"),\n                          \"cycle/silent\", \"\")\n    assert msg2.startswith(\"skip\") and page2 == page\n\n\ndef _stage(kroot, pid, ent, **kw):\n    cyc = kroot / \"_cycle\" / \"repo-a\"\n    cyc.mkdir(parents=True, exist_ok=True)\n    (cyc / f\"pr-{pid}.json\").write_text(json.dumps({\n        \"pr_url\": \"u\", \"pr_id\": pid, \"repo\": \"repo-a\",\n        \"base_url\": \"https://x/C/P\", \"target_branch\": \"release/x\",\n        \"draft\": _draft(ent, invariants=[f\"rule-{pid}\"], **kw),\n        \"author_note\": \"\", \"provenance\": \"silent\"}))\n\n\ndef test_digest_first_delta_then_unlisted_on_close(kroot, monkeypatch):\n    from orchestrator import knowledge_harvest as H\n    (kroot / \"_state\").mkdir()\n    (kroot / \"_state\" / \"repos.json\").write_text(\n        json.dumps({\"repo-a\": \"https://x/C/P\"}))\n    posted, active, completed = [], [], []\n    monkeypatch.setattr(H, \"client\", lambda: contextlib.nullcontext(object()))\n    monkeypatch.setattr(H, \"_post_thread\", lambda c, r, t: posted.append(t))\n    monkeypatch.setattr(H, \"_list_active\", lambda c, r: active)\n    monkeypatch.setattr(H, \"_list_completed\", lambda c, r: completed)\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: [])\n    acc = {\"pullRequestId\": 500, \"sourceRefName\": \"refs/heads/release/x\",\n           \"targetRefName\": \"refs/heads/master\", \"closedDate\": \"z\"}\n    state_f = kroot / \"_state\" / \"cycle.json\"\n\n    _stage(kroot, 70, \"src/x/A.java\")\n    active.append(acc)\n    H._cycle_close(object(), kroot)                       # \u9996\u6b21 digest\n    assert len(posted) == 1 and \"pending acceptance\" in posted[0]\n    assert \"PR#70\" in posted[0] and \"`PR70-I1`\" in posted[0]\n    assert json.loads(state_f.read_text())[\"repo-a#500\"][\"listed\"] == [\"PR70\"]\n\n    H._cycle_close(object(), kroot)                       # \u6c92\u65b0\u7a3f\uff1a\u4e0d\u91cd\u8cbc\n    assert len(posted) == 1\n\n    _stage(kroot, 71, \"src/y/B.java\")\n    H._cycle_close(object(), kroot)                       # delta\uff1a\u53ea\u5217\u65b0\u9032\n    assert len(posted) == 2 and \"update: 1 new entry\" in posted[1]\n    assert \"PR#71\" in posted[1] and \"`PR70-I1`\" not in posted[1]\n    assert json.loads(state_f.read_text())[\"repo-a#500\"][\"listed\"] == [\"PR70\", \"PR71\"]\n\n    _stage(kroot, 72, \"src/z/C.java\")                     # \u9a57\u6536 PR \u5df2\u5b8c\u6210\u624d\u9032\u6c60\n    active.clear()\n    completed.append(acc)\n    lines = H._cycle_close(object(), kroot)\n    assert len(posted) == 2                               # completed \u4e0d\u518d\u8cbc digest\n    for stem in (\"x/A\", \"y/B\", \"z/C\"):\n        assert (kroot / \"repo-a\" / f\"{stem}.md\").exists()\n    receipt = next((kroot / \"repo-a\" / \"_cycles\").glob(\"*-PR500.md\")).read_text()\n    assert \"| PR#72 | C | cycle/silent+unlisted |\" in receipt\n    assert \"| PR#70 | A | cycle/silent |\" in receipt\n    assert \"cycle/silent+unlisted\" in (kroot / \"repo-a\" / \"z\" / \"C.md\").read_text()\n    assert any(\"1 \u689d\u5f9e\u672a\u51fa\u73fe\u5728 digest\" in ln for ln in lines)\n    assert json.loads(state_f.read_text())[\"repo-a#500\"][\"closed\"] is True\n\n\ndef test_reject_by_id_line_and_entry(kroot):\n    from orchestrator import knowledge_harvest as H\n    _stage(kroot, 70, \"src/x/A.java\",\n           decisions=[{\"text\": \"d1\"}, {\"text\": \"d2\"}])\n    _stage(kroot, 71, \"src/y/B.java\")\n    cyc = kroot / \"_cycle\" / \"repo-a\"\n    staged = sorted(cyc.glob(\"*.json\"))\n    msgs, amb = H._apply_rejects({\"pr70-d2\", \"pr70-i1\", \"pr99-i1\"}, staged, \"t\")\n    assert not amb\n    info = json.loads((cyc / \"pr-70.json\").read_text())\n    assert [d[\"id\"] for d in info[\"draft\"][\"decisions\"]] == [\"PR70-D1\"]\n    assert info[\"draft\"][\"invariants\"] == []            # \u884c\u62ff\u6389\u3001\u689d\u76ee\u9084\u5728\n    assert info[\"rejected_ids\"] == [\"PR70-D2\", \"PR70-I1\"]\n    assert any(\"PR99-I1\" in m and \"\u67e5\u7121\" in m for m in msgs)\n    msgs, _ = H._apply_rejects({\"pr71\"}, sorted(cyc.glob(\"*.json\")), \"t\")\n    assert any(\"\u6574\u689d\u4e1f\" in m for m in msgs)\n    assert [f.name for f in cyc.glob(\"*.json\")] == [\"pr-70.json\"]\n\n\ndef test_digest_validate_and_render_offline():\n    from orchestrator import knowledge_digest as D\n    items = [{\"pr_id\": 70, \"provenance\": \"silent\", \"author_note\": \"keep it\",\n              \"draft\": _draft(\"src/x/A.java\",\n                              invariants=[{\"id\": \"PR70-I1\", \"text\": \"r70\"}],\n                              decisions=[{\"id\": \"PR70-D1\", \"text\": \"d70\",\n                                          \"evidence\": [\"PR\"]}])},\n             {\"pr_id\": 71, \"provenance\": \"explicit\", \"author_note\": \"\",\n              \"draft\": _draft(\"src/y/B.java\",\n                              invariants=[{\"id\": \"PR71-I1\", \"text\": \"r71\"}],\n                              supersedes=[{\"entity\": \"A\", \"what\": \"w\",\n                                           \"retires_id\": \"PR1-I1\"}])}]\n    known = D.known_ids(items, [(\"repo-a/x/A.md\", [(\"PR1-I1\", \"old\")])])\n    assert {\"PR70\", \"PR70-I1\", \"PR70-D1\", \"PR71\", \"PR71-I1\", \"PR1-I1\"} <= known\n    raw = {\"headline\": \"  cycle  summary \",\n           \"flags\": [{\"kind\": \"Conflict\", \"ids\": [\"pr70-i1\", \"PR71-I1\", \"PR5-I9\"],\n                      \"note\": \"a\\nb\", \"suggest\": \"reject PR70-I1\"},\n                     {\"kind\": \"duplicate\", \"ids\": [\"PR404-I1\"], \"note\": \"n\"},\n                     {\"kind\": \"praise\", \"ids\": [\"PR70-I1\"], \"note\": \"n\"},\n                     {\"kind\": \"unclear\", \"ids\": [\"PR71-I1\"], \"note\": \"n\",\n                      \"suggest\": \"reject PR9-I9 now\"},\n                     \"junk\"]}\n    out = D.validate(raw, known)\n    assert out[\"headline\"] == \"cycle summary\"\n    assert [f[\"kind\"] for f in out[\"flags\"]] == [\"conflict\", \"unclear\"]\n    assert out[\"flags\"][0][\"ids\"] == [\"PR70-I1\", \"PR71-I1\"]     # \u672a\u77e5 ID \u88ab\u6ffe\n    assert out[\"flags\"][0][\"note\"] == \"a b\"\n    assert out[\"flags\"][1][\"suggest\"] == \"\"                      # \u975e\u6cd5\u5efa\u8b70\u53ea\u7559 note\n    assert D.validate(raw, known, max_flags=1)[\"flags\"][0][\"kind\"] == \"conflict\"\n    assert D.validate(\"nope\", known) is None\n\n    md = D.render(items, None, out)\n    assert md.startswith(D.KMARK) and \"pending acceptance** (2 entries)\" in md\n    assert \"Needs a look\" in md and \"`PR70-I1` \u2194 `PR71-I1`\" in md\n    assert \"\u2192 `reject PR70-I1`\" in md and \"_cycle summary_\" in md\n    assert \"Rules being retired\" in md and \"retires `PR1-I1`\" in md\n    assert \"- d70 [PR] `PR70-D1`\" in md and \"\ud83d\udcac author: keep it\" in md\n    assert \"`reject PR12-I1`\" in md                              # \u6307\u4ee4\u8aaa\u660e\n    md_delta = D.render(items, {\"PR71\"}, out, total=2)\n    assert \"update: 1 new entry\" in md_delta and \"PR#70 \u00b7\" not in md_delta\n    assert \"`PR70-I1` \u2194 `PR71-I1`\" in md_delta                   # \u727d\u6d89\u65b0\u9032 PR \u2192 \u7559\n    assert \"**unclear**\" in md_delta and \"_cycle summary_\" not in md_delta\n    md_plain = D.render(items, None, None)\n    assert \"Needs a look\" not in md_plain and \"PR#70\" in md_plain\n    assert D.parse_reject_token(\"pr70-i1\") == (\"line\", \"PR70-I1\")\n    assert D.parse_reject_token(\"PR70\") == (\"entry\", \"PR70\")\n    assert D.parse_reject_token(\"x/A.java\") == (\"name\", \"x/A.java\")\n\n\ndef test_analyze_degrades_to_none_and_respects_switch(monkeypatch):\n    from orchestrator import knowledge_digest as D\n    items = [{\"pr_id\": 1, \"draft\": _draft(\"a/B.java\", invariants=[\"r\"])}]\n    monkeypatch.setenv(\"KNOWLEDGE_DIGEST_LLM\", \"false\")\n    assert D.analyze(\"repo-a\", items) is None\n    monkeypatch.setenv(\"KNOWLEDGE_DIGEST_LLM\", \"true\")\n    monkeypatch.setattr(D, \"complete_sync\",\n                        lambda *a, **k: (_ for _ in ()).throw(RuntimeError(\"down\")))\n    log = []\n    assert D.analyze(\"repo-a\", items, log=log.append) is None\n    assert log and \"\u5206\u6790\u5931\u6557\" in log[0]\n    monkeypatch.setattr(D, \"complete_sync\", lambda *a, **k:\n                        '{\"headline\":\"h\",\"flags\":[{\"kind\":\"unclear\",\"ids\":[\"PR1-I1\"],\"note\":\"n\"}]}')\n    out = D.analyze(\"repo-a\", items)\n    assert out[\"flags\"][0][\"ids\"] == [\"PR1-I1\"]\n\n\ndef test_write_json_atomic_leaves_no_tmp(tmp_path=None):\n    from orchestrator.knowledge import write_json_atomic\n    d = pathlib.Path(tempfile.mkdtemp()) / \"nested\"\n    write_json_atomic(d / \"pr-1.json\", {\"a\": 1})\n    write_json_atomic(d / \"pr-1.json\", {\"a\": 2})\n    assert json.loads((d / \"pr-1.json\").read_text()) == {\"a\": 2}\n    assert [p.name for p in d.iterdir()] == [\"pr-1.json\"]\n\n\ndef test_mark_superseded_locates_page_by_id(kroot):\n    \"\"\"retires_id \u547d\u4e2d\u6642\u4e0d\u8d70 stem \u731c\u9801\uff1aentity \u4e82\u586b\u4e5f\u84cb\u5c0d\u9801\u3002\"\"\"\n    from orchestrator import knowledge_harvest as H\n    H._land(kroot, \"repo-a\", 40, _draft(\"src/a/lock/LockService.java\",\n                                        invariants=[\"both keys\"]), \"cycle/silent\", \"\")\n    msg = H._mark_superseded(kroot, \"repo-a\",\n                             {\"entity\": \"com.acme.Whatever\", \"what\": \"w\",\n                              \"retires_id\": \"PR40-I1\"}, 41)\n    assert \"PR40-I1 \u5b9a\u4f4d\" in msg\n    body = (kroot / \"repo-a\" / \"lock\" / \"LockService.md\").read_text()\n    assert \"Superseded (PR#41\" in body\n\n\ndef test_cycle_close_waits_for_pending_of_same_branch(kroot, monkeypatch):\n    \"\"\"\u9a57\u6536 PR \u5b8c\u6210\u3001\u6c60\u5b50\u7a7a\u3001\u4f46\u9084\u6709\u5c0f PR \u672a\u7d42\u614b\u4e14\u6307\u5411\u672c\u9031\u671f\u5206\u652f \u2192 \u4e0d\u6a19 closed\uff0c\n    \u7b49\u5b83\u9032\u6c60\u5f8c\u7167\u5e38\u843d\u5730\uff08\u539f\u672c\u6703\u6c38\u4e45\u5b64\u5152\uff09\u3002\"\"\"\n    from orchestrator import knowledge_harvest as H\n    (kroot / \"_state\").mkdir()\n    (kroot / \"_state\" / \"repos.json\").write_text(\n        json.dumps({\"repo-a\": \"https://x/C/P\"}))\n    (kroot / \"_state\" / \"cycle.json\").write_text(          # \u975e\u9996\u898b\uff08\u898b\u6c34\u4f4d\u6e2c\u8a66\uff09\n        json.dumps({\"repo-a#1\": {\"closed\": True}}))\n    pend = kroot / \"_pending\" / \"repo-a\"\n    pend.mkdir(parents=True)\n    (pend / \"pr-80.json\").write_text(json.dumps({\n        \"pr_id\": 80, \"repo\": \"repo-a\", \"target_branch\": \"release/x\",\n        \"draft\": _draft(\"src/q/Q.java\")}))\n    monkeypatch.setattr(H, \"client\", lambda: contextlib.nullcontext(object()))\n    monkeypatch.setattr(H, \"_post_thread\", lambda c, r, t: None)\n    monkeypatch.setattr(H, \"_list_active\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_list_completed\", lambda c, r: [{\n        \"pullRequestId\": 500, \"sourceRefName\": \"refs/heads/release/x\",\n        \"targetRefName\": \"refs/heads/master\", \"closedDate\": \"z\"}])\n    lines = H._cycle_close(object(), kroot)\n    st = json.loads((kroot / \"_state\" / \"cycle.json\").read_text())\n    assert not st.get(\"repo-a#500\", {}).get(\"closed\")\n    assert any(\"\u66ab\u4e0d\u6536\u53e3\" in ln for ln in lines)\n    (pend / \"pr-80.json\").unlink()                     # \u5c0f PR \u7d42\u614b \u2192 \u9032\u6c60\n    _stage(kroot, 80, \"src/q/Q.java\")\n    H._cycle_close(object(), kroot)\n    assert (kroot / \"repo-a\" / \"q\" / \"Q.md\").exists()\n    assert json.loads((kroot / \"_state\" / \"cycle.json\").read_text())[\"repo-a#500\"][\"closed\"]\n\n\n# ========== Phase 1\uff1a\u84b8\u993e\u8b49\u64da\u5730\u677f\uff08\u5207\u7247 / evidence \u9a57\u8b49 / primary \u9328\u9ede\uff09 ==========\n\n_EV_DIFF = (\"--- a/src/main/java/com/acme/cache/SessionCache.java\\n\"\n            \"+++ b/src/main/java/com/acme/cache/SessionCache.java\\n\"\n            \"@@ -10,4 +10,6 @@\\n\"\n            \" ctx10\\n ctx11\\n+added12\\n+added13\\n ctx14\\n ctx15\\n\")\n\n\ndef test_verify_evidence_matrix():\n    \"\"\"\u56db\u7a2e evidence \u5f62\u5f0f \u00d7 \u904e/\u4e0d\u904e\uff1b\u525d\u5149\u7684 decision \u6574\u689d\u4e0d\u5165\u7a3f\u3002\"\"\"\n    from orchestrator.anatomy import Anatomy\n    from orchestrator.knowledge import verify_evidence\n    ana = parse_diff(_EV_DIFF)\n    long_desc = \"x\" * 60\n    data = {\"decisions\": [\n        {\"text\": \"keeps a real line\", \"evidence\": [\"SessionCache.java:12\"]},\n        {\"text\": \"keeps a finding id\", \"evidence\": [\"F2\"]},\n        {\"text\": \"keeps a PR-backed rationale\", \"evidence\": [\"PR\"]},\n        {\"text\": \"mixed: one good one bogus\",\n         \"evidence\": [\"Nope.java:12\", \"SessionCache.java:14\"]},\n        {\"text\": \"line outside the excerpt\", \"evidence\": [\"SessionCache.java:99\"]},\n        {\"text\": \"file not in this diff\", \"evidence\": [\"Other.java:12\"]},\n        {\"text\": \"finding id we never issued\", \"evidence\": [\"F9\"]},\n        {\"text\": \"no evidence at all\", \"evidence\": []},\n        {\"text\": \"free-form prose\", \"evidence\": [\"see the diff\"]},\n    ]}\n    out, dropped = verify_evidence(data, ana, {\"F1\", \"F2\"}, long_desc)\n    kept = [d[\"text\"] for d in out[\"decisions\"]]\n    assert kept == [\"keeps a real line\", \"keeps a finding id\",\n                    \"keeps a PR-backed rationale\", \"mixed: one good one bogus\"]\n    assert out[\"decisions\"][3][\"evidence\"] == [\"SessionCache.java:14\"]  # \u58de\u7684\u88ab\u525d\n    assert len(dropped) == 5 and \"no evidence at all\" in dropped\n\n    # \"PR\" \u9700\u8981\u6709\u5167\u5bb9\u7684 description\uff08\u53bb\u7a7a\u767d\u5f8c >= 40 \u5b57\uff09\n    thin, _ = verify_evidence({\"decisions\": [{\"text\": \"t\", \"evidence\": [\"PR\"]}]},\n                              ana, set(), \"too short\")\n    assert thin[\"decisions\"] == []\n    # \u6c92\u6709 diff \u53ef\u6bd4\u5c0d\u6642 file:line \u4e00\u5f8b\u4e0d\u904e\uff08\u5be7\u53ef\u5c11\u6536\uff0c\u4e0d\u53ef\u5047\u8b49\u64da\uff09\n    blind, _ = verify_evidence(\n        {\"decisions\": [{\"text\": \"t\", \"evidence\": [\"SessionCache.java:12\"]}]},\n        Anatomy(), set(), long_desc)\n    assert blind[\"decisions\"] == []\n\n\ndef test_distill_slices_priority_and_budget(monkeypatch):\n    \"\"\"\u512a\u5148\u5e8f\uff1a\u65b0\u589e\u6700\u591a \u2192 finding \u5f15\u5230\u7684 \u2192 \u6709\u65b0\u5ba3\u544a\u7684 \u2192 \u5176\u9918\uff1b\u8d85\u9810\u7b97\u7559\u8a3b\u8a18\u3002\"\"\"\n    from orchestrator.knowledge import _distill_order, distill_slices\n\n    def f(path, adds, decl=False):\n        body = \"\\n\".join((f\"+    public void m{i}() {{\" if decl else f\"+ line{i}\")\n                         for i in range(adds))\n        return f\"--- /dev/null\\n+++ b/{path}\\n@@ -0,0 +1,{adds} @@\\n{body}\\n\"\n\n    ana = parse_diff(f(\"src/Big.java\", 12) + f(\"src/Cited.java\", 3)\n                     + f(\"src/Decl.java\", 3, decl=True) + f(\"src/Plain.java\", 3))\n    order = [fc.path for fc in _distill_order(ana, [\"src/Cited.java\"])]\n    assert order == [\"/src/Big.java\", \"/src/Cited.java\", \"/src/Decl.java\",\n                     \"/src/Plain.java\"]\n    monkeypatch.setenv(\"DISTILL_DIFF_MAX_CHARS\", \"400\")\n    text, skipped = distill_slices(ana, [\"src/Cited.java\"])\n    assert skipped and \"omitted from the diff excerpt\" in text\n    assert \"/src/Big.java\" not in skipped          # \u6700\u9ad8\u512a\u5148\u5e8f\u4e0d\u6703\u88ab\u7701\u6389\n\n\ndef test_primary_entity_prefers_added_lines_over_path_length():\n    \"\"\"\u820a fallback \u53d6\u300e\u8def\u5f91\u6700\u9577\u300f\u2014\u2014\u90a3\u901a\u5e38\u662f\u6e2c\u8a66\u6a94\u3002\u6539\u53d6\u65b0\u589e\u884c\u6578\u6700\u591a\u7684\u539f\u59cb\u78bc\u6a94\u3002\"\"\"\n    from orchestrator.knowledge import fix_primary_entity, pick_primary_entity\n    diff = (\"--- /dev/null\\n+++ b/src/main/java/com/acme/lock/LockService.java\\n\"\n            \"@@ -0,0 +1,3 @@\\n+a\\n+b\\n+c\\n\"\n            \"--- /dev/null\\n\"\n            \"+++ b/src/test/java/com/acme/lock/integration/LockServiceIT.java\\n\"\n            \"@@ -0,0 +1,8 @@\\n\" + \"\\n\".join(f\"+t{i}\" for i in range(8)) + \"\\n\"\n            \"--- /dev/null\\n+++ b/pom.xml\\n@@ -0,0 +1,9 @@\\n\"\n            + \"\\n\".join(f\"+<dep{i}/>\" for i in range(9)) + \"\\n\")\n    ana = parse_diff(diff)\n    assert pick_primary_entity(ana, []).endswith(\"LockService.java\")\n    d = {\"primary_entity\": \"src/main/java/com/acme/lock/LockService.java\"}\n    assert fix_primary_entity(d, ana, []) is False        # \u5728\u8b8a\u66f4\u6a94\u5167 \u2192 \u4e0d\u52d5\n    d = {\"primary_entity\": \"com.acme.SomewhereElse\"}\n    assert fix_primary_entity(d, ana, []) is True         # \u4e0d\u5728 \u2192 fallback\n    assert d[\"primary_entity\"].endswith(\"LockService.java\")\n\n\n# ========== Phase 2\uff1a\u5f15\u7528\u7387\uff08\u6ce8\u5165 id \u540d\u55ae \u2192 knowledge_ref \u2192 \u78ba\u5b9a\u6027\u57f7\u6cd5\uff09 ==========\n\ndef _seed_page(kroot, repo, rel, entity, invariants, affected=(), pad=0):\n    p = kroot / repo / rel\n    p.parent.mkdir(parents=True, exist_ok=True)\n    body = [f\"# {p.stem}\", \"\", f\"> entity: {entity}\",\n            \"> approval: seed \u00b7 last: PR#9 \u00b7 2026-08-01\", \"\",\n            \"## Summary\", \"s\" * pad if pad else \"seed page\", \"\", \"## Invariants\"]\n    body += [f\"- {t} `{i}`\" for i, t in invariants]\n    if affected:\n        body += [\"\", \"## Affected entities\", \", \".join(f\"`{a}`\" for a in affected)]\n    p.write_text(\"\\n\".join(body) + \"\\n\", encoding=\"utf-8\")\n    return p\n\n\ndef test_load_for_reports_only_injected_ids(kroot):\n    from orchestrator.knowledge import load_for\n    _seed_page(kroot, \"repo-a\", \"cache/SessionCache.md\",\n               \"src/main/java/com/acme/cache/SessionCache.java\",\n               [(\"PR41-I1\", \"ttl is millis\")])\n    text, stats = load_for(\"repo-a\",\n                           [\"src/main/java/com/acme/cache/SessionCache.java\"])\n    assert stats[\"knowledge_ids\"] == [\"PR41-I1\"]      # \u5c3e\u8a3b\u7684\u8aaa\u660e\u6587\u5b57\u4e0d\u7b97\u6578\n    assert stats[\"knowledge_full\"] == 1 and stats[\"knowledge_omitted\"] == 0\n    assert \"knowledge_ref\" in text                    # \u5f15\u7528\u5408\u7d04\u6709\u8b1b\u7d66\u6a21\u578b\u807d\n    assert load_for(\"repo-a\",\n                    [\"src/other/Unrelated.java\"])[1][\"knowledge_entries\"] == 0\n\n\ndef test_synthesize_verifies_knowledge_refs():\n    from orchestrator.pipeline import _synthesize\n    good = _fnd(file=\"a.java\", note=\"grounded\")\n    good.knowledge_ref = [\"pr41-i1\", \"PR99-I9\"]       # \u5f8c\u8005\u6c92\u88ab\u6ce8\u5165\u904e \u2192 \u525d\u6389\n    bare = _fnd(file=\"b.java\", note=\"ungrounded\")\n    stats = {\"knowledge_ids\": [\"PR41-I1\"]}\n    out = _synthesize([good, bare], stats)\n    assert good.knowledge_ref == [\"PR41-I1\"]\n    assert stats[\"knowledge_grounded\"] == 1 and stats[\"knowledge_refs_stripped\"] == 1\n    assert stats[\"knowledge_ids_injected\"] == 1\n    assert len(out) == 2\n\n\ndef test_dedupe_keeps_knowledge_ref_of_the_dropped_twin():\n    from orchestrator.pipeline import _dedupe\n    keep = _fnd(conf=0.9, note=\"kept\")\n    twin = _fnd(conf=0.7, note=\"dup with a citation\")\n    twin.knowledge_ref = [\"PR41-I1\"]\n    out = _dedupe([keep, twin])\n    assert len(out) == 1 and out[0].knowledge_ref == [\"PR41-I1\"]\n\n\ndef test_render_shows_knowledge_citation():\n    from orchestrator.render import render_markdown\n    f = _fnd(note=\"ttl unit is wrong\", sev=\"error\")\n    f.knowledge_ref = [\"PR41-I1\"]\n    md = render_markdown([f], {\"files\": 1, \"added_lines\": 3,\n                               \"knowledge_entries\": 1, \"knowledge_grounded\": 1})\n    assert \"(knowledge: PR41-I1)\" in md\n    assert \"1 finding(s) cite a ledger entry\" in md\n\n\ndef test_score_knowledge_requires_both_catch_and_citation():\n    from eval.run_eval import _score_knowledge\n    expected = [{\"rule\": \"BUG\", \"file\": \"src/A.java\", \"knowledge_ref\": \"PR41-I1\"}]\n    caught_and_cited = [{\"rule\": \"BUG\", \"file\": \"src/A.java\",\n                         \"knowledge_ref\": [\"PR41-I1\"]}]\n    caught_only = [{\"rule\": \"BUG\", \"file\": \"src/A.java\", \"knowledge_ref\": []}]\n    cited_elsewhere = [{\"rule\": \"NAMING\", \"file\": \"src/A.java\",\n                        \"knowledge_ref\": [\"PR41-I1\"]}]\n    assert _score_knowledge(expected, caught_and_cited)[0] == 1.0\n    assert _score_knowledge(expected, caught_only)[0] == 0.0\n    assert _score_knowledge(expected, cited_elsewhere)[0] == 0.0\n    assert _score_knowledge([{\"rule\": \"BUG\"}], caught_only) is None   # \u975e\u77e5\u8b58\u984c\n\n\n# ========== Phase 3\uff1a\u6aa2\u7d22\u6392\u5e8f\uff08tier\uff09\u8207\u5206\u7d1a\u964d\u8f09 ==========\n\ndef test_page_tier_ordering(kroot):\n    from orchestrator.knowledge import _MatchCtx\n    changed = [\"src/main/java/com/acme/cache/SessionCache.java\",\n               \"src/main/java/com/acme/pricing/PricingService.java\"]\n    ctx = _MatchCtx(changed)\n    exact = _seed_page(kroot, \"r\", \"cache/SessionCache.md\", changed[0],\n                       [(\"PR1-I1\", \"x\")])\n    # \u540c (parent, stem) \u4f46\u4f4f\u5728\u53e6\u4e00\u68f5\u5b50\u6a39\u7684\u5be6\u9ad4\uff1a\u6a94\u540d\u547d\u4e2d\uff0c\u4e0d\u662f\u7cbe\u78ba\u8def\u5f91\u547d\u4e2d\n    other = _seed_page(kroot, \"r\", \"pricing/PricingService.md\",\n                       \"src/legacy/pricing/PricingService.java\", [(\"PR2-I1\", \"y\")])\n    neigh = _seed_page(kroot, \"r\", \"cfg/CacheConfig.md\",\n                       \"src/main/java/com/acme/cfg/CacheConfig.java\",\n                       [(\"PR3-I1\", \"z\")], affected=[\"SessionCache.java\"])\n    mod = _seed_page(kroot, \"r\", \"_module/cache.md\", \"(module)\", [(\"PR4-I1\", \"w\")])\n    miss = _seed_page(kroot, \"r\", \"far/Unrelated.md\",\n                      \"src/main/java/com/acme/far/Unrelated.java\", [(\"PR5-I1\", \"v\")])\n\n    def tier(page):\n        return ctx.page_hit(page, page.relative_to(kroot / \"r\"),\n                            page.read_text(encoding=\"utf-8\"))\n\n    assert tier(exact) == 4\n    assert tier(other) == 3          # \u540c (parent, stem)\uff0c\u4f46 entity \u8def\u5f91\u4e0d\u540c\n    assert tier(neigh) == 2          # Affected entities \u9130\u63a5\n    assert tier(mod) == 1            # _module \u8def\u5f91\u6bb5\n    assert tier(miss) == 0\n    assert ctx.entry_tier(changed[0], []) == 4\n    assert ctx.entry_tier(\"src/legacy/pricing/PricingService.java\", []) == 3\n    assert ctx.entry_tier(\"src/x/SessionCache.java\", []) == 3\n    assert ctx.entry_tier(\"src/x/Nope.java\", [\"SessionCache.java\"]) == 2\n    assert ctx.entry_tier(\"src/x/Nope.java\", []) == 0\n\n\ndef test_load_for_guarantees_primary_and_degrades_the_rest(kroot, monkeypatch):\n    \"\"\"\u9810\u7b97\u6975\u5c0f\u6642\uff1atier 4 \u4ecd\u4fdd\u8b49\u5165\u5834\uff08\u964d\u70ba Invariants \u6bb5\uff09\uff0c\u8f03\u5f31\u7684\u547d\u4e2d\u7559\u8a3b\u8a18\u3002\"\"\"\n    from orchestrator.knowledge import load_for\n    changed = [\"src/main/java/com/acme/cache/SessionCache.java\"]\n    _seed_page(kroot, \"repo-a\", \"cache/SessionCache.md\", changed[0],\n               [(\"PR41-I1\", \"ttl is millis\")], pad=4000)\n    # \u9130\u63a5\u547d\u4e2d\u7684\u90a3\u9801\u9023\u300c\u53ea\u6ce8\u5165 Invariants \u6bb5\u300d\u90fd\u585e\u4e0d\u4e0b \u2192 \u5b83\u624d\u662f\u88ab\u7701\u7565\u7684\u90a3\u500b\n    _seed_page(kroot, \"repo-a\", \"cfg/CacheConfig.md\",\n               \"src/main/java/com/acme/cfg/CacheConfig.java\",\n               [(\"PR42-I1\", \"config is seconds \" + \"y\" * 1200)],\n               affected=[\"SessionCache.java\"], pad=4000)\n    monkeypatch.setenv(\"KNOWLEDGE_MAX_CHARS\", \"900\")\n    text, stats = load_for(\"repo-a\", changed)\n    assert stats[\"knowledge_full\"] == 0\n    assert stats[\"knowledge_invariants_only\"] == 1        # tier 4 \u4fdd\u8b49\u5165\u5834\n    assert stats[\"knowledge_omitted\"] == 1\n    assert \"PR41-I1\" in stats[\"knowledge_ids\"]\n    assert \"PR42-I1\" not in stats[\"knowledge_ids\"]\n    assert \"invariants only\" in text and \"more matched entries omitted\" in text\n    assert \"CacheConfig\" in text.split(\"more matched entries omitted\")[1]\n\n\ndef test_load_for_orders_by_tier_not_by_walk_order(kroot):\n    from orchestrator.knowledge import load_for\n    changed = [\"src/main/java/com/acme/zone/ZoneRouter.java\"]\n    _seed_page(kroot, \"repo-a\", \"aaa/Neighbour.md\",\n               \"src/main/java/com/acme/aaa/Neighbour.java\",\n               [(\"PR10-I1\", \"neighbour rule\")], affected=[\"ZoneRouter.java\"])\n    _seed_page(kroot, \"repo-a\", \"zone/ZoneRouter.md\", changed[0],\n               [(\"PR20-I1\", \"compare with equals\")])\n    text, _ = load_for(\"repo-a\", changed)\n    assert text.index(\"ZoneRouter\") < text.index(\"Neighbour\")   # \u7cbe\u78ba\u547d\u4e2d\u5728\u524d\n\n\n# ========== Phase 4\uff1a\u84b8\u993e\u8003\u5377\u7684\u78ba\u5b9a\u6027\u8a08\u5206\uff08\u542b\u4e09\u984c\u9677\u9631\u7684\u5224\u6cd5\uff09 ==========\n\ndef _distill_expect(**kw):\n    exp = {\"intent_stated\": True, \"retires_id\": None, \"must_mention\": [],\n           \"primary_entity\": \"src/main/java/com/acme/cache/SessionCache.java\"}\n    exp.update(kw)\n    return exp\n\n\ndef _distill_draft(**kw):\n    d = {\"summary\": \"ttl boundary is milliseconds\", \"type\": \"bugfix\",\n         \"intent_stated\": True,\n         \"primary_entity\": \"src/main/java/com/acme/cache/SessionCache.java\",\n         \"decisions\": [{\"text\": \"chose millisecond boundary\",\n                        \"evidence\": [\"SessionCache.java:12\"]}],\n         \"invariants\": [], \"supersedes\": [], \"affected\": [],\n         \"ledger_line\": \"ttl unit fixed\"}\n    d.update(kw)\n    return d\n\n\ndef _clean_info(**kw):\n    info = {\"dropped\": [], \"evidence_stripped\": 0, \"primary_fixed\": False}\n    info.update(kw)\n    return info\n\n\ndef test_score_distill_perfect_paper():\n    from eval.run_distill_eval import score_distill\n    rows, score = score_distill(_distill_expect(must_mention=[\"millisecond\"]),\n                                _distill_draft(), _clean_info(), [])\n    assert score == 1.0\n    assert {n for n, _, _ in rows} == {\"intent_ok\", \"retires_ok\", \"evidence_ok\",\n                                       \"must_mention\", \"primary_ok\"}\n\n\ndef test_score_distill_traps():\n    \"\"\"\u4e09\u984c\u9677\u9631\u5404\u81ea\u7684\u5224\u6cd5\uff1a\u7de8 rationale / \u63a8\u8ad6 supersede / \u5e7b\u89ba\u4e0d\u8b8a\u5f0f\u3002\"\"\"\n    from eval.run_distill_eval import score_distill\n\n    def val(rows, name):\n        return next(v for n, v, _ in rows if n == name)\n\n    # \u2460 why \u7f3a\u5e2d\uff1aintent_stated \u8aaa\u4e86\u8b0a\uff0c\u4e14\u689d\u76ee\u88e1\u5192\u51fa rationale \u63aa\u8fad\n    rows, _ = score_distill(\n        _distill_expect(intent_stated=False,\n                        forbidden_mention=[\"because\", \"so that\"]),\n        _distill_draft(intent_stated=True,\n                       decisions=[{\"text\": \"raised the batch size because \"\n                                           \"throughput was low\",\n                                   \"evidence\": [\"SessionCache.java:12\"]}]),\n        _clean_info(), [])\n    assert val(rows, \"intent_ok\") == 0.0 and val(rows, \"no_fabrication\") == 0.0\n\n    # \u2461 supersede \u5047\u8a0a\u865f\uff1a\u6c92\u6709\u660e\u793a\u53cd\u8f49\u537b\u586b\u4e86 retires_id\uff08\u8aa4\u6bba\u4e00\u689d\u9084\u6709\u6548\u7684\u898f\u5247\uff09\n    rows, _ = score_distill(\n        _distill_expect(),\n        _distill_draft(supersedes=[{\"entity\": \"FeatureFlags\",\n                                    \"what\": \"per-request reads\",\n                                    \"retires_id\": \"PR44-I1\"}]),\n        _clean_info(), [])\n    assert val(rows, \"retires_ok\") == 0.0\n    # \u53cd\u904e\u4f86\uff1a\u8a72\u9ede\u540d\u537b\u9ede\u932f ID \u2014\u2014 \u4e00\u6a23\u6263\uff08\u8aa4\u6bba\u5225\u689d\u6bd4\u6f0f\u6a19\u66f4\u8cb4\uff09\n    rows, _ = score_distill(\n        _distill_expect(retires_id=\"PR31-I1\"),\n        _distill_draft(supersedes=[{\"entity\": \"WriteClient\", \"what\": \"retries\",\n                                    \"retires_id\": \"PR31-I2\"}]),\n        _clean_info(), [])\n    assert val(rows, \"retires_ok\") == 0.0\n\n    # \u2462 \u5e7b\u89ba\u4e0d\u8b8a\u5f0f\uff1a\u6750\u6599\u6490\u4e0d\u8d77\u4efb\u4f55 invariant\uff0c\u84b8\u51fa\u4f86\u5c31\u6263\n    rows, _ = score_distill(\n        _distill_expect(forbid_invariants=True),\n        _distill_draft(invariants=[{\"id\": \"PR1-I1\", \"text\": \"javadoc must be \"\n                                                            \"spelled correctly\"}]),\n        _clean_info(), [])\n    assert val(rows, \"no_hallucination\") == 0.0\n\n\ndef test_score_distill_evidence_and_primary():\n    from eval.run_distill_eval import score_distill\n\n    def val(rows, name):\n        return next(v for n, v, _ in rows if n == name)\n\n    rows, _ = score_distill(_distill_expect(), _distill_draft(),\n                            _clean_info(evidence_stripped=1), [])\n    assert val(rows, \"evidence_ok\") == 0.0            # \u6709 evidence \u88ab\u525d = \u6c92\u904e\u95dc\n    rows, _ = score_distill(_distill_expect(), _distill_draft(),\n                            _clean_info(dropped=[\"a decision with no proof\"]), [])\n    assert val(rows, \"evidence_ok\") == 0.0\n    rows, _ = score_distill(_distill_expect(), _distill_draft(),\n                            _clean_info(primary_fixed=True), [])\n    assert val(rows, \"primary_ok\") == 0.0             # \u9760 fallback \u6551\u56de\u4e0d\u7b97\u5206\n    rows, _ = score_distill(\n        _distill_expect(primary_entity=\"src/main/java/com/acme/other/X.java\"),\n        _distill_draft(), _clean_info(), [])\n    assert val(rows, \"primary_ok\") == 0.0             # \u9328\u932f\u5be6\u9ad4\n    rows, _ = score_distill(_distill_expect(must_mention=[\"millisecond\", \"floor\"]),\n                            _distill_draft(), _clean_info(), [])\n    assert val(rows, \"must_mention\") == 0.5\n\n\n# ========== Phase 5\uff1astale \u91cd\u84b8\uff08\u8acb\u6c42\u6233 / \u91cd\u8a66\u4e0a\u9650 / \u8986\u5beb / provenance\uff09 ==========\n\ndef _pending(kroot, pid=90, **extra):\n    from orchestrator.knowledge import write_json_atomic\n    f = kroot / \"_pending\" / \"repo-a\" / f\"pr-{pid}.json\"\n    write_json_atomic(f, {\n        \"pr_url\": f\"https://x/C/P/_git/repo-a/pullrequest/{pid}\",\n        \"pr_id\": pid, \"repo\": \"repo-a\", \"base_url\": \"https://x/C/P\",\n        \"target_branch\": \"release/x\", \"distilled_commit\": \"sha-OLD\",\n        \"author\": \"a\", \"thread_id\": 7, \"posted\": True, \"dry_run\": False,\n        \"draft\": _draft(\"src/x/F.java\"), \"created\": \"t\", **extra})\n    return f\n\n\ndef _completed_pr(merge=\"sha-NEW\"):\n    return {\"status\": \"completed\", \"lastMergeSourceCommit\": {\"commitId\": merge},\n            \"createdBy\": {\"id\": \"author-1\"}}\n\n\ndef test_stale_requests_redistill_then_gives_up(kroot, monkeypatch):\n    \"\"\"\u6233 + attempts \u2264 2\uff1a30 \u5206\u9418\u4e00\u8f2a\u7684 timer \u4e0d\u6703\u8b8a\u6210\u7121\u754c\u7684 LLM \u91cd\u8a66\u8ff4\u5708\u3002\"\"\"\n    from orchestrator import knowledge_harvest as H\n    calls = []\n    monkeypatch.setattr(H, \"_get_pr\", lambda c, r: _completed_pr())\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_request_redistill\",\n                        lambda url: (calls.append(url) or (True, \"\u5df2\u8acb\u6c42\u91cd\u84b8\")))\n    pend = _pending(kroot)\n\n    out = H._process_pending(object(), kroot, pend)\n    assert \"\u8acb\u6c42\u91cd\u84b8\uff08\u7b2c 1/2 \u6b21\" in out and len(calls) == 1\n    stamp = json.loads(pend.read_text(encoding=\"utf-8\"))[\"redistill_requested\"]\n    assert stamp == {\"commit\": \"sha-NEW\", \"attempts\": 1}\n    assert pend.exists()                              # \u7a3f\u7559\u8457\u7b49\u91cd\u84b8\n\n    out = H._process_pending(object(), kroot, pend)   # \u80cc\u666f\u5931\u6557\u4e86 \u2192 \u518d\u4e00\u6b21\n    assert \"\u7b2c 2/2 \u6b21\" in out and len(calls) == 2\n    assert json.loads(pend.read_text(encoding=\"utf-8\"))[\"redistill_requested\"] \\\n        == {\"commit\": \"sha-NEW\", \"attempts\": 2}\n\n    out = H._process_pending(object(), kroot, pend)   # \u5169\u6b21\u90fd\u6c92\u6210 \u2192 \u4e1f\u7a3f\n    assert \"\u91cd\u84b8\u5169\u6b21\u672a\u6210\" in out and not pend.exists() and len(calls) == 2\n\n\ndef test_stale_gives_up_when_a_newer_push_lands_mid_redistill(kroot, monkeypatch):\n    from orchestrator import knowledge_harvest as H\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_request_redistill\", lambda url: (True, \"ok\"))\n    monkeypatch.setattr(H, \"_get_pr\", lambda c, r: _completed_pr(\"sha-NEWER\"))\n    pend = _pending(kroot, redistill_requested={\"commit\": \"sha-NEW\", \"attempts\": 1})\n    out = H._process_pending(object(), kroot, pend)\n    assert \"\u4e16\u4ee3\u8b8a\u66f4\" in out and not pend.exists()\n\n\ndef test_stale_falls_back_to_dropping_when_redistill_is_off(kroot, monkeypatch):\n    from orchestrator import knowledge_harvest as H\n    monkeypatch.setenv(\"KNOWLEDGE_REDISTILL\", \"false\")\n    monkeypatch.setattr(H, \"_get_pr\", lambda c, r: _completed_pr())\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_request_redistill\",\n                        lambda url: pytest.fail(\"\u95dc\u6389\u4e86\u9084\u6253 endpoint\"))\n    pend = _pending(kroot)\n    out = H._process_pending(object(), kroot, pend)\n    assert \"stale \u4e1f\u7a3f\" in out and \"KNOWLEDGE_REDISTILL=false\" in out\n    assert not pend.exists()\n\n\ndef test_stale_keeps_author_reply_for_the_redistill_material(kroot, monkeypatch):\n    from orchestrator import knowledge_harvest as H\n    monkeypatch.setattr(H, \"_get_pr\", lambda c, r: _completed_pr())\n    monkeypatch.setattr(H, \"_request_redistill\", lambda url: (True, \"ok\"))\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: [{\n        \"id\": 7, \"comments\": [\n            {\"author\": {\"id\": \"bot\"}, \"content\": \"draft\"},\n            {\"author\": {\"id\": \"author-1\"}, \"content\": \"we chose X over Y\"}]}])\n    pend = _pending(kroot)\n    H._process_pending(object(), kroot, pend)\n    assert json.loads(pend.read_text(encoding=\"utf-8\"))[\"author_note\"] \\\n        == \"we chose X over Y\"\n\n\ndef test_redistilled_draft_stages_with_visible_provenance(kroot, monkeypatch):\n    \"\"\"\u91cd\u84b8\u904e\u7684\u7a3f\u843d\u5730\u6642 provenance \u6524\u958b\u8aaa\uff1a\u5167\u5bb9\u662f\u91cd\u84b8\u4f86\u7684\u3001\u4f5c\u8005\u6709\u6c92\u6709\u8aaa\u904e\u8a71\u3002\"\"\"\n    from orchestrator import knowledge_harvest as H\n    monkeypatch.setattr(H, \"_get_pr\", lambda c, r: _completed_pr(\"sha-NEW\"))\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: [])   # thread \u8b80\u4e0d\u5230\n    pend = _pending(kroot, distilled_commit=\"sha-NEW\", redistilled=True,\n                    author_note=\"kept from the earlier draft\")\n    out = H._process_pending(object(), kroot, pend)\n    assert \"staged\uff08explicit\u00b7redistilled\" in out\n    staged = json.loads((kroot / \"_cycle\" / \"repo-a\" / \"pr-90.json\")\n                        .read_text(encoding=\"utf-8\"))\n    assert staged[\"provenance\"] == \"explicit\u00b7redistilled\"\n    assert staged[\"author_note\"] == \"kept from the earlier draft\"\n\n    pend2 = _pending(kroot, pid=91, distilled_commit=\"sha-NEW\", redistilled=True)\n    H._process_pending(object(), kroot, pend2)\n    staged2 = json.loads((kroot / \"_cycle\" / \"repo-a\" / \"pr-91.json\")\n                         .read_text(encoding=\"utf-8\"))\n    assert staged2[\"provenance\"] == \"silent\u00b7redistilled\"      # \u6c92\u4eba\u8aaa\u904e\u8a71\n\n\ndef test_redistill_overwrites_pending_and_clears_stale_traces(kroot, monkeypatch):\n    \"\"\"\u91cd\u84b8\uff1a\u6700\u7d42 diff \u91cd\u84b8 \u2192 \u8986\u5beb _pending\u3001\u56de\u8986\u9032\u539f thread\u3001\u6e05\u6389\u820a\u7684\u300e\u5df2\u5217\u300f\u3002\"\"\"\n    from orchestrator import knowledge as K\n    pend = _pending(kroot, author_note=\"the author said this earlier\",\n                    redistill_requested={\"commit\": \"sha-NEW\", \"attempts\": 1})\n    # \u820a\u7684\u66ab\u5b58\u7a3f + \u5df2\u5217\u72c0\u614b\uff08\u624b\u52d5\u88dc\u84b8\u7684\u60c5\u5883\uff09\uff1a\u90fd\u5fc5\u9808\u88ab\u4f5c\u5ee2\n    K.write_json_atomic(kroot / \"_cycle\" / \"repo-a\" / \"pr-90.json\",\n                        {\"pr_id\": 90, \"rejected_ids\": [\"PR90-I1\"],\n                         \"draft\": _draft(\"src/x/F.java\")})\n    K.write_json_atomic(kroot / \"_state\" / \"cycle.json\",\n                        {\"repo-a#500\": {\"listed\": [\"PR70\", \"PR90\"],\n                                        \"digest\": True}})\n    diff = (\"--- a/src/x/F.java\\n+++ b/src/x/F.java\\n@@ -10,3 +10,4 @@\\n\"\n            \" c10\\n+a11\\n c12\\n c13\\n\")\n    seen = {}\n\n    async def f_meta(u):\n        return {\"title\": \"t\", \"description\": \"d\" * 60, \"source_commit\": \"sha-NEW\",\n                \"target_branch\": \"release/x\"}\n\n    async def f_diff(u):\n        return diff\n\n    async def f_post(pr_url, markdown, thread_id=None):\n        seen[\"thread_id\"] = thread_id\n        seen[\"markdown\"] = markdown\n        return {\"posted\": True, \"dry_run\": False, \"reply\": True,\n                \"thread_id\": thread_id}\n\n    async def f_complete(system, user, **kw):\n        seen[\"user\"] = user\n        return json.dumps({\n            \"summary\": \"redistilled from the final diff\", \"type\": \"bugfix\",\n            \"intent_stated\": True, \"primary_entity\": \"src/x/F.java\",\n            \"decisions\": [{\"text\": \"kept the guard\", \"evidence\": [\"F.java:11\"]},\n                          {\"text\": \"no proof at all\", \"evidence\": [\"F2\"]}],\n            \"invariants\": [\"the guard stays\"], \"supersedes\": [], \"affected\": [],\n            \"ledger_line\": \"guard kept\"})\n\n    monkeypatch.setattr(K.clients, \"fetch_pr_metadata\", f_meta)\n    monkeypatch.setattr(K.clients, \"fetch_pr_diff\", f_diff)\n    monkeypatch.setattr(K.clients, \"post_knowledge_draft\", f_post)\n    monkeypatch.setattr(K, \"prompt_or\", lambda name, default: \"SYSTEM\")\n    monkeypatch.setattr(K, \"complete\", f_complete)\n\n    asyncio.run(K.redistill(\"https://x/C/P/_git/repo-a/pullrequest/90\"))\n\n    info = json.loads(pend.read_text(encoding=\"utf-8\"))\n    assert info[\"redistilled\"] is True and info[\"redistill_of\"] == \"sha-OLD\"\n    assert info[\"distilled_commit\"] == \"sha-NEW\"\n    assert \"redistill_requested\" not in info                  # \u6233\u88ab\u6d88\u5316\u6389\u4e86\n    assert info[\"draft\"][\"summary\"] == \"redistilled from the final diff\"\n    assert [d[\"id\"] for d in info[\"draft\"][\"decisions\"]] == [\"PR90-D1\"]\n    assert info[\"distill_dropped\"] == [\"no proof at all\"]      # F \u7de8\u865f\u5df2 stale\n    assert info[\"evidence_verified\"] is True\n    # \u820a\u75d5\u8de1\u4f5c\u5ee2\uff1a\u66ab\u5b58\u7a3f\u79fb\u9664\u3001listed \u79fb\u9664 PR90\uff08\u4e0b\u4e00\u5247 delta \u6703\u91cd\u65b0\u5217\u5b83\uff09\n    assert not (kroot / \"_cycle\" / \"repo-a\" / \"pr-90.json\").exists()\n    state = json.loads((kroot / \"_state\" / \"cycle.json\").read_text(encoding=\"utf-8\"))\n    assert state[\"repo-a#500\"][\"listed\"] == [\"PR70\"]\n    # \u6750\u6599\uff1a\u5e36\u4f5c\u8005\u539f\u8a71\u3001\u4e0d\u542b\u820a review \u5831\u544a\n    assert \"the author said this earlier\" in seen[\"user\"]\n    assert \"Review report\" not in seen[\"user\"]\n    assert seen[\"thread_id\"] == 7                              # \u56de\u8986\u9032\u539f thread\n    assert \"1 decision(s) dropped\" in seen[\"markdown\"]\n\n\ndef test_redistill_is_once_per_pr(kroot, monkeypatch):\n    from orchestrator import knowledge as K\n    pend = _pending(kroot, redistilled=True)\n    before = pend.read_text(encoding=\"utf-8\")\n\n    async def boom(*a, **k):\n        raise AssertionError(\"\u5df2\u91cd\u84b8\u904e\u7684\u7a3f\u4e0d\u8a72\u518d\u6253 ADO\")\n\n    monkeypatch.setattr(K.clients, \"fetch_pr_metadata\", boom)\n    asyncio.run(K.redistill(\"https://x/C/P/_git/repo-a/pullrequest/90\"))\n    assert pend.read_text(encoding=\"utf-8\") == before\n\n\ndef test_knowledge_draft_thread_reply_is_a_reply_not_a_new_thread(monkeypatch):\n    from orchestrator.adapters import ado as S\n    monkeypatch.setenv(\"KNOWLEDGE_POST\", \"false\")\n    url = \"https://x/C/P/_git/repo-a/pullrequest/90\"\n    fresh = S.post_knowledge_draft(url, \"body\")\n    reply = S.post_knowledge_draft(url, \"body\", thread_id=7)\n    assert fresh[\"would_post_to\"].endswith(\"/threads\")\n    assert reply[\"would_post_to\"].endswith(\"/threads/7/comments\")\n    assert reply[\"reply\"] is True and reply[\"dry_run\"] is True\n    assert \"Draft updated after new commits\" in reply[\"preview\"]\n\n\ndef test_reviewer_knowledge_ref_shape_is_coerced_not_fatal(monkeypatch):\n    \"\"\"\u5f15\u7528\u6b04\u4f4d\u5beb\u6b6a\uff08\u55ae\u503c / \u6df7\u578b\u5225 / \u4e82\u5f62\u72c0\uff09\u4e0d\u8a72\u8b93\u6574\u689d finding \u88ab pydantic \u4e1f\u6389\u3002\"\"\"\n    from orchestrator import pipeline as P\n    from orchestrator.rules import RulesBundle\n    ana = parse_diff(\"--- a/src/A.java\\n+++ b/src/A.java\\n@@ -1,1 +1,2 @@\\n a\\n+b\\n\")\n\n    async def fake(system, user, **kw):\n        return json.dumps({\"assessment\": \"a\", \"findings\": [\n            {\"rule\": \"BUG\", \"file\": \"src/A.java\", \"line\": 2,\n             \"severity\": \"warning\", \"note\": \"n1\", \"knowledge_ref\": \"PR1-I1\"},\n            {\"rule\": \"PERF\", \"file\": \"src/A.java\", \"line\": 2, \"severity\": \"info\",\n             \"note\": \"n2\", \"knowledge_ref\": [12, \"PR1-I2\", \"\"]},\n            {\"rule\": \"NAMING\", \"file\": \"src/A.java\", \"line\": 2, \"severity\": \"info\",\n             \"note\": \"n3\", \"knowledge_ref\": {\"bad\": \"shape\"}}]})\n\n    monkeypatch.setattr(P, \"complete\", fake)\n    monkeypatch.setattr(P, \"prompt_or\", lambda name, default: default)\n    dim = P._Dim(name=\"X\", focus=\"f\", hypotheses=[], files=[], rules=[])\n    _assessment, finds, _checks, _loc = asyncio.run(\n        P._review_one(dim, ana, RulesBundle(), \"\", \"\"))\n    assert [f.knowledge_ref for f in finds] == [[\"PR1-I1\"], [\"12\", \"PR1-I2\"], []]\n\n\ndef test_redistill_does_not_resurrect_a_dropped_draft(kroot, monkeypatch):\n    \"\"\"\u6536\u5272\u5668\u5728\u91cd\u84b8\u671f\u9593\u5224\u6b7b\u9019\u689d\u7a3f\uff08\u91cd\u8a66\u7528\u76e1 / \u4e16\u4ee3\u8b8a\u66f4\uff09\u2192 \u91cd\u84b8\u4e0d\u5f97\u628a\u5b83\u5beb\u56de\u4f86\u3002\"\"\"\n    from orchestrator import knowledge as K\n    pend = _pending(kroot)\n    diff = (\"--- a/src/x/F.java\\n+++ b/src/x/F.java\\n@@ -10,3 +10,4 @@\\n\"\n            \" c10\\n+a11\\n c12\\n c13\\n\")\n\n    async def f_meta(u):\n        return {\"title\": \"t\", \"description\": \"d\" * 60, \"source_commit\": \"sha-NEW\",\n                \"target_branch\": \"release/x\"}\n\n    async def f_diff(u):\n        pend.unlink()                 # \u84b8\u5230\u4e00\u534a\uff0c\u6536\u5272\u5668\u628a\u7a3f\u4e1f\u4e86\n        return diff\n\n    async def f_post(pr_url, markdown, thread_id=None):\n        return {\"posted\": True, \"dry_run\": False, \"thread_id\": thread_id}\n\n    async def f_complete(system, user, **kw):\n        return json.dumps({\"summary\": \"s\", \"type\": \"bugfix\",\n                           \"intent_stated\": True, \"primary_entity\": \"src/x/F.java\",\n                           \"decisions\": [{\"text\": \"d\", \"evidence\": [\"F.java:11\"]}],\n                           \"invariants\": [], \"supersedes\": [], \"affected\": [],\n                           \"ledger_line\": \"l\"})\n\n    monkeypatch.setattr(K.clients, \"fetch_pr_metadata\", f_meta)\n    monkeypatch.setattr(K.clients, \"fetch_pr_diff\", f_diff)\n    monkeypatch.setattr(K.clients, \"post_knowledge_draft\", f_post)\n    monkeypatch.setattr(K, \"prompt_or\", lambda name, default: \"SYSTEM\")\n    monkeypatch.setattr(K, \"complete\", f_complete)\n\n    asyncio.run(K.redistill(\"https://x/C/P/_git/repo-a/pullrequest/90\"))\n    assert not pend.exists()\n\n\ndef test_post_knowledge_draft_forwards_thread_id_to_the_adapter(monkeypatch):\n    \"\"\"S1 \u4e4b\u5f8c \u2462 \u4f4f\u5728\u540c\u4e00\u500b\u884c\u7a0b\uff1aclients \u53ea\u662f to_thread \u7684\u6bbc\uff0cthread_id \u5fc5\u9808\u539f\u6a23\u5230 adapter\n    \uff08\u91cd\u84b8\u7684\u66f4\u65b0\u7a3f\u8981\u56de\u9032\u4f5c\u8005\u56de\u904e\u8a71\u7684\u90a3\u4e32\uff0c\u4e0d\u80fd\u958b\u65b0 thread\uff09\u3002\"\"\"\n    from orchestrator import clients\n    from orchestrator.adapters import ado\n    sent = []\n    monkeypatch.setattr(ado, \"post_knowledge_draft\",\n                        lambda pr_url, md, thread_id=None: sent.append((pr_url, md, thread_id))\n                        or {\"posted\": True})\n    asyncio.run(clients.post_knowledge_draft(\"u\", \"md\"))\n    asyncio.run(clients.post_knowledge_draft(\"u\", \"md\", thread_id=7))\n    assert sent == [(\"u\", \"md\", None), (\"u\", \"md\", 7)]\n\n\ndef test_cycle_close_first_sight_does_not_backfill(kroot, monkeypatch):\n    \"\"\"\u9996\u898b\u6c34\u4f4d\uff1a\u6b77\u53f2\u4e0a\u65e9\u5c31 completed \u7684\u9a57\u6536 PR \u4e0d\u5f97\u6536\u53e3\u7576\u4e0b\u66ab\u5b58\u7684\u7a3f\u3002\n\n    \u300c\u54ea\u4e9b\u9a57\u6536 PR \u7d50\u7b97\u904e\u300d\u53ea\u8a18\u5728 _state/cycle.json\uff0c\u800c\u5b83\u4f4f\u5728 KNOWLEDGE_ROOT\u2014\u2014\n    \u5e33\u672c\u91cd\u65b0 clone\u3001_state \u6389\u4e86\u3001\u6216\u6e05\u7a7a KB \u91cd\u6e2c\uff0c\u8a18\u61b6\u5c31\u6c92\u4e86\uff0c\u4f46 ADO \u7684\u6b77\u53f2\n    \u4e00\u689d\u90fd\u6c92\u5c11\u3002\u5c11\u4e86\u9019\u500b\u5224\u65b7\uff0c\u4e0a\u500b\u6708\u7684\u9a57\u6536 PR \u6703\u628a\u4eca\u5929\u525b\u66ab\u5b58\u7684\u7a3f\u7acb\u523b\u843d\u5730\uff0c\n    \u800c\u90a3\u6279\u7a3f\u6c92\u6709\u4efb\u4f55\u4eba\u5728\u4efb\u4f55 digest \u4e0a\u770b\u904e\u3002\n    \"\"\"\n    from orchestrator import knowledge_harvest as H\n    (kroot / \"_state\").mkdir()\n    (kroot / \"_state\" / \"repos.json\").write_text(\n        json.dumps({\"repo-a\": \"https://x/C/P\"}))\n    completed = [{\"pullRequestId\": 400, \"sourceRefName\": \"refs/heads/release/x\",\n                  \"targetRefName\": \"refs/heads/master\",\n                  \"closedDate\": \"2026-01-01T00:00:00Z\"}]        # \u4e0a\u4e00\u8f2a\u7684\n    monkeypatch.setattr(H, \"client\", lambda: contextlib.nullcontext(object()))\n    monkeypatch.setattr(H, \"_post_thread\", lambda c, r, t: None)\n    monkeypatch.setattr(H, \"_list_active\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_list_completed\", lambda c, r: completed)\n\n    _stage(kroot, 70, \"src/x/A.java\")                # \u4eca\u5929\u525b\u66ab\u5b58\u7684\u7a3f\n    lines = H._cycle_close(object(), kroot)\n    assert any(\"\u9996\u898b\" in ln and \"\u4e0d\u56de\u586b\" in ln for ln in lines)\n    assert not (kroot / \"repo-a\" / \"x\" / \"A.md\").exists()        # \u6c92\u6709\u88ab\u843d\u5730\n    assert (kroot / \"_cycle\" / \"repo-a\" / \"pr-70.json\").exists()  # \u7a3f\u9084\u5728\u6c60\u88e1\n    st = json.loads((kroot / \"_state\" / \"cycle.json\").read_text())\n    assert st[\"repo-a#400\"][\"closed\"] is True                   # \u4f46\u4e0d\u6703\u518d\u554f\u4e00\u6b21\n\n    # \u4e4b\u5f8c\u771f\u7684\u6709\u4e00\u689d\u9a57\u6536 PR \u5b8c\u6210 \u2192 \u7167\u5e38\u6536\u53e3\n    completed.append({\"pullRequestId\": 401,\n                      \"sourceRefName\": \"refs/heads/release/x\",\n                      \"targetRefName\": \"refs/heads/master\", \"closedDate\": \"z\"})\n    lines = H._cycle_close(object(), kroot)\n    assert any(\"\u9a57\u6536 PR#401 \u6536\u53e3\" in ln for ln in lines)\n    assert (kroot / \"repo-a\" / \"x\" / \"A.md\").exists()\n    assert not (kroot / \"_cycle\" / \"repo-a\" / \"pr-70.json\").exists()\n\n\ndef test_retired_invariants_stay_on_the_page_but_leave_the_injection(kroot):\n    \"\"\"\u8a3b\u92b7\u662f\u6a19\u8a18\u4e0d\u662f\u84b8\u767c\u2014\u2014\u9801\u9762\u7559\u8457\uff0c\u4f46\u6ce8\u5165\u7d66 reviewer \u7684\u5340\u584a\u4e0d\u5e36\u5b83\u3002\n\n    \u5e36\u8457\u5b83\uff0c\u6a21\u578b\u6703\u7167\u6a23\u62ff\u4e00\u689d\u6b7b\u6389\u7684\u898f\u5247\u5831 violation\uff08\u4f5c\u8005\u660e\u660e\u5df2\u7d93\u8aaa\u90a3\u500b\n    business \u9700\u6c42\u53d6\u6d88\u4e86\uff09\uff0c\u800c\u8aa4\u5831\u6bd4\u6f0f\u5831\u66f4\u5feb\u628a\u4fe1\u4efb\u71d2\u5149\u3002\n    \"\"\"\n    from orchestrator import knowledge_harvest as H\n    from orchestrator.knowledge import existing_invariants, load_for\n    H._land(kroot, \"repo-a\", 10,\n            _draft(\"src/a/Fee.java\", invariants=[\"Fee must be capped at 5%\",\n                                                 \"Fee is always BigDecimal\"]),\n            \"cycle/silent\", \"\")\n    H._land(kroot, \"repo-a\", 11,\n            _draft(\"src/a/Fee.java\",\n                   supersedes=[{\"entity\": \"Fee\", \"what\": \"cap removed\",\n                                \"retires_id\": \"PR10-I1\"}]),\n            \"cycle/explicit\", \"business requirement dropped\")\n\n    page = (kroot / \"repo-a\" / \"a\" / \"Fee.md\").read_text(encoding=\"utf-8\")\n    assert \"~~Fee must be capped at 5%~~ \u26a0 retired by PR#11\" in page   # \u8840\u7de3\u7559\u8457\n    assert existing_invariants(\"repo-a\", [\"src/a/Fee.java\"])[0][1] == [\n        (\"PR10-I2\", \"Fee is always BigDecimal\")]       # \u76ee\u9304\u65e9\u5c31\u4e0d\u5217\u5b83\n\n    text, stats = load_for(\"repo-a\", [\"src/a/Fee.java\"])\n    assert \"Fee must be capped\" not in text            # \u6ce8\u5165\u4e0d\u5e36\u6b7b\u898f\u5247\n    assert \"Fee is always BigDecimal\" in text          # \u6d3b\u7684\u7167\u5e38\n    assert stats[\"knowledge_ids\"] == [\"PR10-I2\"]       # \u4e5f\u4e0d\u80fd\u62ff\u5b83\u7576 grounding\n    assert stats[\"knowledge_retired_hidden\"] == 1      # \u64cb\u6389\u5e7e\u689d\uff0c\u6524\u5728 stats\n    assert \"business requirement dropped\" in text      # \u4f5c\u8005\u539f\u8a71\u4ecd\u5728\uff08\u662f\u8108\u7d61\uff09\n\n\n# ========== \u77db\u76fe\u88c1\u6c7a\uff1a\u5be6\u4f5c\u63a8\u7ffb\u898f\u5247 \u2192 \u9a57\u6536\u7a97\u6c7a\u5b9a\u62d4\u4e0d\u62d4 ==========\n\ndef _seed_rule(kroot, entity=\"src/a/Fee.java\", text=\"Fee must be capped at 5%\"):\n    \"\"\"\u5148\u8b93\u4e00\u689d\u898f\u5247\u843d\u5730\uff0c\u56de\u5b83\u7684 id\u3002\"\"\"\n    from orchestrator import knowledge_harvest as H\n    H._land(kroot, \"repo-a\", 10, _draft(entity, invariants=[text]),\n            \"cycle/silent\", \"\")\n    return \"PR10-I1\"\n\n\ndef _stage_contradicting(kroot, pid, iid, ent=\"src/a/Fee.java\"):\n    from orchestrator.knowledge import write_json_atomic\n    write_json_atomic(kroot / \"_cycle\" / \"repo-a\" / f\"pr-{pid}.json\", {\n        \"pr_url\": \"u\", \"pr_id\": pid, \"repo\": \"repo-a\",\n        \"base_url\": \"https://x/C/P\", \"target_branch\": \"release/x\",\n        \"draft\": _draft(ent, invariants=[f\"new rule from PR{pid}\"]),\n        \"author_note\": \"the business requirement was dropped\",\n        \"provenance\": \"explicit\", \"contradicted\": [iid]})\n\n\ndef _cycle_env(kroot, monkeypatch, threads=()):\n    from orchestrator import knowledge_harvest as H\n    (kroot / \"_state\").mkdir(exist_ok=True)\n    (kroot / \"_state\" / \"repos.json\").write_text(\n        json.dumps({\"repo-a\": \"https://x/C/P\"}))\n    (kroot / \"_state\" / \"cycle.json\").write_text(          # \u975e\u9996\u898b\n        json.dumps({\"repo-a#1\": {\"closed\": True}}))\n    monkeypatch.setattr(H, \"client\", lambda: contextlib.nullcontext(object()))\n    monkeypatch.setattr(H, \"_post_thread\", lambda c, r, t: None)\n    monkeypatch.setattr(H, \"_list_active\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: list(threads))\n    monkeypatch.setattr(H, \"_list_completed\", lambda c, r: [{\n        \"pullRequestId\": 500, \"sourceRefName\": \"refs/heads/release/x\",\n        \"targetRefName\": \"refs/heads/master\", \"closedDate\": \"z\"}])\n\n\ndef test_contradicted_invariant_is_retired_at_cycle_close(kroot, monkeypatch):\n    \"\"\"\u5e36\u8457\u77db\u76fe\u5b8c\u6210\u7684 PR = \u5be6\u4f5c\u63a8\u7ffb\u4e86\u898f\u5247\uff1b\u6c89\u9ed8\u5373\u63a5\u53d7 \u2192 \u6536\u53e3\u6642\u756b\u6389\u90a3\u689d\u3002\"\"\"\n    from orchestrator import knowledge_harvest as H\n    from orchestrator.knowledge import existing_invariants, load_for\n    iid = _seed_rule(kroot)\n    _stage_contradicting(kroot, 70, iid)\n    _cycle_env(kroot, monkeypatch)\n\n    lines = H._cycle_close(object(), kroot)\n    assert any(f\"\u62d4\u9664 {iid}\" in ln for ln in lines)\n    page = (kroot / \"repo-a\" / \"a\" / \"Fee.md\").read_text(encoding=\"utf-8\")\n    assert \"~~Fee must be capped at 5%~~ \u26a0 retired by PR#70\" in page   # \u756b\u6389\u4e0d\u522a\u9664\n    assert \"retired `PR10-I1`: contradicted by merged code\" in page    # History \u7559\u884c\n    assert \"new rule from PR70\" in page                                # \u65b0\u689d\u76ee\u7167\u6a23\u843d\u5730\n    # \u4e4b\u5f8c\u5169\u689d\u8b80\u53d6\u8def\u5f91\u90fd\u4e0d\u518d\u5e36\u5b83\n    assert all(i != iid for _, pairs in existing_invariants(\n        \"repo-a\", [\"src/a/Fee.java\"]) for i, _ in pairs)\n    assert \"Fee must be capped\" not in load_for(\"repo-a\", [\"src/a/Fee.java\"])[0]\n    receipt = next((kroot / \"repo-a\" / \"_cycles\").glob(\"*-PR500.md\")).read_text(\n        encoding=\"utf-8\")\n    assert \"Invariants retired this cycle\" in receipt\n\n\ndef test_keep_command_vetoes_the_retirement(kroot, monkeypatch):\n    \"\"\"\u4efb\u4f55\u4eba\u56de `keep PR10-I1` \u2192 \u672c\u9031\u671f\u4e0d\u62d4\uff0c\u898f\u5247\u539f\u5c01\u4e0d\u52d5\u3002\"\"\"\n    from orchestrator import knowledge_harvest as H\n    iid = _seed_rule(kroot)\n    _stage_contradicting(kroot, 71, iid)\n    _cycle_env(kroot, monkeypatch, threads=[{\"id\": 9, \"comments\": [\n        {\"content\": \"keep PR10-I1\\n\u9019\u689d\u9084\u8981\uff0c\u53ea\u662f\u9019\u652f\u4f8b\u5916\"}]}])\n\n    lines = H._cycle_close(object(), kroot)\n    assert any(f\"\u77db\u76fe {iid} \u4fdd\u7559\" in ln for ln in lines)\n    page = (kroot / \"repo-a\" / \"a\" / \"Fee.md\").read_text(encoding=\"utf-8\")\n    assert \"- Fee must be capped at 5% `PR10-I1`\" in page      # \u6c92\u88ab\u52d5\u904e\n    assert \"~~\" not in page\n\n\ndef test_contradiction_retirement_can_be_switched_off(kroot, monkeypatch):\n    from orchestrator import knowledge_harvest as H\n    monkeypatch.setenv(\"KNOWLEDGE_RETIRE_ON_CONTRADICTION\", \"false\")\n    iid = _seed_rule(kroot)\n    _stage_contradicting(kroot, 72, iid)\n    _cycle_env(kroot, monkeypatch)\n    lines = H._cycle_close(object(), kroot)\n    assert not any(\"\u62d4\u9664\" in ln for ln in lines)\n    assert \"~~\" not in (kroot / \"repo-a\" / \"a\" / \"Fee.md\").read_text(\n        encoding=\"utf-8\")\n\n\ndef test_retire_by_id_refuses_when_the_id_is_ambiguous_or_absent(kroot):\n    from orchestrator import knowledge_harvest as H\n    _seed_rule(kroot)\n    assert \"\u67e5\u7121\u6b64 ID\" in H._retire_by_id(kroot, \"repo-a\", \"PR99-I9\", 70)\n    # \u540c\u4e00\u500b ID \u51fa\u73fe\u5728\u5169\u9801\uff08\u4e0d\u8a72\u767c\u751f\uff0c\u4f46\u771f\u767c\u751f\u6642\u5be7\u53ef\u4e0d\u52d5\uff09\n    H._land(kroot, \"repo-a\", 11, _draft(\"src/b/Other.java\",\n                                        invariants=[\"dup\"]), \"cycle/silent\", \"\")\n    p = kroot / \"repo-a\" / \"b\" / \"Other.md\"\n    p.write_text(p.read_text(encoding=\"utf-8\").replace(\"`PR11-I1`\", \"`PR10-I1`\"),\n                 encoding=\"utf-8\")\n    assert \"\u649e\u5230 2 \u9801\" in H._retire_by_id(kroot, \"repo-a\", \"PR10-I1\", 70)\n\n\ndef test_digest_shows_contradictions_as_a_proposal(kroot):\n    from orchestrator import knowledge_digest as D\n    items = [{\"pr_id\": 70, \"provenance\": \"explicit\", \"author_note\": \"req dropped\",\n              \"contradicted\": [\"PR10-I1\"],\n              \"draft\": _draft(\"src/a/Fee.java\", invariants=[\"new rule\"])}]\n    md = D.render(items, None, None)\n    assert \"Invariants contradicted by merged code\" in md\n    assert \"`PR10-I1`\" in md and \"keep PR10-I1\" in md\n\n\ndef test_review_hands_the_distiller_its_diff_ids_and_contradictions(monkeypatch):\n    \"\"\"app \u2192 distiller \u7684\u63a5\u7dda\uff1a\u540c\u4e00\u4efd diff\u3001F \u7de8\u865f\u3001\u88ab\u8e29\u5230\u7684\u4e0d\u8b8a\u5f0f id\u3002\n\n    \u9019\u6bb5\u662f\u7d14\u63a5\u7dda\uff0c\u6700\u5bb9\u6613\u5728\u6539\u52d5\u88e1\u5b89\u975c\u65b7\u6389\uff08\u65b7\u4e86\u4e5f\u53ea\u6703 print \u4e00\u884c journal\uff09\uff0c\n    \u6240\u4ee5\u7528\u4e00\u689d\u6e2c\u8a66\u628a\u56db\u500b\u53c3\u6578\u91d8\u4f4f\u3002\n    \"\"\"\n    from orchestrator import app as A\n    from orchestrator.models import Finding\n    A._RECENT.clear()\n    captured = {}\n\n    async def f_meta(u):\n        return {\"repo\": \"r\", \"title\": \"t\", \"source_commit\": \"sha-X\",\n                \"target_branch\": \"refs/heads/release/x\"}\n\n    async def f_diff(u):\n        return \"--- a/x.java\\n+++ b/x.java\\n@@ -1,1 +1,2 @@\\n a\\n+b\\n\"\n\n    async def f_run(diff, md):\n        blocking = Finding(rule=\"BUG\", file=\"x.java\", line=2, severity=\"error\",\n                           note=\"violates the cap rule\")\n        blocking.knowledge_ref = [\"PR41-I1\"]\n        advisory = Finding(rule=\"STYLE\", file=\"x.java\", line=2, severity=\"info\",\n                           note=\"nit\")\n        advisory.knowledge_ref = [\"PR41-I2\"]        # info \u4e0d\u7b97\u77db\u76fe\n        return types.SimpleNamespace(\n            markdown=\"## Pull Request Review OK\", findings=[blocking, advisory],\n            stats={\"file_table\": [{\"path\": \"x.java\"}], \"graph_impacted\": []})\n\n    async def f_distill(*a, **k):\n        captured.update(k)\n        captured[\"files\"] = a[2]\n\n    monkeypatch.setattr(A.clients, \"fetch_pr_metadata\", f_meta)\n    monkeypatch.setattr(A.clients, \"fetch_pr_diff\", f_diff)\n    monkeypatch.setattr(A, \"run_review\", f_run)\n    monkeypatch.setattr(A.knowledge, \"distill_and_stage\", f_distill)\n    monkeypatch.setenv(\"AUTO_POST\", \"false\")\n\n    async def go():\n        await A.handle_review(\"https://x/C/P/_git/R/pullrequest/9\", \"u\")\n        await asyncio.sleep(0)          # \u8b93 _bg \u6392\u7684\u90a3\u689d\u771f\u7684\u8dd1\u5230\n\n    asyncio.run(go())\n    assert captured[\"finding_ids\"] == {\"F1\", \"F2\"}\n    assert captured[\"finding_files\"] == [\"x.java\", \"x.java\"]\n    assert captured[\"diff\"].startswith(\"--- a/x.java\")\n    assert captured[\"contradicted\"] == {\"PR41-I1\"}    # \u53ea\u6709 error/warning \u7b97\n"}
{"path":"tests/test_doctor.py","perm":"0644","sha":"9969d229aac805bb6e9ac1649d663c9466308fa4ff2ffdd96677185b80c94048","data":"\"\"\"shared.doctor \u7684\u9396\uff1a\u5168\u90e8\u96e2\u7dda \u2014\u2014 \u7db2\u8def\u3001PATH\u3001subprocess \u63a2\u91dd\u4e00\u5f8b stub\u3002\"\"\"\nimport pytest\n\nimport shared.doctor as D\nimport shared.settings as S\n\n\ndef _by(checks, group, name=None):\n    hits = [c for c in checks if c.group == group and (name is None or c.name == name)]\n    assert hits, f\"no check {group}/{name}: {[(c.group, c.name) for c in checks]}\"\n    return hits[0] if name else hits\n\n\n@pytest.fixture\ndef offline(monkeypatch):\n    \"\"\"\u9810\u8a2d\u4e00\u5207\u90fd\u901a\uff1b\u500b\u5225\u6e2c\u8a66\u518d\u628a\u67d0\u500b\u63a2\u91dd\u5f04\u58de\u3002\"\"\"\n    monkeypatch.setattr(D, \"_tcp_open\", lambda host, port, timeout=0: True)\n    monkeypatch.setattr(D, \"_which\", lambda b: f\"/venv/bin/{b}\" if b in (\"semgrep\", \"ruff\") else None)\n    monkeypatch.setattr(D, \"_run\", lambda cmd, timeout=0: (0, \"1.2.3\"))\n\n    def http(url, **kw):\n        if url.endswith(\"/healthz\"):\n            return 200, {\"ok\": True, \"pipeline\": \"v2\", \"jobs\": {\n                \"repo-sync\": {\"enabled\": True, \"interval_min\": 10, \"running\": False,\n                              \"last_ok\": True, \"last_end\": 1e12, \"last_detail\": [\"a -> 1\", \"b -> 2\"]},\n                \"harvest\": {\"enabled\": False},\n            }}, \"\"\n        if url.endswith(\"/api/public/health\"):\n            return 200, {\"status\": \"OK\"}, \"\"\n        if url.endswith(\"/api/public/projects\"):\n            return 200, {\"data\": [{\"name\": \"pr-review\"}]}, \"\"\n        if url.endswith(\"/models\"):\n            return 200, {\"data\": [{\"id\": \"gpt-4o-mini\"}, {\"id\": \"big\"}]}, \"\"\n        return 404, \"\", \"\"\n    monkeypatch.setattr(D, \"_http_get\", http)\n    for _g, _c, _f, info in S.iter_fields():\n        for n in S.env_names(info):\n            monkeypatch.delenv(n, raising=False)\n    monkeypatch.setenv(\"ADO_PAT\", \"x\" * 52)\n    monkeypatch.setenv(\"LANGFUSE_PUBLIC_KEY\", \"pk\")\n    monkeypatch.setenv(\"LANGFUSE_SECRET_KEY\", \"sk\")\n    return http\n\n\ndef test_all_green_exit_0(offline):\n    checks, code = D.run()\n    assert code == 0\n    assert not [c for c in checks if c.status == D.FAIL]\n    assert _by(checks, \"services\", \"orchestrator\").status == D.OK\n    assert _by(checks, \"llm\", \"LLM_MODEL\").status == D.OK\n    assert _by(checks, \"ado\", \"reach\").status == D.SKIP            # \u6c92\u7d66 --pr-url\n    assert _by(checks, \"paths\", \"KNOWLEDGE_ROOT\").status == D.SKIP  # \u672a\u8a2d = \u505c\u7528\n\n\ndef test_bad_settings_exit_2_and_nothing_else_runs(offline, monkeypatch):\n    monkeypatch.setenv(\"REVIEW_MIN_CONFIDENCE\", \"9\")\n    checks, code = D.run()\n    assert code == 2 and len(checks) == 1\n    assert checks[0].status == D.FAIL and \"REVIEW_MIN_CONFIDENCE\" in checks[0].detail\n\n\ndef test_orchestrator_down_fails_and_jobs_come_from_healthz(offline, monkeypatch):\n    checks, code = D.run()\n    assert _by(checks, \"jobs\", \"repo-sync\").status == D.OK\n    assert \"2 \u9805\" in _by(checks, \"jobs\", \"repo-sync\").detail\n    assert _by(checks, \"jobs\", \"harvest\").status == D.SKIP\n    assert not [c for c in checks if c.group == \"services\" and \"\u2460\" in c.name]\n\n    def http(url, **kw):\n        if url.endswith(\"/healthz\"):\n            return None, None, \"ConnectError\"\n        return offline(url, **kw)\n    monkeypatch.setattr(D, \"_http_get\", http)\n    checks, code = D.run()\n    assert code == 1\n    assert _by(checks, \"services\", \"orchestrator\").status == D.FAIL\n    assert not [c for c in checks if c.group == \"jobs\"]\n\n\ndef test_failed_job_is_a_fail(offline, monkeypatch):\n    def http(url, **kw):\n        if url.endswith(\"/healthz\"):\n            return 200, {\"ok\": True, \"jobs\": {\"harvest\": {\n                \"enabled\": True, \"interval_min\": 30, \"running\": False,\n                \"last_ok\": False, \"last_error\": \"RuntimeError: git lock\"}}}, \"\"\n        return offline(url, **kw)\n    monkeypatch.setattr(D, \"_http_get\", http)\n    checks, code = D.run()\n    assert code == 1 and \"git lock\" in _by(checks, \"jobs\", \"harvest\").detail\n\n\ndef test_model_not_served_by_gateway_fails(offline, monkeypatch):\n    monkeypatch.setenv(\"LLM_MODEL\", \"nope\")\n    monkeypatch.setenv(\"LLM_MODEL_ADVERSARY\", \"big\")\n    checks, code = D.run()\n    assert code == 1\n    assert _by(checks, \"llm\", \"LLM_MODEL\").status == D.FAIL\n    assert _by(checks, \"llm\", \"LLM_MODEL_ADVERSARY\").status == D.OK\n\n\ndef test_gateway_without_models_endpoint_is_a_warning(offline, monkeypatch):\n    def http(url, **kw):\n        if url.endswith(\"/models\"):\n            return 404, \"\", \"\"\n        return offline(url, **kw)\n    monkeypatch.setattr(D, \"_http_get\", http)\n    checks, code = D.run()\n    assert code == 0\n    assert _by(checks, \"llm\", \"gateway\").status == D.WARN\n\n\ndef test_langfuse_bad_keys_fail(offline, monkeypatch):\n    def http(url, **kw):\n        if url.endswith(\"/api/public/projects\"):\n            return 401, {\"message\": \"unauthorized\"}, \"\"\n        return offline(url, **kw)\n    monkeypatch.setattr(D, \"_http_get\", http)\n    checks, code = D.run()\n    assert code == 1 and _by(checks, \"langfuse\", \"keys\").status == D.FAIL\n\n\ndef test_paths_report_missing_vs_present(offline, tmp_path, monkeypatch):\n    monkeypatch.setenv(\"REPOS_ROOT\", str(tmp_path / \"missing\"))\n    monkeypatch.setenv(\"RULES_ROOT\", str(tmp_path))                  # \u5b58\u5728\u4f46\u6c92\u6709 rules/common\n    kroot = tmp_path / \"k\"; (kroot / \"_pending\" / \"repo-a\").mkdir(parents=True)\n    (kroot / \"_pending\" / \"repo-a\" / \"pr-1.json\").write_text(\"{}\", encoding=\"utf-8\")\n    (kroot / \"repo-a\").mkdir(); (kroot / \"repo-a\" / \"Fee.md\").write_text(\"# x\", encoding=\"utf-8\")\n    monkeypatch.setenv(\"KNOWLEDGE_ROOT\", str(kroot))\n    checks, code = D.run()\n    assert _by(checks, \"paths\", \"REPOS_ROOT\").status == D.FAIL\n    rules = _by(checks, \"paths\", \"RULES_ROOT\")\n    assert rules.status == D.WARN and \"\u5c0d\u4e0d\u4e0a\" in rules.detail\n    k = _by(checks, \"paths\", \"KNOWLEDGE_ROOT\")\n    assert \"1 page(s), 1 pending\" in k.detail\n    assert code == 1\n\n\ndef test_no_network_skips_probes_and_missing_pat_still_fails(offline, monkeypatch):\n    monkeypatch.delenv(\"ADO_PAT\")\n    checks, code = D.run(network=False)\n    assert _by(checks, \"services\", \"all\").status == D.SKIP\n    assert _by(checks, \"langfuse\", \"all\").status == D.SKIP\n    assert _by(checks, \"llm\", \"all\").status == D.SKIP\n    assert _by(checks, \"ado\", \"ADO_PAT\").status == D.FAIL and code == 1\n\n\ndef test_missing_semgrep_warns_unless_switched_off(offline, monkeypatch):\n    monkeypatch.setattr(D, \"_which\", lambda b: None)\n    checks, _ = D.run(network=False)\n    assert _by(checks, \"python\", \"semgrep\").status == D.WARN\n    assert _by(checks, \"systemd\", \"all\").status == D.SKIP        # \u6c92 systemctl\n    monkeypatch.setenv(\"STATIC_SEMGREP\", \"off\")\n    checks, _ = D.run(network=False)\n    assert _by(checks, \"python\", \"semgrep\").status == D.SKIP\n\n\ndef test_pr_url_probe_reports_title(offline, monkeypatch):\n    import shared.azdo as A\n    import contextlib\n    monkeypatch.setattr(A, \"client\", lambda: contextlib.nullcontext(object()))\n    monkeypatch.setattr(A, \"get_json\", lambda c, url, **p: {\"title\": \"Fix TTL\", \"status\": \"active\"})\n    checks, code = D.run(pr_url=\"https://dev.azure.com/o/p/_git/R/pullrequest/42\")\n    r = _by(checks, \"ado\", \"reach\")\n    assert r.status == D.OK and \"Fix TTL\" in r.detail and code == 0\n\n\ndef test_render_and_json_shapes(offline):\n    checks, code = D.run()\n    text = D.render(checks)\n    assert \"[services]\" in text and \"OK \" in text and text.rstrip().endswith(\"SKIP \" + str(\n        sum(1 for c in checks if c.status == D.SKIP)))\n    import json\n    from dataclasses import asdict\n    payload = json.loads(json.dumps([asdict(c) for c in checks], ensure_ascii=False))\n    assert {\"group\", \"name\", \"status\", \"detail\"} <= set(payload[0])\n"}
{"path":"tests/test_jobs_adapters.py","perm":"0644","sha":"2ccdee1a9d063387689188d4cb699d6d9ebc37cc974ab566a27b0d6731dc34b1","data":"\"\"\"S1 \u7684\u9396\uff1a\u2460\u2462 \u4f75\u5165\u884c\u7a0b\u5f8c\u884c\u70ba\u4e0d\u8b8a\uff1b\u6392\u7a0b\u8ff4\u5708\u7684\u72c0\u614b\u6a5f\u6b63\u78ba\u3002\u5168\u96e2\u7dda\u3002\"\"\"\nimport asyncio\nimport contextlib\nimport subprocess\n\nimport orchestrator.jobs as J\nfrom orchestrator.adapters import ado\n\n\n# ---------- adapters/ado\uff1a\u5beb\u5165\u7684\u96d9\u958b\u95dc\u8207\u7a3d\u6838 ----------\n\ndef test_review_post_respects_dry_run_and_audits(monkeypatch):\n    monkeypatch.setenv(\"DRY_RUN\", \"true\")\n    ado.audit_log.clear()\n    url = \"https://x/C/P/_git/repo-a/pullrequest/5\"\n    out = ado.post_review_comment(url, \"# review\")\n    assert out[\"dry_run\"] is True and out[\"posted\"] is False\n    assert out[\"would_post_to\"].endswith(\"/pullRequests/5/threads\")\n    assert out[\"preview\"].startswith(ado.MARKER)\n    assert ado.audit_log[-1][\"kind\"] == \"review\" and ado.audit_log[-1][\"posted\"] is False\n\n\ndef test_review_post_really_posts_when_dry_run_off(monkeypatch):\n    monkeypatch.setenv(\"DRY_RUN\", \"false\")\n    monkeypatch.setenv(\"ADO_PAT\", \"pat\")\n    posted = {}\n\n    class _Resp:\n        def raise_for_status(self): pass\n        def json(self): return {\"id\": 77}\n\n    class _Client:\n        def post(self, url, params=None, json=None):\n            posted[\"url\"], posted[\"json\"] = url, json\n            return _Resp()\n    monkeypatch.setattr(ado, \"client\", lambda: contextlib.nullcontext(_Client()))\n    out = ado.post_review_comment(\"https://x/C/P/_git/R/pullrequest/9\", \"body\")\n    assert out == {\"posted\": True, \"dry_run\": False, \"thread_id\": 77}\n    assert posted[\"url\"].endswith(\"/pullRequests/9/threads\")\n    assert posted[\"json\"][\"comments\"][0][\"content\"].startswith(ado.MARKER)\n    assert ado.audit_log[-1][\"posted\"] is True\n\n\ndef test_clients_wrappers_keep_their_names_for_callers():\n    \"\"\"pipeline / knowledge / app \u8207\u65e2\u6709\u6e2c\u8a66\u90fd monkeypatch \u9019\u5e7e\u500b\u540d\u5b57\u2014\u2014\u7c3d\u540d\u4e0d\u80fd\u52d5\u3002\"\"\"\n    import inspect\n    from orchestrator import clients\n    for name in (\"fetch_pr_metadata\", \"fetch_pr_diff\", \"post_review_comment\",\n                 \"post_knowledge_draft\", \"graph_blast\", \"graph_call\"):\n        assert inspect.iscoroutinefunction(getattr(clients, name)), name\n    assert list(inspect.signature(clients.post_knowledge_draft).parameters) == \\\n        [\"pr_url\", \"markdown\", \"thread_id\"]\n\n\n# ---------- jobs\uff1arepo-sync \u771f\u7684\u5c0d git \u52d5\u624b ----------\n\ndef _git(*args, cwd):\n    subprocess.run([\"git\", *args], cwd=str(cwd), check=True, capture_output=True,\n                   env={**__import__(\"os\").environ, \"GIT_AUTHOR_NAME\": \"t\", \"GIT_AUTHOR_EMAIL\": \"t@x\",\n                        \"GIT_COMMITTER_NAME\": \"t\", \"GIT_COMMITTER_EMAIL\": \"t@x\"})\n\n\ndef test_repo_sync_pulls_fast_forward_and_reports_each_clone(tmp_path, monkeypatch):\n    upstream = tmp_path / \"up\"; upstream.mkdir()\n    _git(\"init\", \"-q\", \"-b\", \"main\", cwd=upstream)\n    (upstream / \"a.txt\").write_text(\"1\", encoding=\"utf-8\")\n    _git(\"add\", \"a.txt\", cwd=upstream); _git(\"commit\", \"-qm\", \"one\", cwd=upstream)\n    repos = tmp_path / \"repos\"; repos.mkdir()\n    _git(\"clone\", \"-q\", str(upstream), str(repos / \"svc\"), cwd=tmp_path)\n    (repos / \"notgit\").mkdir()\n    (upstream / \"a.txt\").write_text(\"2\", encoding=\"utf-8\")\n    _git(\"commit\", \"-qam\", \"two\", cwd=upstream)\n    monkeypatch.setenv(\"REPOS_ROOT\", str(repos))\n    monkeypatch.setenv(\"REPO_SYNC_GRAPH_REBUILD\", \"off\")\n    lines = J.repo_sync_once()\n    assert len(lines) == 1 and lines[0].startswith(\"svc -> \")\n    assert (repos / \"svc\" / \"a.txt\").read_text(encoding=\"utf-8\") == \"2\"\n\n\ndef test_repo_sync_without_root_is_a_noop_message(monkeypatch):\n    monkeypatch.delenv(\"REPOS_ROOT\", raising=False)\n    assert \"\u7121\u4e8b\u53ef\u505a\" in J.repo_sync_once()[0]\n\n\n# ---------- jobs\uff1a\u6392\u7a0b\u72c0\u614b\u6a5f ----------\n\ndef test_run_once_records_success_failure_and_refuses_overlap(monkeypatch):\n    calls = []\n    monkeypatch.setitem(J.JOBS, \"repo-sync\", lambda: calls.append(1) or [\"x -> 1\"])\n    monkeypatch.setitem(J.JOBS, \"harvest\", lambda: (_ for _ in ()).throw(RuntimeError(\"git lock\")))\n\n    async def go():\n        J._STATE.clear()\n        a = await J.run_once(\"repo-sync\")\n        b = await J.run_once(\"harvest\")\n        return a, b\n    a, b = asyncio.run(go())\n    assert a.last_ok is True and a.last_detail == [\"x -> 1\"] and a.runs == 1\n    assert b.last_ok is False and \"git lock\" in b.last_error and b.runs == 1\n    snap = J.snapshot()\n    assert snap[\"harvest\"][\"last_error\"].startswith(\"RuntimeError\")\n\n    async def overlap():\n        st = J._STATE[\"repo-sync\"]\n        st.running = True\n        return await J.run_once(\"repo-sync\")\n    assert asyncio.run(overlap()).runs == 1          # \u6b63\u5728\u8dd1 \u2192 \u4e0d\u518d\u958b\u7b2c\u4e8c\u8f2a\n    assert calls == [1]\n\n\ndef test_start_schedules_only_jobs_whose_root_is_set(tmp_path, monkeypatch):\n    monkeypatch.setenv(\"REPOS_ROOT\", str(tmp_path))\n    monkeypatch.delenv(\"KNOWLEDGE_ROOT\", raising=False)\n    monkeypatch.setenv(\"REPO_SYNC_INTERVAL_MIN\", \"5\")\n\n    async def go():\n        sts = J.start(first_delay_s=3600)\n        try:\n            return {s.name: s.enabled for s in sts}, len(J._TASKS)\n        finally:\n            J.stop()\n    enabled, n_tasks = asyncio.run(go())\n    assert enabled == {\"repo-sync\": True, \"harvest\": False}\n    assert n_tasks == 2                      # \u95dc\u8457\u7684\u4e5f\u6709\u8ff4\u5708\uff08\u6bcf\u5206\u9418\u770b\u8a2d\u5b9a\uff09\uff0c\u53ea\u662f\u4e0d\u8dd1\n    assert J.snapshot()[\"repo-sync\"][\"next_run\"] is not None\n    assert J.snapshot()[\"harvest\"][\"next_run\"] is None\n\n\ndef test_zero_interval_disables_job(tmp_path, monkeypatch):\n    monkeypatch.setenv(\"REPOS_ROOT\", str(tmp_path))\n    monkeypatch.setenv(\"REPO_SYNC_INTERVAL_MIN\", \"0\")\n\n    async def go():\n        try:\n            return {s.name: s.enabled for s in J.start(first_delay_s=3600)}\n        finally:\n            J.stop()\n    assert asyncio.run(go())[\"repo-sync\"] is False\n\n\ndef test_cli_rejects_unknown_job(capsys):\n    assert J._main([\"nope\"]) == 2\n    assert \"\u7528\u6cd5\" in capsys.readouterr().err\n"}
{"path":"tests/test_ledger_setup.py","perm":"0644","sha":"2d6d3574f8a0a30a1007bb704f881b79b1b0226f5bb212579dabb9d3a766e4b6","data":"\"\"\"S4 \u7684\u9396\uff1a\u63a7\u5236\u53f0\u88c1\u6c7a\u8207 PR \u7559\u8a00\u540c\u7fa9\u4e14\u6536\u53e3\u6642\u7528\u6389\uff1bKnowledge / Setup \u9801\uff1binstall \u51aa\u7b49\u3002\u5168\u96e2\u7dda\u3002\"\"\"\nimport json\nfrom pathlib import Path\n\nimport pytest\nfrom fastapi.testclient import TestClient\n\nimport orchestrator.ledger as L\nimport shared.doctor as D\n\n\ndef _seed_knowledge(root: Path) -> None:\n    (root / \"repo-a\" / \"a\").mkdir(parents=True)\n    (root / \"repo-a\" / \"a\" / \"Fee.md\").write_text(\n        \"# Fee\\n> entity: a/Fee.java\\n\\n## Invariants\\n- fee in cents `PR1-I1`\\n\", encoding=\"utf-8\")\n    (root / \"_pending\" / \"repo-a\").mkdir(parents=True)\n    (root / \"_pending\" / \"repo-a\" / \"pr-5.json\").write_text(json.dumps({\n        \"pr_url\": \"https://x/C/P/_git/repo-a/pullrequest/5\", \"pr_id\": 5, \"repo\": \"repo-a\",\n        \"target_branch\": \"release/1\", \"base_url\": \"https://x/C/P\", \"posted\": False, \"dry_run\": True,\n        \"created\": \"2026-11-06T01:00:00\", \"contradicted\": [\"PR1-I1\"],\n        \"draft\": {\"primary_entity\": \"a/Fee.java\", \"ledger_line\": \"rounds half-even\",\n                  \"decisions\": [{\"what\": \"use HALF_EVEN\", \"why\": \"spec\", \"evidence\": [\"F1\"]}],\n                  \"invariants\": [\"fee rounding is half-even\"]}}), encoding=\"utf-8\")\n    (root / \"_cycle\" / \"repo-a\").mkdir(parents=True)\n    (root / \"_cycle\" / \"repo-a\" / \"pr-6.json\").write_text(json.dumps({\n        \"pr_url\": \"https://x/C/P/_git/repo-a/pullrequest/6\", \"pr_id\": 6, \"repo\": \"repo-a\",\n        \"target_branch\": \"release/1\", \"base_url\": \"https://x/C/P\", \"provenance\": \"silent\",\n        \"contradicted\": [\"PR1-I1\"],\n        \"draft\": {\"primary_entity\": \"a/Tax.java\", \"ledger_line\": \"tax is exclusive\",\n                  \"decisions\": [{\"what\": \"exclusive tax\", \"why\": \"law\", \"evidence\": [\"PR\"]}],\n                  \"invariants\": [\"tax never negative\"]}}), encoding=\"utf-8\")\n    (root / \"_state\").mkdir()\n    (root / \"_state\" / \"cycle.json\").write_text(json.dumps({\"repo-a#99\": {\"listed\": [\"PR6\"], \"digest\": True}}),\n                                               encoding=\"utf-8\")\n\n\n@pytest.fixture\ndef kroot(tmp_path, monkeypatch):\n    root = tmp_path / \"know\"; root.mkdir()\n    _seed_knowledge(root)\n    monkeypatch.setenv(\"KNOWLEDGE_ROOT\", str(root))\n    return root\n\n\n# ---------- ledger ----------\n\ndef test_ledger_reads_pending_staged_cycle_and_renders_digest(kroot):\n    p = L.pending()\n    assert len(p) == 1 and p[0][\"pr_id\"] == 5 and p[0][\"dry_run\"] and p[0][\"contradicted\"] == [\"PR1-I1\"]\n    assert p[0][\"draft\"][\"decisions\"][0][\"id\"] == \"PR5-D1\" and p[0][\"draft\"][\"invariants\"][0][\"id\"] == \"PR5-I1\"\n    s = L.staged()\n    assert len(s) == 1 and s[0][\"pr_id\"] == 6 and s[0][\"provenance\"] == \"silent\"\n    assert list(L.cycle_state()) == [\"repo-a#99\"]\n    d = L.digest_preview(\"repo-a\")\n    assert \"PR#6\" in d and \"PR6-I1\" in d and \"`keep PR1-I1`\" in d\n    assert L.digest_preview(\"nope\") == \"\"\n\n\ndef test_verdicts_add_remove_peek_consume(kroot):\n    assert \"\u5df2\u8a18\u9304\" in L.add_verdict(\"Repo-A\", \"reject\", \"PR6-I1\", by=\"me\")\n    assert \"\u5df2\u8a18\u9304\" in L.add_verdict(\"repo-a\", \"keep\", \"PR1-I1\")\n    assert \"\u50c5\u63a5\u53d7\u689d\u76ee ID\" in L.add_verdict(\"repo-a\", \"keep\", \"Fee\")\n    assert \"\u7f3a\u5c11\" in L.add_verdict(\"repo-a\", \"nuke\", \"x\")\n    v = L.verdicts()\n    assert set(v[\"repo-a\"][\"reject\"]) == {\"PR6-I1\"} and set(v[\"repo-a\"][\"keep\"]) == {\"PR1-I1\"}\n    assert L.peek_verdicts(kroot, \"repo-a\") == ({\"pr6-i1\"}, {\"PR1-I1\"})\n    assert L.verdicts()[\"repo-a\"][\"reject\"]                      # peek \u4e0d\u6e05\n    assert \"\u5df2\u64a4\u56de\" in L.remove_verdict(\"repo-a\", \"keep\", \"PR1-I1\")\n    assert \"\u7121\u6b64\u88c1\u6c7a\" in L.remove_verdict(\"repo-a\", \"keep\", \"PR1-I1\")\n    assert L.consume_verdicts(kroot, \"repo-a\") == ({\"pr6-i1\"}, set())\n    assert L.consume_verdicts(kroot, \"repo-a\") == (set(), set())   # \u7528\u6389\u4e86\n\n\ndef test_harvester_applies_console_verdicts_at_cycle_close(kroot, monkeypatch):\n    \"\"\"\u63a7\u5236\u53f0 reject PR6-I1 + keep PR1-I1\uff1a\u6536\u53e3\u5f8c Tax \u9801\u6c92\u6709\u90a3\u689d\u4e0d\u8b8a\u5f0f\u3001Fee \u7684 PR1-I1 \u6c92\u88ab\u756b\u6389\u3002\"\"\"\n    from orchestrator import knowledge_harvest as H\n    monkeypatch.setenv(\"KNOWLEDGE_CYCLE_SOURCE\", \"release/*\")\n    monkeypatch.setenv(\"KNOWLEDGE_CYCLE_TARGET\", \"master\")\n    monkeypatch.setenv(\"KNOWLEDGE_DIGEST_LLM\", \"false\")\n    (kroot / \"_state\" / \"repos.json\").write_text(json.dumps({\"repo-a\": \"https://x/C/P\"}), encoding=\"utf-8\")\n    (kroot / \"_state\" / \"cycle.json\").write_text(json.dumps({\"repo-a#1\": {\"closed\": True}}), encoding=\"utf-8\")\n    L.add_verdict(\"repo-a\", \"reject\", \"PR6-I1\")\n    L.add_verdict(\"repo-a\", \"keep\", \"PR1-I1\")\n    monkeypatch.setattr(H, \"_list_active\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_list_completed\", lambda c, r: [{\n        \"pullRequestId\": 99, \"sourceRefName\": \"refs/heads/release/1\", \"targetRefName\": \"refs/heads/master\"}])\n    monkeypatch.setattr(H, \"_get_threads\", lambda c, r: [])\n    monkeypatch.setattr(H, \"_post_thread\", lambda c, r, t: None)\n    monkeypatch.setattr(H, \"_git\", lambda root, *a: None)\n    lines = H._cycle_close(object(), kroot)\n    assert any(\"\u6536\u53e3\" in ln for ln in lines)\n    tax = (kroot / \"repo-a\" / \"a\" / \"Tax.md\").read_text(encoding=\"utf-8\")\n    assert \"PR6-D1\" in tax and \"tax never negative\" not in tax        # reject \u90a3\u4e00\u884c\u6c92\u843d\u5730\uff08History \u6703\u8a18 rejected\uff09\n    fee = (kroot / \"repo-a\" / \"a\" / \"Fee.md\").read_text(encoding=\"utf-8\")\n    assert \"~~\" not in fee                                           # keep \u5426\u6c7a\u4e86\u62d4\u9664\n    assert L.verdicts().get(\"repo-a\") in (None, {}) or not any(L.verdicts()[\"repo-a\"].values())\n\n\n# ---------- console pages ----------\n\n@pytest.fixture\ndef client(kroot, monkeypatch, tmp_path):\n    monkeypatch.setenv(\"ADO_PAT\", \"pat\")\n    monkeypatch.setattr(D, \"_tcp_open\", lambda h, p, timeout=0: True)\n    monkeypatch.setattr(D, \"_http_get\", lambda url, **kw: (200, {\"ok\": True, \"jobs\": {}}, \"\"))\n    monkeypatch.setattr(D, \"_which\", lambda b: None)\n    monkeypatch.setattr(D, \"_run\", lambda cmd, timeout=0: (0, \"\"))\n    import orchestrator.app as A\n    import orchestrator.console.router as R\n    R._doctor_cache.update(ts=0.0, checks=[])\n    with TestClient(A.app) as c:\n        yield c\n\n\ndef test_knowledge_page_lists_and_records_verdicts(client):\n    r = client.get(\"/console/knowledge\")\n    assert r.status_code == 200 and \"repo-a#5\" in r.text and \"repo-a#6\" in r.text\n    assert \"keep PR1-I1\" in r.text and \"repo-a#99\" in r.text\n    r = client.post(\"/console/knowledge/verdict\", data={\"repo\": \"repo-a\", \"kind\": \"reject\", \"token\": \"PR6\"},\n                    follow_redirects=True)\n    assert \"\u5df2\u8a18\u9304\" in r.text and \"<code>PR6</code>\" in r.text\n    r = client.post(\"/console/knowledge/verdict/remove\", data={\"repo\": \"repo-a\", \"kind\": \"reject\", \"token\": \"PR6\"},\n                    follow_redirects=True)\n    assert \"\u5df2\u64a4\u56de\" in r.text\n    r = client.get(\"/console/knowledge\", params={\"digest_repo\": \"repo-a\"})\n    assert \"Knowledge cycle digest\" in r.text\n\n\ndef test_setup_page_groups_doctor_checks_into_steps(client):\n    r = client.get(\"/console/setup\")\n    assert r.status_code == 200\n    for title in (\"LLM gateway\", \"Langfuse\", \"Azure DevOps\", \"Orchestrator \u670d\u52d9\", \"\u672c\u5730 clone\", \"\u5718\u968a\u898f\u5247\", \"\u77e5\u8b58\u8ff4\u5708\"):\n        assert title in r.text\n    assert \"REPOS_ROOT\" in r.text and \"/console/settings#g-llm\" in r.text\n\n\ndef test_overview_points_to_setup_when_failing(client, monkeypatch):\n    monkeypatch.setattr(D, \"_http_get\", lambda url, **kw: (None, None, \"down\"))\n    import orchestrator.console.router as R\n    R._doctor_cache.update(ts=0.0, checks=[])\n    r = client.get(\"/console?refresh=1\")\n    assert \"\u8a2d\u5b9a\u7cbe\u9748\" in r.text and \"\u670d\u52d9\u4e0d\u53ef\u7528\" in r.text and \"BLOCKING\" in r.text\n\n\n# ---------- install ----------\n\ndef test_install_is_idempotent_and_writes_unit(tmp_path, monkeypatch, capsys):\n    from shared import install\n    cfg, data, unit = tmp_path / \"etc\", tmp_path / \"var\", tmp_path / \"unit.service\"\n    args = [\"--config-dir\", str(cfg), \"--data-dir\", str(data), \"--unit-path\", str(unit),\n            \"--prefix\", \"/opt/x\", \"--user\", \"svc\"]\n    assert install.main([*args, \"--dry-run\"]) == 0\n    assert not cfg.exists() and not unit.exists()\n    assert install.main(args) == 0\n    assert (cfg / \"config.toml\").exists() and (cfg / \"secrets.env\").exists() and data.is_dir()\n    u = unit.read_text(encoding=\"utf-8\")\n    assert \"User=svc\" in u and \"/opt/x/venv/bin/uvicorn\" in u and f\"CONFIG_DIR={cfg.as_posix()}\" in u\n    (cfg / \"secrets.env\").write_text(\"ADO_PAT=keepme\\n\", encoding=\"utf-8\")\n    assert install.main(args) == 0\n    assert \"keepme\" in (cfg / \"secrets.env\").read_text(encoding=\"utf-8\")       # \u4e0d\u8986\u5beb\n    out = capsys.readouterr().out\n    assert \"\u4fdd\u7559\u65e2\u6709\" in out and \"[settings]\" in out                            # \u672b\u5c3e\u8dd1\u4e86 doctor\n"}
{"path":"tests/test_settings.py","perm":"0644","sha":"1bd17116bcb23f98bbac9731e7c41adcf6c2af40fd7df1a7ef1483d4be42f2a1","data":"\"\"\"shared.settings \u7684\u9396\uff1a\u8b8a\u6578\u540d\u4e0d\u8b8a\u3001\u7a7a\u5b57\u4e32=\u672a\u8a2d\u3001\u58de\u503c\u5c31\u70b8\u3001example \u53ef\u5f80\u8fd4\u3002\"\"\"\n\nimport pytest\nfrom pydantic import ValidationError\n\nimport shared.settings as S\n\n\ndef _clear_all(monkeypatch):\n    for _g, _c, _f, info in S.iter_fields():\n        for n in S.env_names(info):\n            monkeypatch.delenv(n, raising=False)\n\n\ndef test_defaults_match_legacy_code(monkeypatch):\n    _clear_all(monkeypatch)\n    s = S.settings()\n    assert s.orchestrator.pipeline == \"v1\"\n    assert s.review.max_findings == 30 and s.review.min_confidence == 0.55\n    assert s.knowledge.branches == [\"master\", \"main\"]\n    assert s.posting.dry_run is True and s.posting.knowledge_post is False\n    assert s.jobs.repo_sync_interval_min == 10 and s.jobs.harvest_interval_min == 30\n    assert s.ado.verify_ssl is True\n    assert s.static.semgrep == \"auto\"\n    assert s.knowledge.enabled is False and s.graph.enabled is False\n    assert s.rules.enabled is False\n\n\ndef test_env_override_and_reset(monkeypatch):\n    monkeypatch.setenv(\"REVIEW_MAX_FINDINGS\", \"2\")\n    assert S.settings().review.max_findings == 2\n    monkeypatch.setenv(\"REVIEW_MAX_FINDINGS\", \"5\")      # conftest \u7d81\u4e86 reset()\n    assert S.settings().review.max_findings == 5\n\n\ndef test_blank_string_means_unset(monkeypatch):\n    monkeypatch.setenv(\"KNOWLEDGE_ROOT\", \"\")\n    monkeypatch.setenv(\"EVAL_MAX_NOISE\", \"\")\n    monkeypatch.setenv(\"REVIEW_MAX_FINDINGS\", \"\")\n    s = S.settings()\n    assert s.knowledge.root is None and s.knowledge.enabled is False\n    assert s.eval.max_noise is None\n    assert s.review.max_findings == 30\n\n\ndef test_bad_value_fails_loud(monkeypatch):\n    monkeypatch.setenv(\"REVIEW_MAX_FINDINGS\", \"abc\")\n    with pytest.raises(ValidationError):\n        S.settings()\n    monkeypatch.setenv(\"REVIEW_MAX_FINDINGS\", \"30\")\n    monkeypatch.setenv(\"REVIEW_PIPELINE\", \"v3\")\n    with pytest.raises(ValidationError):\n        S.settings()\n\n\ndef test_tri_state_and_switch_parsing(monkeypatch):\n    monkeypatch.setenv(\"ADO_VERIFY_SSL\", \"/etc/ssl/certs/ca.crt\")\n    monkeypatch.setenv(\"STATIC_SEMGREP\", \"false\")\n    monkeypatch.setenv(\"STATIC_RUFF\", \"YES\")\n    monkeypatch.setenv(\"REVIEW_PIPELINE\", \" V2 \")\n    monkeypatch.setenv(\"KNOWLEDGE_BRANCHES\", \" master , release/* ,\")\n    s = S.settings()\n    assert s.ado.verify_ssl == \"/etc/ssl/certs/ca.crt\"\n    assert s.static.semgrep == \"off\" and s.static.semgrep_enabled is False\n    assert s.static.ruff == \"on\"\n    assert s.orchestrator.pipeline == \"v2\"\n    assert s.knowledge.branches == [\"master\", \"release/*\"]\n    monkeypatch.setenv(\"ADO_VERIFY_SSL\", \"0\")\n    assert S.settings().ado.verify_ssl is False\n\n\ndef test_retired_tool_names_are_flagged_not_honoured(monkeypatch):\n    _clear_all(monkeypatch)\n    monkeypatch.setenv(\"ADO_TOOLS_PORT\", \"8094\")\n    monkeypatch.setenv(\"REPO_ROOT\", \"/srv/x\")\n    s = S.settings()                                        # \u4e0d\u5f97 raise\u3001\u4e0d\u5f97\u6709\u8a72\u6b04\u4f4d\n    assert not hasattr(s, \"tools\")\n    w = \"\\n\".join(S.warnings_for(s))\n    assert \"ADO_TOOLS_PORT\" in w and \"REPO_ROOT\" in w and \"\u5df2\u7121\u4f5c\u7528\" in w\n\n\ndef test_enabled_flags_follow_directories(tmp_path, monkeypatch):\n    monkeypatch.setenv(\"KNOWLEDGE_ROOT\", str(tmp_path / \"nope\"))\n    assert S.settings().knowledge.enabled is False\n    monkeypatch.setenv(\"KNOWLEDGE_ROOT\", str(tmp_path))\n    assert S.settings().knowledge.enabled is True\n    monkeypatch.setenv(\"GRAPH_TOOLS_URL\", \"http://127.0.0.1:8097/mcp\")\n    assert S.settings().graph.enabled is False               # \u5c11 GRAPH_TOOL_BLAST\n    monkeypatch.setenv(\"GRAPH_TOOL_BLAST\", \"get_impact_radius_tool\")\n    assert S.settings().graph.enabled is True\n    (tmp_path / \"myrepo\").mkdir()\n    monkeypatch.setenv(\"REPOS_ROOT\", str(tmp_path))\n    assert S.settings().repos.root_for(\"MyRepo\") == (tmp_path / \"myrepo\").resolve()\n    assert S.settings().repos.root_for(\"other\") is None\n\n\ndef test_knobs_have_no_secrets_and_use_env_names(monkeypatch):\n    monkeypatch.setenv(\"ORCH_API_KEY\", \"topsecret\")\n    k = S.settings().knobs()\n    assert \"REVIEW_MAX_FINDINGS\" in k and \"KNOWLEDGE_MAX_CHARS\" in k\n    assert \"ORCH_API_KEY\" not in k\n    assert \"topsecret\" not in repr(k)\n\n\ndef test_every_legacy_env_name_is_still_recognised():\n    \"\"\"\u7a0b\u5f0f\u88e1\u66fe\u7d93 getenv \u904e\u7684\u540d\u5b57\uff0cschema \u4e00\u500b\u90fd\u4e0d\u80fd\u6f0f\u3002\"\"\"\n    legacy = {\n        \"ADO_PAT\", \"ADO_VERIFY_SSL\", \"ADO_DIFF_MAX_FILES\", \"ADO_DIFF_MAX_FILE_BYTES\",\n        \"ADO_DIFF_FETCH_CONCURRENCY\", \"DRY_RUN\", \"KNOWLEDGE_POST\",\n        \"REPO_SYNC_INTERVAL_MIN\", \"HARVEST_INTERVAL_MIN\", \"REPO_SYNC_GRAPH_REBUILD\",\n        \"LLM_BASE_URL\", \"LLM_API_KEY\", \"LLM_MODEL\", \"LLM_MODEL_ADVERSARY\",\n        \"LLM_MODEL_DIGEST\", \"LLM_TIMEOUT_S\", \"REVIEW_PIPELINE\", \"AUTO_POST\",\n        \"REVIEW_DEDUPE_TTL\", \"ORCH_API_KEY\", \"ORCH_URL\", \"REVIEW_MAX_DIMENSIONS\",\n        \"REVIEW_MAX_PARALLEL\", \"REVIEW_LLM_BASE_CONF\", \"REVIEW_MIN_CONFIDENCE\",\n        \"REVIEW_MAX_FINDINGS\", \"REVIEW_ADVERSARY\", \"ADVERSARY_CHUNK\",\n        \"REVIEWER_RULES_MAX_CHARS\", \"REVIEWER_SLICES_MAX_CHARS\",\n        \"REVIEWER_FILE_SLICE_MAX_CHARS\", \"STATIC_SEMGREP\", \"STATIC_RUFF\",\n        \"STATIC_TIMEOUT\", \"STATIC_MISSING_TEST\", \"REPOS_ROOT\",\n        \"CONTEXT_LINES\", \"CONTEXT_MAX_CHARS\", \"GRAPH_TOOLS_URL\", \"GRAPH_TOOL_BLAST\",\n        \"GRAPH_TOOL_BLAST_ARGS\", \"GRAPH_REPO\", \"RULES_ROOT\", \"RULES_SUBDIR\",\n        \"RULES_COMMON_DIR\", \"RULES_MAX_CHARS\", \"KNOWLEDGE_ROOT\", \"KNOWLEDGE_BRANCHES\",\n        \"KNOWLEDGE_MAX_CHARS\", \"DISTILL_DIFF_MAX_CHARS\", \"KNOWLEDGE_REDISTILL\",\n        \"KNOWLEDGE_CYCLE_SOURCE\", \"KNOWLEDGE_CYCLE_TARGET\", \"KNOWLEDGE_DIGEST\",\n        \"KNOWLEDGE_DIGEST_LLM\", \"KNOWLEDGE_DIGEST_MAX_FLAGS\",\n        \"KNOWLEDGE_RETIRE_ON_CONTRADICTION\", \"EVAL_KNOWLEDGE_ROOT\", \"EVAL_KNOWLEDGE_AB\",\n        \"EVAL_MIN_RECALL\", \"EVAL_MAX_NOISE\", \"EVAL_MAX_FORBIDDEN\",\n        \"EVAL_MIN_KNOWLEDGE_DELTA\", \"EVAL_MIN_DISTILL_SCORE\",\n    }\n    known = {n for _g, _c, _f, info in S.iter_fields() for n in S.env_names(info)}\n    assert legacy <= known, legacy - known\n\n\ndef test_example_round_trips_through_the_schema(monkeypatch):\n    \"\"\"\u7522\u751f\u7684 example \u6bcf\u4e00\u500b\u6b63\u540d\u51fa\u73fe\u4e00\u6b21\uff0c\u4e14\u628a\u5b83\u7576 env \u9935\u56de\u53bb\u53ef\u4ee5\u901a\u904e\u9a57\u8b49\u3002\"\"\"\n    text = S.example_text()\n    primary = [S.env_names(info)[0] for _g, _c, _f, info in S.iter_fields()]\n    for name in primary:\n        assert sum(1 for ln in text.splitlines()\n                   if ln.lstrip(\"# \").startswith(name + \"=\")) == 1, name\n    _clear_all(monkeypatch)\n    for ln in text.splitlines():\n        if ln and not ln.startswith(\"#\") and \"=\" in ln:\n            k, v = ln.split(\"=\", 1)\n            monkeypatch.setenv(k, v.strip(\"'\"))\n    s = S.settings()                       # \u4e0d\u5f97 raise\n    assert s.orchestrator.pipeline == \"v1\"\n    rows = S.show_rows(s)\n    assert any(r[1] == \"ADO_PAT\" and r[3] == \"env:ADO_PAT\" for r in rows)  # \u5fc5\u586b\u6b04\u4f4d\u5728 example \u662f\u6253\u958b\u7684\n    secret = {\"ADO_PAT\", \"LLM_API_KEY\", \"ORCH_API_KEY\", \"LANGFUSE_SECRET_KEY\"}\n    assert all(\"changeme\" not in r[2] for r in rows if r[1] in secret)   # \u906e\u7f69\n\n\ndef test_warnings_catch_config_smells(tmp_path, monkeypatch):\n    _clear_all(monkeypatch)\n    monkeypatch.setenv(\"AUTO_POST\", \"true\")\n    monkeypatch.setenv(\"KNOWLEDGE_ROOT\", str(tmp_path / \"missing\"))\n    monkeypatch.setenv(\"GRAPH_TOOLS_URL\", \"http://127.0.0.1:8097/mcp\")\n    monkeypatch.setenv(\"PORT\", \"8094\")\n    w = \"\\n\".join(S.warnings_for())\n    assert \"DRY_RUN=true\" in w and \"KNOWLEDGE_ROOT\" in w\n    assert \"GRAPH_TOOL_BLAST\" in w and \"PORT\" in w and \"\u5df2\u7121\u4f5c\u7528\" in w\n\n\ndef test_fail_fast_exits_with_readable_message(monkeypatch, capsys):\n    monkeypatch.setenv(\"REVIEW_MIN_CONFIDENCE\", \"1.5\")\n    with pytest.raises(SystemExit) as ex:\n        S.fail_fast()\n    assert ex.value.code == 1\n    assert \"REVIEW_MIN_CONFIDENCE\" in capsys.readouterr().err\n"}
{"path":"tests/test_store_sources.py","perm":"0644","sha":"2750c0ba636d592d598e43e70179d6bd4032926a304f955895ce3f3e19082401","data":"\"\"\"S3 \u7684\u9396\uff1areview \u6b77\u53f2\uff08SQLite\uff09\u3001\u4e09\u500b source \u7684\u72c0\u614b\u8207\u9810\u89bd\u3001\u63a7\u5236\u53f0 Sources / Reviews \u9801\u3002\u5168\u96e2\u7dda\u3002\"\"\"\nimport asyncio\nimport os\nimport subprocess\nimport time\n\nimport pytest\nfrom fastapi.testclient import TestClient\n\nimport orchestrator.sources as SRC\nimport orchestrator.store as ST\nimport shared.doctor as D\nfrom orchestrator.models import Finding, ReviewResult\n\n\n# ---------- store ----------\n\ndef test_store_records_lifecycle_and_summary(tmp_path, monkeypatch):\n    monkeypatch.setenv(\"DATA_DIR\", str(tmp_path / \"d\"))\n    rid = ST.start_review(\"https://x/C/P/_git/Repo/pullrequest/7\", \"u\")\n    assert rid and ST.get_review(rid)[\"status\"] == \"running\"\n    ST.set_title(rid, \"Fix TTL\")\n    res = ReviewResult(markdown=\"# ok\", findings=[\n        Finding(rule=\"BUG\", file=\"a.py\", line=1, severity=\"error\", note=\"x\"),\n        Finding(rule=\"NAMING\", file=\"a.py\", line=2, severity=\"info\", note=\"y\")],\n        stats={\"pipeline\": \"v2\", \"files\": 1, \"rules_files\": [\"rules/common/a.md\"]})\n    ST.finish_review(rid, res, trace_id=\"t1\")\n    r = ST.get_review(rid)\n    assert r[\"status\"] == \"done\" and r[\"title\"] == \"Fix TTL\" and r[\"repo\"] == \"Repo\" and r[\"pr_id\"] == 7\n    assert (r[\"n_error\"], r[\"n_warning\"], r[\"n_info\"]) == (1, 0, 1)\n    assert r[\"findings\"][0][\"rule\"] == \"BUG\" and r[\"stats\"][\"rules_files\"] == [\"rules/common/a.md\"]\n    assert r[\"trace_id\"] == \"t1\" and r[\"duration\"] is not None\n    rid2 = ST.start_review(\"https://x/C/P/_git/Repo/pullrequest/8\", \"u\")\n    ST.fail_review(rid2, \"RuntimeError: boom\")\n    rows = ST.list_reviews()\n    assert [x[\"status\"] for x in rows] == [\"error\", \"done\"] and \"findings\" not in rows[0]\n    s = ST.summary(7)\n    assert s[\"n\"] == 2 and s[\"errors\"] == 1 and s[\"avg_findings\"] == 2.0 or s[\"avg_findings\"] in (1.0, 2.0)\n    assert ST.enabled()\n\n\ndef test_store_degrades_when_data_dir_is_unwritable(tmp_path, monkeypatch):\n    blocker = tmp_path / \"file\"\n    blocker.write_text(\"x\", encoding=\"utf-8\")\n    monkeypatch.setenv(\"DATA_DIR\", str(blocker / \"sub\"))        # \u7236\u8def\u5f91\u662f\u6a94\u6848 \u2192 mkdir \u5931\u6557\n    assert ST.start_review(\"https://x/C/P/_git/R/pullrequest/1\", \"u\") is None\n    ST.finish_review(None, ReviewResult(markdown=\"\", findings=[], stats={}))   # \u4e0d\u70b8\n    assert ST.list_reviews() == [] and not ST.enabled() and \"sub\" in ST.disabled_reason()\n\n\ndef test_handle_review_records_even_when_pipeline_fails(monkeypatch):\n    import orchestrator.app as A\n\n    async def f_meta(u):\n        return {\"repo\": \"r\", \"title\": \"T\"}\n\n    async def f_diff(u):\n        raise RuntimeError(\"ado down\")\n    monkeypatch.setattr(A.clients, \"fetch_pr_metadata\", f_meta)\n    monkeypatch.setattr(A.clients, \"fetch_pr_diff\", f_diff)\n    with pytest.raises(RuntimeError):\n        asyncio.run(A.handle_review(\"https://x/C/P/_git/r/pullrequest/3\", \"u\"))\n    rows = ST.list_reviews()\n    assert rows[0][\"status\"] == \"error\" and \"ado down\" in rows[0][\"error\"] and rows[0][\"title\"] == \"T\"\n\n\n# ---------- sources ----------\n\ndef _git(*args, cwd):\n    subprocess.run([\"git\", *args], cwd=str(cwd), check=True, capture_output=True,\n                   env={**os.environ, \"GIT_AUTHOR_NAME\": \"t\", \"GIT_AUTHOR_EMAIL\": \"t@x\",\n                        \"GIT_COMMITTER_NAME\": \"t\", \"GIT_COMMITTER_EMAIL\": \"t@x\"})\n\n\n@pytest.fixture\ndef roots(tmp_path, monkeypatch):\n    repos = tmp_path / \"repos\"; (repos / \"svc\").mkdir(parents=True)\n    _git(\"init\", \"-q\", \"-b\", \"main\", cwd=repos / \"svc\")\n    (repos / \"svc\" / \"a\").write_text(\"1\", encoding=\"utf-8\")\n    _git(\"add\", \".\", cwd=repos / \"svc\"); _git(\"commit\", \"-qm\", \"one\", cwd=repos / \"svc\")\n    (repos / \"junk\").mkdir()\n    rules = tmp_path / \"rules\"; (rules / \"rules\" / \"common\").mkdir(parents=True)\n    (rules / \"rules\" / \"svc\").mkdir()\n    (rules / \"rules\" / \"common\" / \"naming.md\").write_text(\"# naming\\nbe clear\", encoding=\"utf-8\")\n    (rules / \"rules\" / \"svc\" / \"db.md\").write_text(\"# db\\nno raw sql\", encoding=\"utf-8\")\n    (rules / \"semgrep\").mkdir(); (rules / \"semgrep\" / \"x.semgrep.yml\").write_text(\"rules: []\", encoding=\"utf-8\")\n    know = tmp_path / \"know\"; (know / \"svc\" / \"cache\").mkdir(parents=True)\n    (know / \"svc\" / \"cache\" / \"SessionCache.md\").write_text(\n        \"# SessionCache\\n> entity: cache/SessionCache.java\\n\\n## Invariants\\n- ttl is seconds `PR1-I1`\\n- ~~old~~ `PR1-I2`\\n\",\n        encoding=\"utf-8\")\n    (know / \"_pending\" / \"svc\").mkdir(parents=True)\n    (know / \"_pending\" / \"svc\" / \"pr-9.json\").write_text(\"{}\", encoding=\"utf-8\")\n    monkeypatch.setenv(\"REPOS_ROOT\", str(repos)); monkeypatch.setenv(\"RULES_ROOT\", str(rules))\n    monkeypatch.setenv(\"KNOWLEDGE_ROOT\", str(know))\n    return tmp_path\n\n\ndef test_source_views_report_counts_and_heads(roots):\n    v = SRC.all_views()\n    assert v[\"repos\"].counts == {\"clones\": 1, \"others\": 1}\n    svc = next(i for i in v[\"repos\"].items if i[\"name\"] == \"svc\")\n    assert svc[\"branch\"] == \"main\" and svc[\"sha\"] and svc[\"dirty\"] is False\n    assert v[\"rules\"].counts == {\"md\": 2, \"semgrep\": 1, \"common\": 1, \"repos\": 1}\n    assert v[\"knowledge\"].counts[\"pages\"] == 1 and v[\"knowledge\"].counts[\"pending\"] == 1\n    assert v[\"knowledge\"].items[0][\"invariants\"] == 2 and v[\"knowledge\"].items[0][\"retired\"] == 1\n    assert v[\"knowledge\"].head.get(\"error\")                      # \u4e0d\u662f git repo\uff1a\u5982\u5be6\u56de\u5831\n\n\ndef test_previews_call_the_real_loaders(roots):\n    rp = SRC.rules_preview(\"svc\")\n    assert rp[\"loaded\"] and rp[\"files\"] == [\"rules/common/naming.md\", \"rules/svc/db.md\"]\n    assert SRC.rules_preview(\"other\")[\"files\"] == [\"rules/common/naming.md\"]\n    kp = SRC.knowledge_preview(\"svc\", [\"src/cache/SessionCache.java\"])\n    assert kp[\"stats\"][\"knowledge_entries\"] == 1 and \"PR1-I1\" in kp[\"text\"] and \"PR1-I2\" not in kp[\"text\"]\n    assert SRC.knowledge_preview(\"svc\", [\"src/other/X.java\"])[\"stats\"][\"knowledge_entries\"] == 0\n\n\ndef test_source_views_when_unset_or_missing(tmp_path, monkeypatch):\n    for n in (\"REPOS_ROOT\", \"RULES_ROOT\", \"KNOWLEDGE_ROOT\"):\n        monkeypatch.delenv(n, raising=False)\n    v = SRC.all_views()\n    assert all(not x.exists and \"\u672a\u8a2d\" in x.note for x in v.values())\n    monkeypatch.setenv(\"RULES_ROOT\", str(tmp_path / \"nope\"))\n    assert \"\u4e0d\u5b58\u5728\" in SRC.rules_view().note\n\n\ndef test_add_repo_validates_before_touching_git(roots, tmp_path, monkeypatch):\n    assert \"\u4e0d\u5408\u6cd5\" in SRC.add_repo(\"Bad Name\", \"https://x\", \"main\")[0]      # \u4e0d\u5408\u6cd5\n    assert \"http(s)\" in SRC.add_repo(\"ok\", \"git@x:y\", \"main\")[0]\n    assert \"\u5df2\u5b58\u5728\" in SRC.add_repo(\"svc\", \"https://x/y\", \"main\")[0]        # \u5df2\u5b58\u5728\n    monkeypatch.setenv(\"ADO_PAT\", \"\")\n    assert \"clone \u5931\u6557\" in SRC.add_repo(\"newone\", \"https://127.0.0.1:9/no/_git/x\", \"main\")[0]\n    assert not (roots / \"repos\" / \"newone\").exists()\n\n\n# ---------- console pages ----------\n\n@pytest.fixture\ndef client(roots, monkeypatch):\n    monkeypatch.setenv(\"ADO_PAT\", \"pat\")\n    monkeypatch.setattr(D, \"_tcp_open\", lambda h, p, timeout=0: True)\n    monkeypatch.setattr(D, \"_http_get\", lambda url, **kw: (200, {\"ok\": True, \"jobs\": {}}, \"\"))\n    monkeypatch.setattr(D, \"_which\", lambda b: None)\n    monkeypatch.setattr(D, \"_run\", lambda cmd, timeout=0: (0, \"\"))\n    import orchestrator.app as A\n    import orchestrator.console.router as R\n    R._doctor_cache.update(ts=0.0, checks=[])\n    with TestClient(A.app) as c:\n        yield c\n\n\ndef test_sources_page_and_previews(client):\n    r = client.get(\"/console/sources\")\n    assert r.status_code == 200 and \"svc\" in r.text and \"naming.md\" in r.text and \"SessionCache.md\" in r.text\n    r = client.get(\"/console/sources\", params={\"rules_repo\": \"svc\"})\n    assert \"rules/svc/db.md\" in r.text and \"\u8f09\u5165 2 \u6a94\" in r.text\n    r = client.get(\"/console/sources\", params={\"k_repo\": \"svc\", \"k_paths\": \"src/cache/SessionCache.java\"})\n    assert \"1 \u689d\u76ee\" in r.text and \"PR1-I1\" in r.text\n\n\ndef test_overview_shows_sources_and_recent_reviews(client):\n    rid = ST.start_review(\"https://x/C/P/_git/svc/pullrequest/5\", \"u\")\n    ST.finish_review(rid, ReviewResult(markdown=\"m\", findings=[], stats={\"pipeline\": \"v2\"}))\n    r = client.get(\"/console\")\n    assert \"svc#5\" in r.text and \"1 \u9846 clone\" in r.text and \"2 \u689d\u898f\u5247\" in r.text\n    assert \"\u6d3b\u52d5\u7d00\u9304\" in r.text and \"\u5f85\u8655\u7406\u9805\u76ee\" in r.text\n\n\ndef test_reviews_pages_and_run_form(client, monkeypatch):\n    import orchestrator.app as A\n    r = client.get(\"/console/reviews\")\n    assert r.status_code == 200 and \"\u5c1a\u7121 review \u8a18\u9304\" in r.text\n    r = client.post(\"/console/reviews/run\", data={\"pr_url\": \"not a url\"}, follow_redirects=False)\n    assert r.status_code == 303 and \"error=\" in r.headers[\"location\"]\n\n    async def fake(url, user, on_status=None):\n        rid = ST.start_review(url, user)\n        ST.finish_review(rid, ReviewResult(markdown=\"# R\", findings=[\n            Finding(rule=\"SECURITY\", file=\"a.py\", line=3, severity=\"error\", note=\"inj\")],\n            stats={\"pipeline\": \"v2\", \"files\": 1, \"dimension_names\": [\"Security\"]}))\n    monkeypatch.setattr(A, \"handle_review\", fake)\n    r = client.post(\"/console/reviews/run\", data={\"pr_url\": \"see https://x/C/P/_git/svc/pullrequest/11 pls\"},\n                    follow_redirects=False)\n    assert r.status_code == 303\n    time.sleep(0.3)\n    rows = ST.list_reviews()\n    assert rows and rows[0][\"pr_id\"] == 11 and rows[0][\"user\"] == \"console\"\n    r = client.get(f\"/console/reviews/{rows[0]['id']}\")\n    assert r.status_code == 200 and \"SECURITY\" in r.text and \"Security\" in r.text and \"# R\" in r.text\n    assert client.get(\"/console/reviews/9999\").status_code == 404\n"}
"""
FILES = [json.loads(ln) for ln in PAYLOAD.splitlines() if ln.strip()]

def digest(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()

if mode == "list":
    for f in FILES:
        print("%s  %7d  %s" % (f["sha"][:12], len(f["data"].encode("utf-8")), f["path"]))
    print("%d files" % len(FILES))
    sys.exit(0)

bad = [f["path"] for f in FILES if digest(f["data"]) != f["sha"]]
if bad:
    print("payload corrupted: " + ", ".join(bad), file=sys.stderr)
    sys.exit(1)
if mode == "verify":
    print("payload ok: %d files" % len(FILES))
    sys.exit(0)

root = os.path.abspath(target)
stamp = time.strftime("%Y%m%d-%H%M%S")
backup = os.path.join(root, ".backup-" + stamp)
written = unchanged = backed = 0
for f in FILES:
    dst = os.path.join(root, f["path"])
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    blob = f["data"].encode("utf-8")
    if os.path.exists(dst):
        with open(dst, "rb") as fh:
            if fh.read() == blob:
                unchanged += 1
                continue
        bdst = os.path.join(backup, f["path"])
        os.makedirs(os.path.dirname(bdst), exist_ok=True)
        shutil.copy2(dst, bdst)
        backed += 1
    with open(dst, "wb") as fh:
        fh.write(blob)
    os.chmod(dst, int(f["perm"], 8))
    with open(dst, "rb") as fh:
        if hashlib.sha256(fh.read()).hexdigest() != f["sha"]:
            print("write verification failed: " + f["path"], file=sys.stderr)
            sys.exit(1)
    written += 1
print("files: %d written, %d unchanged, %d backed up%s" % (
    written, unchanged, backed, (" to " + backup) if backed else ""))
PY_BUNDLE_EOF

if [ "$MODE" != "install" ]; then exit 0; fi

cd "$TARGET"
if [ "$NO_PIP" = 1 ]; then
  echo "skipped venv/pip (--no-pip)"
  exit 0
fi
if [ ! -x venv/bin/pip ] && [ ! -x venv/Scripts/pip.exe ]; then
  echo "creating venv"
  "$PY" -m venv venv
fi
if [ -x venv/bin/pip ]; then VPIP=venv/bin/pip; VPY=venv/bin/python; else VPIP=venv/Scripts/pip.exe; VPY=venv/Scripts/python.exe; fi
echo "installing requirements"
"$VPIP" install -q -r requirements.txt
if [ "$WITH_STATIC" = 1 ]; then "$VPIP" install -q semgrep ruff; fi
"$VPY" -m shared.settings --check || true
if [ "$SYSTEM" = 1 ]; then
  "$VPY" -m shared.install --prefix "$TARGET"
else
  echo
  echo "next:"
  echo "  1. (as root) $VPY -m shared.install --prefix $TARGET   # /etc config, /var data, systemd unit"
  echo "  2. edit /etc/pr-review-suite/secrets.env, then: systemctl enable --now review-orchestrator"
  echo "  3. open http://<host>:8080/console/setup"
fi
